void requireUnaryTransformOperandIdentity() {
  auto first = std::make_unique<SgTemplateType>(SgName("T"));
  auto second = std::make_unique<SgTemplateType>(SgName("T"));
  ROSE_ASSERT(first->get_mangled() == second->get_mangled());
  auto *first_type = SgUnaryTransformType::createType(
      first.get(), SgUnaryTransformType::e_enum_underlying_type);
  auto *second_type = SgUnaryTransformType::createType(
      second.get(), SgUnaryTransformType::e_enum_underlying_type);
  ROSE_ASSERT(first_type != second_type);
  ROSE_ASSERT(first_type->get_operand_type() == first.get());
  ROSE_ASSERT(second_type->get_operand_type() == second.get());
  ROSE_ASSERT(SgUnaryTransformType::createType(
                  second.get(), SgUnaryTransformType::e_enum_underlying_type) ==
              second_type);
  delete first_type;
  delete second_type;
}

void requireReferenceTypeConstructionIdentity() {
  using namespace Rose::AstJson;
  {
    auto *file =
        SageBuilder::buildGeneratedSourceFile("rex_implicit_binding.c");
    std::unique_ptr<SgProject, DeleteFixtureAst> project(file->get_project());
    auto *scope = file->get_globalScope();
    auto *signature = SageBuilder::buildFunctionType(
        SageBuilder::buildIntType(), new SgFunctionParameterTypeList(), false);
    const auto declaration = [&](const char *name) {
      auto *function = SageBuilder::buildNondefiningFunctionDeclaration(
          SageBuilder::function_declaration_ownership::semanticAuxiliary()
              .withFunctionType(signature),
          name, SageBuilder::buildIntType(),
          SageBuilder::buildFunctionParameterList_nfi(), scope);
      function->set_is_implicit_function(true);
      return function;
    };
    auto *implicit = declaration("rex_implicit_binding");
    auto *symbol =
        isSgFunctionSymbol(scope->find_symbol_from_declaration(implicit));
    ROSE_ASSERT(symbol != nullptr);
    std::unique_ptr<SgFunctionRefExp, DeleteFixtureAst> source(
        SageBuilder::buildFunctionRefExp_nfi(symbol, signature));
    source->set_c_implicit_declaration(implicit);
    SageBuilder::initializeSemanticExpressionSourceProvenance(source.get());
    const NodeMap nodes{{1, implicit}, {2, scope}};
    const std::unordered_map<const SgNode *, uint64_t> ids{{implicit, 1},
                                                           {scope, 2}};
    auto properties = parseJson(rawNodeProperties(source.get(), ids));
    std::unique_ptr<SgFunctionRefExp, DeleteFixtureAst> restored(
        functionReferenceFromProperties(properties, nodes));
    ROSE_ASSERT(restored->get_c_implicit_declaration() == implicit);
    std::unique_ptr<SgFunctionRefExp, DeleteFixtureAst> inline_restored(
        isSgFunctionRefExp(expressionFromRef(
            parseJson(rawTypeOwnedExpressionRef(source.get(), ids)), nodes)));
    ROSE_ASSERT(inline_restored != nullptr &&
                inline_restored->get_c_implicit_declaration() == implicit);
    auto *copied_declaration = declaration("rex_implicit_binding_copy");
    auto *copied_symbol =
        scope->find_symbol_from_declaration(copied_declaration);
    NodeMap malformed_nodes = nodes;
    malformed_nodes.emplace(3, copied_declaration);
    for (const char *value : {"", "null", "-1", "2", "3", "4"}) {
      auto malformed = properties;
      if (*value == '\0')
        malformed.object.erase("c_implicit_declaration");
      else
        malformed.object.at("c_implicit_declaration") = parseJson(value);
      const auto references = SgFunctionRefExp::numberOfNodes();
      const auto positions = Sg_File_Info::numberOfNodes();
      bool rejected = false;
      try {
        std::unique_ptr<SgFunctionRefExp, DeleteFixtureAst> invalid(
            functionReferenceFromProperties(malformed, malformed_nodes));
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected && SgFunctionRefExp::numberOfNodes() == references &&
                  Sg_File_Info::numberOfNodes() == positions);
    }
    SgTreeCopy copying;
    copying.insertCopiedNodePair(implicit, copied_declaration);
    copying.insertCopiedNodePair(symbol, copied_symbol);
    std::unique_ptr<SgFunctionRefExp, DeleteFixtureAst> copy(
        isSgFunctionRefExp(source->copy(copying)));
    ROSE_ASSERT(copy != nullptr && copy->get_symbol() == copied_symbol &&
                copy->get_c_implicit_declaration() == copied_declaration);
  }
  for (SgType *type :
       {static_cast<SgType *>(SageBuilder::buildIntType()),
        static_cast<SgType *>(SageBuilder::buildArrayType(
            SageBuilder::buildIntType(), SageBuilder::buildIntVal(3)))}) {
    std::unique_ptr<SgBasicBlock, DeleteFixtureAst> scope(
        SageBuilder::buildBasicBlock());
    auto *declaration = SageBuilder::buildVariableDeclaration(
        "rex_reference_type", type, nullptr, scope.get());
    scope->append_statement(declaration);
    auto *name = declaration->get_variables().front();
    auto *symbol =
        isSgVariableSymbol(scope->find_symbol_from_declaration(name));
    ROSE_ASSERT(symbol != nullptr);
    std::unique_ptr<SgVarRefExp, DeleteFixtureAst> source(
        SageBuilder::buildVarRefExp(symbol));
    const NodeMap nodes{{1, symbol}, {2, name}};
    const std::unordered_map<const SgNode *, uint64_t> ids{{symbol, 1},
                                                           {name, 2}};
    auto serialized = parseJson(rawTypeOwnedExpressionRef(source.get(), ids));
    std::unique_ptr<SgVarRefExp, DeleteFixtureAst> restored(
        isSgVarRefExp(expressionFromRef(serialized, nodes)));
    ROSE_ASSERT(restored != nullptr && restored->get_symbol() == symbol);
    ROSE_ASSERT(restored->get_type() == type);
    serialized.object.at("properties").object.at("type") =
        parseJson(rawTypeJson(SageBuilder::buildFloatType(), {}));
    const auto references = SgVarRefExp::numberOfNodes();
    const auto positions = Sg_File_Info::numberOfNodes();
    bool rejected = false;
    try {
      std::unique_ptr<SgExpression, DeleteFixtureAst> invalid(
          expressionFromRef(serialized, nodes));
    } catch (const std::runtime_error &error) {
      ROSE_ASSERT(std::string(error.what()).find("variable reference type") !=
                  std::string::npos);
      rejected = true;
    }
    ROSE_ASSERT(rejected && SgVarRefExp::numberOfNodes() == references);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  for (bool rvalue : {false, true}) {
    SgType *base = SageBuilder::buildIntType();
    SgType *reference =
        rvalue ? static_cast<SgType *>(SgRvalueReferenceType::createType(base))
               : SgReferenceType::createType(base);
    const auto type = parseJson(rawTypeJson(reference, {}));
    const size_t lvalues = SgReferenceType::numberOfNodes();
    const size_t rvalues = SgRvalueReferenceType::numberOfNodes();
    for (int repeat = 0; repeat != 100; ++repeat) {
      ROSE_ASSERT(typeFromJson(type, {}) == reference);
      ROSE_ASSERT(SgReferenceType::numberOfNodes() == lvalues);
      ROSE_ASSERT(SgRvalueReferenceType::numberOfNodes() == rvalues);
    }
    auto *original = new SgTypeExpression(reference);
    SageInterface::setOneSourcePositionNull(original);
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    const auto record = parseJson(rawTypeOwnedExpressionRef(original, {}));
    for (int repeat = 0; repeat != 100; ++repeat) {
      auto *restored = isSgTypeExpression(expressionFromRef(record, {}));
      ROSE_ASSERT(restored != nullptr);
      ROSE_ASSERT(restored->get_represented_type() == reference);
      SageInterface::deleteAST(restored);
    }
    SageInterface::deleteAST(original);
    SgType *wrong_base = SageBuilder::buildFloatType();
    SgType *wrong =
        rvalue ? static_cast<SgType *>(new SgRvalueReferenceType(wrong_base))
               : new SgReferenceType(wrong_base);
    if (rvalue)
      base->set_rvalue_ref_to(isSgRvalueReferenceType(wrong));
    else
      base->set_ref_to(isSgReferenceType(wrong));
    const size_t malformed_lvalues = SgReferenceType::numberOfNodes();
    const size_t malformed_rvalues = SgRvalueReferenceType::numberOfNodes();
    {
      bool rejected = false;
      try {
        (void)(typeFromJson(type, {}));
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgReferenceType::numberOfNodes() == malformed_lvalues);
      ROSE_ASSERT(SgRvalueReferenceType::numberOfNodes() == malformed_rvalues);
      ROSE_ASSERT((rvalue ? static_cast<SgType *>(base->get_rvalue_ref_to())
                          : base->get_ref_to()) == wrong);
    }
    if (rvalue)
      base->set_rvalue_ref_to(isSgRvalueReferenceType(reference));
    else
      base->set_ref_to(isSgReferenceType(reference));
    delete wrong;

    JsonValue source_type = type;
    source_type.object.at("fortran_source_syntax") = JsonValue::boolean(true);
    source_type.object["source_type_identity"] = JsonValue::number("1");
    const size_t floats = SgTypeFloat::numberOfNodes();
    for (int repeat = 0; repeat != 100; ++repeat) {
      bool rejected = false;
      try {
        (void)typeFromJson(source_type, {});
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgTypeFloat::numberOfNodes() == floats);
      ROSE_ASSERT(SgReferenceType::numberOfNodes() == lvalues);
      ROSE_ASSERT(SgRvalueReferenceType::numberOfNodes() == rvalues);
    }
  }
}

void requireFoldOperatorKinds() {
  using namespace Rose::AstJson;
  using Fold = SgFoldExpression;
  const std::pair<Fold::operator_kind_enum, const char *> operators[] = {
      {Fold::e_fold_add, "+"},
      {Fold::e_fold_subtract, "-"},
      {Fold::e_fold_multiply, "*"},
      {Fold::e_fold_divide, "/"},
      {Fold::e_fold_remainder, "%"},
      {Fold::e_fold_bit_xor, "^"},
      {Fold::e_fold_bit_and, "&"},
      {Fold::e_fold_bit_or, "|"},
      {Fold::e_fold_assign, "="},
      {Fold::e_fold_less, "<"},
      {Fold::e_fold_greater, ">"},
      {Fold::e_fold_shift_left, "<<"},
      {Fold::e_fold_shift_right, ">>"},
      {Fold::e_fold_add_assign, "+="},
      {Fold::e_fold_subtract_assign, "-="},
      {Fold::e_fold_multiply_assign, "*="},
      {Fold::e_fold_divide_assign, "/="},
      {Fold::e_fold_remainder_assign, "%="},
      {Fold::e_fold_xor_assign, "^="},
      {Fold::e_fold_and_assign, "&="},
      {Fold::e_fold_or_assign, "|="},
      {Fold::e_fold_shift_left_assign, "<<="},
      {Fold::e_fold_shift_right_assign, ">>="},
      {Fold::e_fold_equal, "=="},
      {Fold::e_fold_not_equal, "!="},
      {Fold::e_fold_less_equal, "<="},
      {Fold::e_fold_greater_equal, ">="},
      {Fold::e_fold_logical_and, "&&"},
      {Fold::e_fold_logical_or, "||"},
      {Fold::e_fold_comma, ","},
      {Fold::e_fold_member_pointer, ".*"},
      {Fold::e_fold_indirect_member_pointer, "->*"},
  };
  for (const auto &entry : operators) {
    ROSE_ASSERT(std::string(Fold::operator_token_for_kind(entry.first)) ==
                entry.second);
    const auto properties = parseJson(
        "{\"operator_kind\":" + std::to_string(static_cast<int>(entry.first)) +
        ",\"is_left_associative\":true}");
    const auto fields = foldConstructionFieldsFromJson(properties);
    ROSE_ASSERT(fields.operator_kind == entry.first &&
                fields.is_left_associative);
  }
  for (int invalid : {-1, 0, 33, 9999}) {
    bool rejected = false;
    try {
      (void)foldConstructionFieldsFromJson(
          parseJson("{\"operator_kind\":" + std::to_string(invalid) +
                    ",\"is_left_associative\":true}"));
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what()).find("invalid operator_kind enum value") !=
          std::string::npos;
    }
    ROSE_ASSERT(rejected);
  }
  bool rejected = false;
  try {
    (void)foldConstructionFieldsFromJson(
        parseJson(R"({"operator_token":"+","is_left_associative":true})"));
  } catch (const std::runtime_error &error) {
    rejected = std::string(error.what()).find("missing key: operator_kind") !=
               std::string::npos;
  }
  ROSE_ASSERT(rejected);
}

void requireAsmConstruction() {
  using namespace Rose::AstJson;
  for (bool output : {false, true}) {
    SgAsmOp::constraint_info constraint;
    constraint.spelling = output ? "+rm" : "n";
    constraint.allows_memory = output;
    constraint.allows_register = output;
    constraint.requires_immediate = !output;
    if (output)
      constraint.output_bounds = {0, std::numeric_limits<unsigned>::max()};
    else {
      constraint.immediate_range = {-128, 127};
      constraint.immediate_values = {-7, 17};
    }
    auto *expression = SageBuilder::buildIntVal(17);
    auto *original = new SgAsmOp(
        constraint, output ? SgAsmOp::e_modify : SgAsmOp::e_input, expression);
    expression->set_parent(original);
    original->set_name("value");
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    NodeRecord record;
    record.id = 1;
    record.kind = "SgAsmOp";
    record.flags = parseJson(rawNodeFlagsJson(original));
    record.location = parseJson(rawLocationJson(original));
    record.properties = parseJson(rawNodeProperties(original, {}));
    record.edges.push_back({"expression", 2, 0});
    NodeRecord child;
    child.id = 2;
    child.kind = "SgIntVal";
    child.edges.push_back({"parent", 1, 0});
    const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
    SageInterface::deleteAST(original);
    const size_t operands = SgAsmOp::numberOfNodes();
    const size_t expressions = SgIntVal::numberOfNodes();
    for (bool inline_reader : {false, true}) {
      SgAsmOp *restored = nullptr;
      if (inline_reader)
        restored = isSgAsmOp(expressionFromRef(owned, {}));
      else {
        AstFileRecord ast;
        ast.nodes = {child, record};
        ast.index_by_id = {{2, 0}, {1, 1}};
        NodeMap nodes{{2, SageBuilder::buildIntVal(17)}};
        rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
        restored = isSgAsmOp(nodes.at(1));
      }
      ROSE_ASSERT(restored != nullptr &&
                  restored->get_isOutputOperand() == output);
      ROSE_ASSERT(restored->get_expression()->get_parent() == restored);
      ROSE_ASSERT(parseJson(rawNodeProperties(restored, {}))
                      .exactlyEquals(record.properties));
      SageInterface::deleteAST(restored);
      for (int invalid = 0; invalid != 5; ++invalid) {
        auto malformed = owned;
        auto &properties = malformed.object.at("properties");
        auto &metadata = properties.object.at("asm_constraint");
        if (invalid == 0)
          metadata.object.erase("allows_memory");
        else if (invalid == 1)
          metadata.object.at("allows_register") = JsonValue::string("true");
        else if (invalid == 2)
          metadata.object.at("tied_output") = JsonValue::number("-2");
        else if (invalid == 3)
          metadata.object.at("immediate_values") = parseJson("[17,17]");
        else
          properties.object.at("asm_modifiers") = JsonValue::number("0");
        bool rejected = false;
        SgExpression *fresh = nullptr;
        try {
          if (inline_reader) {
            auto *unexpected = expressionFromRef(malformed, {});
            SageInterface::deleteAST(unexpected);
          } else {
            AstFileRecord ast;
            auto bad_record = record;
            bad_record.properties = properties;
            ast.nodes = {child, bad_record};
            ast.index_by_id = {{2, 0}, {1, 1}};
            fresh = SageBuilder::buildIntVal(17);
            NodeMap nodes{{2, fresh}};
            rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
          }
        } catch (const std::runtime_error &) {
          rejected = true;
        }
        ROSE_ASSERT(rejected);
        if (fresh != nullptr) {
          ROSE_ASSERT(fresh->get_parent() == nullptr);
          SageInterface::deleteAST(fresh);
        }
        ROSE_ASSERT(SgAsmOp::numberOfNodes() == operands);
        ROSE_ASSERT(SgIntVal::numberOfNodes() == expressions);
      }
    }
  }
}

void requireFoldConstruction() {
  using namespace Rose::AstJson;
  for (bool left : {false, true}) {
    auto *operand = SageBuilder::buildIntVal(7);
    auto *type = SageBuilder::buildDoubleType();
    auto *original =
        new SgFoldExpression(operand, SgFoldExpression::e_fold_add, left, type);
    ROSE_ASSERT(operand->get_parent() == original);
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    NodeRecord record;
    record.id = 1;
    record.kind = "SgFoldExpression";
    record.flags = parseJson(rawNodeFlagsJson(original));
    record.location = parseJson(rawLocationJson(original));
    record.properties =
        parseJson(rawNodeProperties(original, {{original, 1}, {operand, 2}}));
    record.edges.push_back({"operands", 2, 0});
    const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
    SageInterface::deleteAST(original);
    const auto folds = SgFoldExpression::numberOfNodes();
    for (int repeat = 0; repeat != 25; ++repeat) {
      auto *restored_owned = isSgFoldExpression(expressionFromRef(owned, {}));
      ROSE_ASSERT(restored_owned != nullptr &&
                  restored_owned->get_type() == type);
      ROSE_ASSERT(restored_owned->get_is_left_associative() == left);
      ROSE_ASSERT(restored_owned->get_operands()->get_parent() ==
                  restored_owned);
      SageInterface::deleteAST(restored_owned);
      for (bool invalid_operator : {false, true}) {
        AstFileRecord ast;
        ast.nodes = {record};
        if (invalid_operator)
          ast.nodes[0].properties.object.at("operator_kind") = parseJson("0");
        auto *fresh = SageBuilder::buildIntVal(7);
        NodeMap nodes{{2, fresh}};
        NodeRecord child;
        child.id = 2;
        child.kind = "SgIntVal";
        child.edges.push_back({"parent", 1, 0});
        ast.nodes.push_back(child);
        if (repeat % 2)
          std::swap(ast.nodes[0], ast.nodes[1]);
        bool rejected = false;
        try {
          rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
        } catch (const std::runtime_error &error) {
          if (!invalid_operator ||
              std::string(error.what())
                      .find("invalid operator_kind enum value") ==
                  std::string::npos)
            throw;
          rejected = true;
        }
        if (invalid_operator) {
          ROSE_ASSERT(rejected && nodes.count(1) == 0 &&
                      fresh->get_parent() == nullptr);
          SageInterface::deleteAST(fresh);
        } else {
          auto *fold = isSgFoldExpression(nodes.at(1));
          ROSE_ASSERT(!rejected && fold != nullptr && fold->get_type() == type);
          ROSE_ASSERT(fold->get_operands() == fresh &&
                      fresh->get_parent() == fold);
          ROSE_ASSERT(fold->get_operator_kind() ==
                          SgFoldExpression::e_fold_add &&
                      fold->get_is_left_associative() == left);
          SageInterface::deleteAST(fold);
        }
        ROSE_ASSERT(SgFoldExpression::numberOfNodes() == folds);
      }
    }
  }
}

