void requirePackConstruction() {
  using namespace Rose::AstJson;
  auto *leaf = SageBuilder::buildIntVal(7);
  auto *inner_type = SageBuilder::buildDoubleType();
  auto *outer_type = SageBuilder::buildLongDoubleType();
  auto *inner = new SgPackExpansionExpr(leaf, inner_type);
  ROSE_ASSERT(leaf->get_parent() == inner);
  auto *outer = new SgPackExpansionExpr(inner, outer_type);
  ROSE_ASSERT(inner->get_parent() == outer);
  SageBuilder::initializeSemanticExpressionSourceProvenance(inner);
  SageBuilder::initializeSemanticExpressionSourceProvenance(outer);
  const std::unordered_map<const SgNode *, uint64_t> ids{
      {outer, 1}, {inner, 2}, {leaf, 3}};
  AstFileRecord ast;
  for (auto *pack : {outer, inner}) {
    NodeRecord record;
    record.id = ids.at(pack);
    record.kind = "SgPackExpansionExpr";
    record.flags = parseJson(rawNodeFlagsJson(pack));
    record.location = parseJson(rawLocationJson(pack));
    record.properties = parseJson(rawNodeProperties(pack, ids));
    record.edges.push_back(
        {"pattern_expression", ids.at(pack->get_pattern_expression()), 0});
    if (pack == inner)
      record.edges.push_back({"parent", 1, 0});
    ast.nodes.push_back(record);
  }
  NodeRecord child;
  child.id = 3;
  child.kind = "SgIntVal";
  child.edges.push_back({"parent", 2, 0});
  ast.nodes.push_back(child);
  const auto owned = parseJson(rawTypeOwnedExpressionRef(outer, {}));
  SageInterface::deleteAST(outer);
  const auto count = SgPackExpansionExpr::numberOfNodes();
  for (int repeat = 0; repeat != 25; ++repeat) {
    auto *owned_outer = isSgPackExpansionExpr(expressionFromRef(owned, {}));
    ROSE_ASSERT(owned_outer != nullptr &&
                owned_outer->get_type() == outer_type);
    auto *owned_inner =
        isSgPackExpansionExpr(owned_outer->get_pattern_expression());
    ROSE_ASSERT(owned_inner != nullptr &&
                owned_inner->get_type() == inner_type);
    ROSE_ASSERT(owned_inner->get_parent() == owned_outer);
    SageInterface::deleteAST(owned_outer);
    auto *fresh = SageBuilder::buildIntVal(7);
    NodeMap nodes{{3, fresh}};
    rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    auto *restored_outer = isSgPackExpansionExpr(nodes.at(1));
    auto *restored_inner = isSgPackExpansionExpr(nodes.at(2));
    ROSE_ASSERT(restored_outer->get_pattern_expression() == restored_inner);
    ROSE_ASSERT(restored_inner->get_pattern_expression() == fresh);
    ROSE_ASSERT(restored_inner->get_parent() == restored_outer &&
                fresh->get_parent() == restored_inner);
    ROSE_ASSERT(restored_outer->get_type() == outer_type &&
                restored_inner->get_type() == inner_type);
    SageInterface::deleteAST(restored_outer);
    AstFileRecord missing;
    missing.nodes = {ast.nodes[0]};
    missing.nodes[0].edges.clear();
    NodeMap empty;
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph(missing.nodes), empty);
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what())
                     .find("missing required edge 'pattern_expression'") !=
                 std::string::npos;
    }
    ROSE_ASSERT(rejected && empty.empty());
    ROSE_ASSERT(SgPackExpansionExpr::numberOfNodes() == count);
    std::swap(ast.nodes[0], ast.nodes[1]);
  }
}

void requireOperandRequirementConstruction() {
  using namespace Rose::AstJson;
  for (const auto kind :
       {OperandRequirementKind::simple, OperandRequirementKind::compound,
        OperandRequirementKind::nested}) {
    auto *operand = SageBuilder::buildBoolValExp(true);
    auto *original = constructOperandRequirement(
        kind, operand, nullptr, kind == OperandRequirementKind::compound);
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    const char *field =
        kind == OperandRequirementKind::nested ? "constraint" : "expression";
    NodeRecord record;
    record.id = 1;
    record.kind = original->sage_class_name();
    record.flags = parseJson(rawNodeFlagsJson(original));
    record.location = parseJson(rawLocationJson(original));
    record.properties =
        parseJson(rawNodeProperties(original, {{original, 1}, {operand, 2}}));
    record.edges = {{field, 2, 0}};
    NodeRecord child;
    child.id = 2;
    child.kind = operand->sage_class_name();
    child.edges = {{"parent", 1, 0}};
    const auto owned_operand =
        parseJson(rawTypeOwnedExpressionRef(operand, {}));
    const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
    SageInterface::deleteAST(original);
    const auto count = [] {
      return SgSimpleRequirement::numberOfNodes() +
             SgCompoundRequirement::numberOfNodes() +
             SgNestedRequirement::numberOfNodes();
    };
    const auto baseline = count();
    for (bool inline_type : {false, true}) {
      SgExpression *restored = nullptr;
      SgExpression *graph_operand = nullptr;
      if (inline_type) {
        restored = expressionFromRef(owned, {});
      } else {
        AstFileRecord ast;
        ast.nodes = {record, child};
        NodeMap nodes;
        graph_operand = expressionFromRef(owned_operand, {});
        nodes.emplace(2, graph_operand);
        rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
        restored = isSgExpression(nodes.at(1));
      }
      ROSE_ASSERT(restored != nullptr &&
                  restored->sage_class_name() == record.kind);
      SgExpression *restored_operand = nullptr;
      if (auto *simple = isSgSimpleRequirement(restored))
        restored_operand = simple->get_expression();
      else if (auto *compound = isSgCompoundRequirement(restored)) {
        restored_operand = compound->get_expression();
        ROSE_ASSERT(compound->get_noexcept_required() &&
                    compound->get_type_constraint() == nullptr);
      } else
        restored_operand = isSgNestedRequirement(restored)->get_constraint();
      ROSE_ASSERT(restored_operand != nullptr &&
                  restored_operand->get_parent() == restored);
      ROSE_ASSERT(inline_type || restored_operand == graph_operand);
      ROSE_ASSERT(isSgBoolValExp(restored_operand)->get_value());
      SageInterface::deleteAST(restored);
      ROSE_ASSERT(count() == baseline);

      bool rejected = false;
      try {
        if (inline_type) {
          auto bad = owned;
          bad.object.at("properties").object.at(field) =
              parseJson(R"({"node":0})");
          (void)expressionFromRef(bad, {});
        } else {
          auto bad = record;
          bad.edges.clear();
          AstFileRecord ast;
          ast.nodes = {bad};
          NodeMap nodes;
          rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
        }
      } catch (const std::runtime_error &error) {
        const std::string expected =
            inline_type
                ? "requirement needs exact exclusive constructor-time operands"
                : std::string("missing required edge '") + field + "'";
        if (std::string(error.what()).find(expected) == std::string::npos)
          throw;
        rejected = true;
      }
      ROSE_ASSERT(rejected && count() == baseline);
    }
  }
}

void requireTypeRequirementConstruction() {
  using namespace Rose::AstJson;
  SgType *type = SageBuilder::buildIntType();
  auto *original = SageBuilder::buildTypeRequirement_nfi(type);
  SageBuilder::initializeSemanticExpressionSourceProvenance(original);
  NodeRecord record;
  record.id = 1;
  record.kind = "SgTypeRequirement";
  record.flags = parseJson(rawNodeFlagsJson(original));
  record.location = parseJson(rawLocationJson(original));
  record.properties = parseJson(rawNodeProperties(original, {{original, 1}}));
  const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
  SageInterface::deleteAST(original);
  const size_t count = SgTypeRequirement::numberOfNodes();
  for (bool inline_type : {false, true}) {
    SgTypeRequirement *restored = nullptr;
    if (inline_type) {
      restored = isSgTypeRequirement(expressionFromRef(owned, {}));
    } else {
      AstFileRecord ast;
      ast.nodes = {record};
      NodeMap nodes;
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      restored = isSgTypeRequirement(nodes.at(record.id));
    }
    ROSE_ASSERT(restored != nullptr && restored->get_required_type() == type);
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgTypeRequirement::numberOfNodes() == count);
    for (
        const char *bad_type :
        {"", R"({"present":false})",
         R"({"present":true,"kind":"SgTypeUnknown","fortran_source_syntax":false})",
         R"({"present":true,"kind":"SgTypeDefault","fortran_source_syntax":false})"}) {
      NodeRecord bad = record;
      if (*bad_type == '\0')
        bad.properties.object.erase("required_type");
      else
        bad.properties.object.at("required_type") = parseJson(bad_type);
      bool rejected = false;
      try {
        if (inline_type) {
          auto bad_owned = owned;
          bad_owned.object.at("properties") = bad.properties;
          (void)expressionFromRef(bad_owned, {});
        } else {
          AstFileRecord ast;
          ast.nodes = {bad};
          NodeMap nodes;
          rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
        }
      } catch (const std::runtime_error &error) {
        const std::string message = error.what();
        const char *expected =
            *bad_type == '\0' ? "missing key: required_type"
            : std::string(bad_type) == R"({"present":false})"
                ? "SgTypeRequirement has no exact required type"
                : "optional type requires an exact type";
        if (message.find(expected) == std::string::npos)
          throw;
        rejected = true;
      }
      ROSE_ASSERT(rejected && SgTypeRequirement::numberOfNodes() == count);
    }
  }
}

template <class Node, class Value>
void requireLiteralValueRange(const char *kind) {
  using namespace Rose::AstJson;
  constexpr int64_t minimum = std::numeric_limits<Value>::min();
  constexpr int64_t maximum = std::numeric_limits<Value>::max();
  auto original_storage =
      std::make_unique<Node>(static_cast<Sg_File_Info *>(nullptr), Value{});
  auto &original = *original_storage;
  SageBuilder::initializeSemanticExpressionSourceProvenance(&original);
  original.set_need_paren(true);
  original.set_semantic_wrapper_mask(
      SgExpression::e_constant_evaluated_wrapper);
  const auto count = Node::numberOfNodes();
  std::vector<int64_t> values{minimum, maximum};
  if constexpr (std::is_same_v<Node, SgCharVal> ||
                std::is_same_v<Node, SgWcharVal>) {
    values.push_back(-1);
    values.push_back(std::numeric_limits<uint32_t>::max());
  }
  if constexpr (minimum > std::numeric_limits<int64_t>::min())
    values.push_back(minimum - 1);
  if constexpr (maximum < std::numeric_limits<int64_t>::max())
    values.push_back(maximum + 1);
  for (int64_t value : values) {
    NodeRecord record;
    record.id = 1;
    record.kind = kind;
    record.flags = parseJson(rawNodeFlagsJson(&original));
    record.location = parseJson(rawLocationJson(&original));
    record.properties = parseJson(rawNodeProperties(&original, {}));
    record.properties.object.at("value") = parseJson(std::to_string(value));
    const bool valid = value >= minimum && value <= maximum;
    for (int reader = 0; reader != 3; ++reader) {
      bool rejected = false;
      try {
        SgNode *restored = nullptr;
        if (reader == 1) {
          NodeMap nodes;
          rebuildConstructorOnlyNodes(recordGraph({record}), nodes);
          restored = nodes.at(record.id);
        } else if (reader == 2) {
          auto owned = parseJson(rawTypeOwnedExpressionRef(&original, {}));
          owned.object.at("properties") = record.properties;
          restored = expressionFromRef(owned, {});
        } else {
          restored = createNodeFromRecord(record, nullptr);
        }
        ROSE_ASSERT(valid && restored->sage_class_name() == record.kind);
        ROSE_ASSERT(static_cast<int64_t>(
                        static_cast<Node *>(restored)->get_value()) == value);
        auto *expression = isSgExpression(restored);
        ROSE_ASSERT(expression->get_need_paren());
        ROSE_ASSERT(expression->get_semantic_wrapper_mask() ==
                    SgExpression::e_constant_evaluated_wrapper);
        if constexpr (std::is_same_v<Node, SgCharVal> ||
                      std::is_same_v<Node, SgWcharVal>) {
          auto *fixture = new Node(value, "");
          SageInterface::setOneSourcePositionNull(fixture);
          SageBuilder::initializeSemanticExpressionSourceProvenance(fixture);
          fixture->set_literal_type(SageBuilder::buildLongLongType());
          auto *copy = static_cast<Node *>(SageInterface::deepCopy(fixture));
          SageInterface::deleteAST(fixture);
          ROSE_ASSERT(copy != nullptr && copy->get_value() == value &&
                      copy->get_type() == SageBuilder::buildLongLongType());
          SageInterface::deleteAST(copy);
        }
        SageInterface::deleteAST(restored);
      } catch (const std::runtime_error &error) {
        const std::string expected =
            record.kind == "SgBoolValExp"
                ? "AST JSON boolean literal value is not 0 or 1"
                : "AST JSON integer literal value is out of range";
        if (valid || error.what() != expected)
          throw;
        rejected = true;
      }
      ROSE_ASSERT(rejected == !valid && Node::numberOfNodes() == count);
    }
  }
  for (int mutation = 0; mutation != 4; ++mutation) {
    NodeRecord record;
    record.kind = kind;
    record.flags = parseJson(rawNodeFlagsJson(&original));
    record.location = parseJson(rawLocationJson(&original));
    record.properties = parseJson(rawNodeProperties(&original, {}));
    record.properties.object.at("type") = JsonValue::objectValue({});
    if (mutation == 0)
      record.properties.object.erase("literal_spelling_form");
    else if (mutation == 1)
      record.properties.object.at("literal_spelling_form") =
          JsonValue::number("0");
    else if (mutation == 2)
      record.properties.object.erase("lvalue");
    else
      record.properties.object.at("fortran_integer_constant_value") =
          JsonValue::number("1");
    bool rejected = false;
    try {
      std::unique_ptr<SgNode> unexpected(createNodeFromRecord(record, nullptr));
    } catch (const std::runtime_error &error) {
      const char *expected =
          mutation == 0
              ? "AST JSON object is missing key: literal_spelling_form"
          : mutation == 1 ? "AST JSON SgValueExp has an invalid "
                            "literal_spelling_form enum value"
          : mutation == 2 ? "AST JSON object is missing key: lvalue"
                          : "AST JSON expression has a Fortran folded selector "
                            "value without availability";
      rejected = std::string(error.what()) == expected;
    }
    ROSE_ASSERT(rejected && Node::numberOfNodes() == count);
  }
}

template <class Node, class Value = float>
void requireFloatingLiteralRoundtrip(const char *kind) {
  using namespace Rose::AstJson;
  const std::vector<std::string> payloads =
      std::is_same_v<Value, float>
          ? std::vector<std::string>{"[0]", "[2147483648]", "[1067450368]",
                                     "[2139095040]", "[2143363909]"}
          : std::vector<std::string>{"[0,0]", "[0,2147483648]",
                                     "[0,1072955392]", "[0,2146435072]",
                                     "[74565,2146959360]"};
  for (const auto &payload : payloads) {
    const auto encoded = parseJson(payload);
    const Value value = floatingValueFromJson<Value>(encoded);
    std::unique_ptr<Node, DeleteFixtureAst> original(new Node(value, ""));
    SageInterface::setOneSourcePositionNull(original.get());
    SageBuilder::initializeSemanticExpressionSourceProvenance(original.get());
    const auto count = Node::numberOfNodes();
    const auto positions = Sg_File_Info::numberOfNodes();
    NodeRecord record;
    record.id = 1;
    record.kind = kind;
    record.flags = parseJson(rawNodeFlagsJson(original.get()));
    record.location = parseJson(rawLocationJson(original.get()));
    record.properties = parseJson(rawNodeProperties(original.get(), {}));
    const auto &words = record.properties.at("value_bits").array;
    ROSE_ASSERT(words.size() == encoded.array.size());
    for (size_t index = 0; index < words.size(); ++index)
      ROSE_ASSERT(words[index].asInt() == encoded.array[index].asInt());
    const auto owned = parseJson(rawTypeOwnedExpressionRef(original.get(), {}));
    for (int reader = 0; reader != 3; ++reader) {
      SgNode *restored = nullptr;
      if (reader == 0)
        restored = createNodeFromRecord(record, nullptr);
      else if (reader == 1) {
        NodeMap nodes;
        rebuildConstructorOnlyNodes(recordGraph({record}), nodes);
        restored = nodes.at(record.id);
      } else
        restored = expressionFromRef(owned, {});
      ROSE_ASSERT(restored->sage_class_name() == record.kind);
      const auto *literal = static_cast<Node *>(restored);
      ROSE_ASSERT(rawFloatingValueBits(literal->get_value()) == payload);
      ROSE_ASSERT(literal->get_literal_spelling_form() ==
                  original->get_literal_spelling_form());
      SageInterface::deleteAST(restored);
      ROSE_ASSERT(Node::numberOfNodes() == count);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
    const char *wrong_width = std::is_same_v<Value, float> ? "[1,2]" : "[1]";
    const char *negative = std::is_same_v<Value, float> ? "[-1]" : "[-1,0]";
    const char *overflow =
        std::is_same_v<Value, float> ? "[4294967296]" : "[4294967296,0]";
    for (const char *invalid : {"[]", wrong_width, negative, overflow}) {
      auto bad = record;
      bad.properties.object.at("value_bits") = parseJson(invalid);
      for (int reader = 0; reader != 3; ++reader) {
        bool rejected = false;
        try {
          if (reader == 0) {
            std::unique_ptr<SgNode, DeleteFixtureAst> unexpected(
                createNodeFromRecord(bad, nullptr));
          } else if (reader == 1) {
            NodeMap nodes;
            rebuildConstructorOnlyNodes(recordGraph({bad}), nodes);
          } else {
            auto bad_owned = owned;
            bad_owned.object.at("properties") = bad.properties;
            std::unique_ptr<SgNode, DeleteFixtureAst> unexpected(
                expressionFromRef(bad_owned, {}));
          }
        } catch (const std::runtime_error &error) {
          rejected =
              std::string(error.what()).find("AST JSON floating value_bits") ==
              0;
        }
        ROSE_ASSERT(rejected && Node::numberOfNodes() == count);
        ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
      }
    }
  }
}

void requireLiteralTypeConsistency() {
  using namespace Rose::AstJson;
  {
    std::unique_ptr<SgIntVal, DeleteFixtureAst> extent(new SgIntVal(4, ""));
    SageBuilder::initializeSemanticExpressionSourceProvenance(extent.get());
    auto *source = SageBuilder::buildSizeOfOp_nfi(
        SageBuilder::buildIntType(), SageBuilder::buildUnsignedLongType());
    SageBuilder::initializeSemanticExpressionSourceProvenance(source);
    extent->set_originalExpressionTree(source);
    source->set_parent(extent.get());
    const auto encoded = parseJson(rawTypeOwnedExpressionRef(extent.get(), {}));
    std::unique_ptr<SgIntVal, DeleteFixtureAst> restored(
        isSgIntVal(expressionFromRef(encoded, {})));
    ROSE_ASSERT(restored != nullptr && restored->get_value() == 4);
    auto *written = isSgSizeOfOp(restored->get_originalExpressionTree());
    ROSE_ASSERT(written != nullptr && written != source &&
                written->get_parent() == restored.get() &&
                isSgTypeInt(written->get_operand_type()) != nullptr);
    const auto literals = SgIntVal::numberOfNodes();
    const auto operators = SgSizeOfOp::numberOfNodes();
    const auto positions = Sg_File_Info::numberOfNodes();
    for (int mutation = 0; mutation != 7; ++mutation) {
      auto malformed = encoded;
      if (mutation == 0)
        malformed.object.erase("original_expression");
      else if (mutation == 1)
        malformed.object.at("original_expression") = parseJson(R"({"node":7})");
      else if (mutation == 2)
        malformed.object.at("original_expression")
            .object.at("original_expression") =
            encoded.at("original_expression");
      else if (mutation == 3)
        malformed.object.at("original_expression") =
            parseJson(R"({"node":0,"original_expression":{"node":7}})");
      else if (mutation == 4)
        malformed.object.at("original_expression") =
            parseJson(R"({"node":7,"owned_kind":"SgIntVal"})");
      else {
        auto &properties = malformed.object.at("properties");
        if (mutation == 5)
          properties.object.erase("literal_spelling_form");
        else
          properties.object.at("literal_spelling_form") =
              JsonValue::number("0");
        properties.object.at("type") = JsonValue::objectValue({});
        malformed.object.at("original_expression") = JsonValue::objectValue({});
      }
      bool rejected = false;
      try {
        std::unique_ptr<SgExpression, DeleteFixtureAst> unexpected(
            expressionFromRef(malformed, {{7, source}}));
      } catch (const std::runtime_error &error) {
        const char *expected =
            mutation == 5   ? "missing key: literal_spelling_form"
            : mutation == 6 ? "invalid literal_spelling_form enum value"
            : mutation == 0 ? "missing key: original_expression"
            : mutation >= 3 ? "reference contains inline expression fields"
                            : "requires one unowned source tree";
        ROSE_ASSERT(std::string(error.what()).find(expected) !=
                    std::string::npos);
        rejected = true;
      }
      ROSE_ASSERT(rejected && SgIntVal::numberOfNodes() == literals &&
                  SgSizeOfOp::numberOfNodes() == operators &&
                  Sg_File_Info::numberOfNodes() == positions);
      ROSE_ASSERT(source->get_parent() == extent.get() &&
                  extent->get_originalExpressionTree() == source);
    }
  }
  {
    std::unique_ptr<SgIntVal, DeleteFixtureAst> original(
        SageBuilder::buildIntVal(1));
    auto *type = SageBuilder::buildIntType(SageBuilder::buildIntVal(8));
    original->set_literal_type(type);
    NodeRecord record;
    record.kind = "SgIntVal";
    record.flags = parseJson(rawNodeFlagsJson(original.get()));
    record.location = parseJson(rawLocationJson(original.get()));
    record.properties = parseJson(rawNodeProperties(original.get(), {}));
    const auto fields = validateSourcePositionRecord(record);
    auto positions = constructSourcePositions(fields);
    auto *start = positions.start.get();
    auto *end = positions.end.get();
    auto *operator_position = positions.operator_position.get();
    ASSERT_not_null(start);
    std::unique_ptr<SgIntVal, DeleteFixtureAst> restored(isSgIntVal(
        createNodeFromRecord(record, nullptr, {}, std::move(positions))));
    ROSE_ASSERT(restored && restored->get_type() == type);
    ROSE_ASSERT(restored->get_startOfConstruct() == start &&
                restored->get_endOfConstruct() == end &&
                restored->get_operatorPosition() == operator_position);
    ROSE_ASSERT(restored->get_literal_type() == type);
  }
  const auto count = SgIntVal::numberOfNodes();
  auto *original = new SgIntVal(1, "1");
  SageBuilder::initializeSemanticExpressionSourceProvenance(original);
  const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
  SageInterface::deleteAST(original);
  for (bool inline_type : {false, true}) {
    for (bool mismatched : {false, true}) {
      auto input = owned;
      auto &properties = input.object.at("properties");
      ROSE_ASSERT(!properties.requiredBool("has_literal_semantic_type"));
      if (mismatched)
        properties.object.at("type") =
            parseJson(rawTypeJson(SageBuilder::buildDoubleType(), {}));
      std::unique_ptr<SgNode> restored;
      bool rejected = false;
      try {
        if (inline_type) {
          restored.reset(expressionFromRef(input, {}));
        } else {
          NodeRecord record;
          record.id = 1;
          record.kind = "SgIntVal";
          record.flags = input.at("flags");
          record.location = input.at("location");
          record.properties = properties;
          restored.reset(createNodeFromRecord(record, nullptr));
          AstFileRecord ast;
          ast.nodes.push_back(record);
          ast.index_by_id.emplace(record.id, 0);
          validateReconstructedTypesAndSymbols(ast,
                                               {{record.id, restored.get()}});
        }
      } catch (const std::runtime_error &error) {
        if (std::string(error.what()) !=
            "AST JSON literal type disagrees with its intrinsic type")
          throw;
        rejected = true;
      }
      ROSE_ASSERT(rejected == mismatched);
      restored.reset();
      ROSE_ASSERT(SgIntVal::numberOfNodes() == count);
    }
  }
}

template <class Node, class Value> void requireUnsignedLiteralRoundtrip() {
  using namespace Rose::AstJson;
  const Value maximum = std::numeric_limits<Value>::max();
  const auto count = Node::numberOfNodes();
  for (Value value :
       {Value{0}, Value(maximum / 2), Value(maximum / 2 + 1), maximum}) {
    auto *original = new Node(value, "");
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    NodeRecord record;
    record.kind = original->sage_class_name();
    record.flags = parseJson(rawNodeFlagsJson(original));
    record.location = parseJson(rawLocationJson(original));
    record.properties = parseJson(rawNodeProperties(original, {}));
    const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
    SageInterface::deleteAST(original);
    for (bool inline_type : {false, true}) {
      SgNode *restored = inline_type ? expressionFromRef(owned, {})
                                     : createNodeFromRecord(record, nullptr);
      ROSE_ASSERT(restored->sage_class_name() == record.kind);
      ROSE_ASSERT(static_cast<Node *>(restored)->get_value() == value);
      SageInterface::deleteAST(restored);
      ROSE_ASSERT(Node::numberOfNodes() == count);
    }
  }
}

void requireNoexceptConstruction() {
  using namespace Rose::AstJson;
  auto *operand = SageBuilder::buildBoolValExp(true);
  auto *original = new SgNoexceptOp(operand);
  SageBuilder::initializeSemanticExpressionSourceProvenance(original);
  NodeRecord record;
  record.id = 1;
  record.kind = "SgNoexceptOp";
  record.flags = parseJson(rawNodeFlagsJson(original));
  record.location = parseJson(rawLocationJson(original));
  record.properties =
      parseJson(rawNodeProperties(original, {{original, 1}, {operand, 2}}));
  record.edges = {{"operand_expr", 2, 0}};
  NodeRecord child;
  child.id = 2;
  child.kind = operand->sage_class_name();
  child.edges = {{"parent", 1, 0}};
  const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
  const auto owned_operand = parseJson(rawTypeOwnedExpressionRef(operand, {}));
  SageInterface::deleteAST(original);
  const auto count = SgNoexceptOp::numberOfNodes();
  for (bool inline_type : {false, true}) {
    SgNoexceptOp *restored = nullptr;
    if (inline_type) {
      restored = isSgNoexceptOp(expressionFromRef(owned, {}));
    } else {
      AstFileRecord ast;
      ast.nodes = {record, child};
      NodeMap nodes{{2, expressionFromRef(owned_operand, {})}};
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      restored = isSgNoexceptOp(nodes.at(1));
      ROSE_ASSERT(restored->get_operand_expr() == nodes.at(2));
    }
    ROSE_ASSERT(restored != nullptr && isSgTypeBool(restored->get_type()));
    ROSE_ASSERT(restored->get_operand_expr()->get_parent() == restored);
    for (bool bad_type : {false, true}) {
      auto properties = record.properties;
      if (bad_type)
        properties.object.at("type") =
            parseJson(rawTypeJson(SageBuilder::buildIntType(), {}));
      bool rejected = false;
      try {
        std::unique_ptr<SgNoexceptOp> unexpected(noexceptFromProperties(
            properties, {}, restored->get_operand_expr()));
      } catch (const std::runtime_error &error) {
        const std::string expected =
            bad_type ? "AST JSON SgNoexceptOp result type is not exact bool"
                     : "AST JSON noexcept requires an exclusive operand";
        if (error.what() != expected)
          throw;
        rejected = true;
      }
      ROSE_ASSERT(rejected && SgNoexceptOp::numberOfNodes() == count + 1);
      ROSE_ASSERT(restored->get_operand_expr()->get_parent() == restored);
    }
    const auto vararg_count = SgVarArgOp::numberOfNodes();
    for (int invalid = 0; invalid != 3; ++invalid) {
      auto properties = record.properties;
      if (invalid == 2)
        properties.object.erase("type");
      bool rejected = false;
      try {
        std::unique_ptr<SgVarArgOp> unexpected(varArgFromProperties(
            properties, {},
            invalid == 0 ? nullptr : restored->get_operand_expr()));
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected && SgVarArgOp::numberOfNodes() == vararg_count);
      ROSE_ASSERT(restored->get_operand_expr()->get_parent() == restored);
    }
    if (inline_type) {
      auto *operand_copy = isSgExpression(
          SageInterface::deepCopySemanticSubtree(restored->get_operand_expr()));
      auto *vararg = SageBuilder::buildVarArgOp_nfi(
          operand_copy, SageBuilder::buildBoolType());
      SageBuilder::initializeSemanticExpressionSourceProvenance(vararg);
      const auto serialized = parseJson(rawTypeOwnedExpressionRef(vararg, {}));
      SageInterface::deleteAST(vararg);
      auto *decoded = isSgVarArgOp(expressionFromRef(serialized, {}));
      ROSE_ASSERT(decoded != nullptr && isSgTypeBool(decoded->get_type()));
      ROSE_ASSERT(isSgBoolValExp(decoded->get_operand_expr())->get_value());
      ROSE_ASSERT(decoded->get_operand_expr()->get_parent() == decoded);
      SageInterface::deleteAST(decoded);
      ROSE_ASSERT(SgVarArgOp::numberOfNodes() == vararg_count);
    }
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgNoexceptOp::numberOfNodes() == count);
  }
}

void requireTypeIdConstruction() {
  using namespace Rose::AstJson;
  auto *file = SageBuilder::buildGeneratedSourceFile("rex_typeid_contract.cpp");
  std::unique_ptr<SgProject, DeleteFixtureAst> project(file->get_project());
  auto *declaration = SageBuilder::buildNondefiningClassDeclaration(
      SageBuilder::declaration_ownership::sourceLexical(), "RexTypeIdResult",
      file->get_globalScope());
  auto *result_type = SageBuilder::buildReferenceType(
      SageBuilder::buildConstType(declaration->get_type()));
  for (bool type_operand : {false, true}) {
    auto *operand = type_operand ? nullptr : SageBuilder::buildIntVal(7);
    auto *operand_type = type_operand ? SageBuilder::buildIntType() : nullptr;
    auto *original = new SgTypeIdOp(operand, operand_type, result_type, false);
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    const std::unordered_map<const SgNode *, uint64_t> ids{
        {original, 1}, {operand, 2}, {declaration, 3}};
    NodeRecord record;
    record.id = 1;
    record.kind = "SgTypeIdOp";
    record.flags = parseJson(rawNodeFlagsJson(original));
    record.location = parseJson(rawLocationJson(original));
    record.properties = parseJson(rawNodeProperties(original, ids));
    if (operand != nullptr)
      record.edges = {{"operand_expr", 2, 0}};
    const auto owned =
        parseJson(rawTypeOwnedExpressionRef(original, {{declaration, 3}}));
    SageInterface::deleteAST(original);
    const auto count = SgTypeIdOp::numberOfNodes();
    for (bool inline_type : {false, true}) {
      NodeMap nodes{{3, declaration}};
      SgTypeIdOp *restored = nullptr;
      if (inline_type) {
        restored = isSgTypeIdOp(expressionFromRef(owned, nodes));
      } else {
        std::vector<NodeRecord> records{record};
        if (!type_operand) {
          nodes.emplace(2, SageBuilder::buildIntVal(7));
          NodeRecord child;
          child.id = 2;
          child.kind = "SgIntVal";
          child.edges = {{"parent", 1, 0}};
          records.push_back(child);
        }
        rebuildConstructorOnlyNodes(recordGraph(records), nodes);
        restored = isSgTypeIdOp(nodes.at(1));
      }
      ROSE_ASSERT(restored != nullptr && restored->get_type() == result_type);
      ROSE_ASSERT(!restored->get_operand_is_evaluated());
      ROSE_ASSERT(restored->get_operand_type() == operand_type);
      if (!type_operand)
        ROSE_ASSERT(restored->get_operand_expr()->get_parent() == restored);
      SageInterface::deleteAST(restored);
      ROSE_ASSERT(SgTypeIdOp::numberOfNodes() == count);
    }
    for (int invalid = 0; invalid != (type_operand ? 3 : 2); ++invalid) {
      auto malformed = owned;
      auto &properties = malformed.object.at("properties");
      const char *diagnostic = nullptr;
      if (invalid == 0) {
        properties.object.erase("operand_is_evaluated");
        diagnostic = "missing key: operand_is_evaluated";
      } else if (invalid == 1) {
        properties.object.at("operand_is_evaluated") = JsonValue::number("1");
        diagnostic = "value is not a bool";
      } else {
        properties.object.at("operand_is_evaluated") = JsonValue::boolean(true);
        diagnostic = "typeid";
      }
      const auto expressions = SgIntVal::numberOfNodes();
      const auto positions = Sg_File_Info::numberOfNodes();
      for (bool inline_type : {false, true}) {
        bool rejected = false;
        try {
          if (inline_type) {
            SageInterface::deleteAST(
                expressionFromRef(malformed, {{3, declaration}}));
          } else {
            NodeRecord bad = record;
            bad.properties = properties;
            SageInterface::deleteAST(
                reconstructSourceFile(recordGraph({bad}), nullptr));
          }
        } catch (const std::runtime_error &error) {
          rejected =
              std::string(error.what()).find(diagnostic) != std::string::npos;
        }
        ROSE_ASSERT(rejected && SgTypeIdOp::numberOfNodes() == count);
        ROSE_ASSERT(SgIntVal::numberOfNodes() == expressions);
        ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
      }
    }
  }
}

void requireNullptrValueConstruction() {
  using namespace Rose::AstJson;
  for (SgType *type : {static_cast<SgType *>(SageBuilder::buildNullptrType()),
                       static_cast<SgType *>(SageBuilder::buildPointerType(
                           SageBuilder::buildIntType()))}) {
    for (bool explicit_type : {false, true}) {
      auto original = std::make_unique<SgNullptrValExp>();
      original->set_literal_type(type);
      SageBuilder::initializeSemanticExpressionSourceProvenance(original.get());
      NodeRecord record;
      record.id = 1;
      record.kind = "SgNullptrValExp";
      record.flags = parseJson(rawNodeFlagsJson(original.get()));
      record.location = parseJson(rawLocationJson(original.get()));
      record.properties = parseJson(rawNodeProperties(original.get(), {}));
      record.properties.object.at("has_literal_semantic_type") =
          parseJson(explicit_type ? "true" : "false");
      auto owned = parseJson(rawTypeOwnedExpressionRef(original.get(), {}));
      const auto count = SgNullptrValExp::numberOfNodes();
      for (bool inline_type : {false, true}) {
        for (SgType *serialized_type :
             {type, static_cast<SgType *>(SageBuilder::buildIntType()),
              static_cast<SgType *>(nullptr)}) {
          auto candidate = record;
          candidate.properties.object.at("type") =
              parseJson(rawTypeJson(serialized_type, {}));
          const bool valid = serialized_type == type &&
                             (explicit_type || isSgTypeNullptr(type));
          bool rejected = false;
          try {
            SgNullptrValExp *restored = nullptr;
            if (inline_type) {
              owned.object.at("properties") = candidate.properties;
              restored = isSgNullptrValExp(expressionFromRef(owned, {}));
            } else {
              AstFileRecord ast;
              ast.nodes = {candidate};
              NodeMap nodes;
              rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
              restored = isSgNullptrValExp(nodes.at(1));
            }
            std::unique_ptr<SgNullptrValExp> owner(restored);
            ROSE_ASSERT(valid && restored && restored->get_type() == type);
            ROSE_ASSERT(restored->get_literal_type() ==
                        (explicit_type ? type : nullptr));
          } catch (const std::runtime_error &error) {
            ROSE_ASSERT(
                std::string(error.what())
                    .find("null literal requires an exact null or pointer "
                          "type and matching literal metadata") !=
                std::string::npos);
            rejected = true;
          }
          ROSE_ASSERT(rejected == !valid &&
                      SgNullptrValExp::numberOfNodes() == count);
        }
      }
    }
  }
}

void requireEnumValueConstruction() {
  using namespace Rose::AstJson;
  auto *file = SageBuilder::buildGeneratedSourceFile("rex_enum_contract.cpp");
  std::unique_ptr<SgProject, DeleteFixtureAst> project(file->get_project());
  auto *declaration = SageBuilder::buildEnumDeclaration(
      SageBuilder::declaration_ownership::sourceLexical(), "rex_enum", false,
      file->get_globalScope());
  auto *canonical =
      isSgEnumDeclaration(declaration->get_type()->get_declaration());
  ROSE_ASSERT(canonical != nullptr);
  NodeRecord record;
  record.id = 2;
  record.kind = "SgEnumDeclaration";
  record.edges = {{"scope", 3, 0}, {"firstNondefiningDeclaration", 4, 0}};
  record.flags = parseJson(rawNodeFlagsJson(declaration));
  record.location = parseJson(rawLocationJson(declaration));
  record.properties = parseJson(
      rawNodeProperties(declaration, {{declaration, 2}, {canonical, 4}}));
  record.properties.object.at("embedded") = parseJson("true");
  record.properties.object.at("is_autonomous_declaration") = parseJson("false");
  record.properties.object.at("is_scoped_enum") = parseJson("true");
  record.properties.object.at("underlying_type_source_spelled") =
      parseJson("true");
  auto *underlying = SageBuilder::buildUnsignedShortType();
  record.properties.object.at("field_type") =
      parseJson(rawTypeJson(underlying, {}));
  auto *promotion = SageBuilder::buildIntType();
  record.properties.object.at("promotion_type") =
      parseJson(rawTypeJson(promotion, {}));
  const NodeMap enum_dependencies{{3, file->get_globalScope()}, {4, canonical}};
  {
    std::unique_ptr<SgEnumDeclaration> declaration(isSgEnumDeclaration(
        createNodeFromRecord(record, nullptr, enum_dependencies)));
    ROSE_ASSERT(declaration != nullptr && declaration->get_embedded());
    ROSE_ASSERT(!declaration->get_isUnNamed());
    ROSE_ASSERT(!declaration->get_isAutonomousDeclaration());
    ROSE_ASSERT(declaration->get_isScopedEnum());
    ROSE_ASSERT(declaration->get_underlying_type_source_spelled());
    ROSE_ASSERT(declaration->get_firstNondefiningDeclaration() == canonical);
    ROSE_ASSERT(declaration->get_type() == canonical->get_type());
    ROSE_ASSERT(declaration->get_field_type() == underlying);
    ROSE_ASSERT(declaration->get_promotion_type() == promotion);
  }
  {
    NodeRecord owner_record = record;
    owner_record.id = 4;
    std::unique_ptr<SgEnumDeclaration> owner(
        isSgEnumDeclaration(createNodeFromRecord(
            owner_record, nullptr, NodeMap{{3, file->get_globalScope()}})));
    std::unique_ptr<SgEnumType> wrapper(owner->get_type());
    ROSE_ASSERT(owner->get_firstNondefiningDeclaration() == owner.get());
    ROSE_ASSERT(wrapper->get_declaration() == owner.get());
    ROSE_ASSERT(owner->get_field_type() == underlying);
    ROSE_ASSERT(owner->get_promotion_type() == promotion);
    owner->set_type(nullptr);
    wrapper->set_declaration(nullptr);
  }
  record.properties.object.erase("is_scoped_enum");
  const auto enumCount = SgEnumDeclaration::numberOfNodes();
  bool missingScopedFlagRejected = false;
  try {
    std::unique_ptr<SgNode> unexpected(
        createNodeFromRecord(record, nullptr, enum_dependencies));
  } catch (const std::runtime_error &error) {
    missingScopedFlagRejected =
        std::string(error.what()).find("missing key: is_scoped_enum") !=
        std::string::npos;
  }
  ROSE_ASSERT(missingScopedFlagRejected &&
              SgEnumDeclaration::numberOfNodes() == enumCount);
  record.properties.object["is_scoped_enum"] = parseJson("true");
  for (bool missing : {true, false}) {
    NodeRecord rejected_record = record;
    if (missing)
      rejected_record.properties.object.erase("promotion_type");
    else
      rejected_record.properties.object.at("promotion_type") =
          parseJson(rawTypeJson(SageBuilder::buildFloatType(), {}));
    bool rejected = false;
    try {
      std::unique_ptr<SgNode> unexpected(
          createNodeFromRecord(rejected_record, nullptr, enum_dependencies));
    } catch (const std::runtime_error &error) {
      const std::string expected = missing ? "missing key: promotion_type"
                                           : "enum has no exact promotion type";
      if (std::string(error.what()).find(expected) == std::string::npos)
        throw;
      rejected = true;
    }
    ROSE_ASSERT(rejected && SgEnumDeclaration::numberOfNodes() == enumCount);
  }
  auto original = std::make_unique<SgEnumVal>(7, declaration, "rex_value");
  original->set_literal_type(declaration->get_type());
  SageBuilder::initializeSemanticExpressionSourceProvenance(original.get());
  const auto properties = parseJson(
      rawNodeProperties(original.get(), {{declaration, 2}, {canonical, 4}}));
  const NodeMap nodes{
      {2, declaration}, {3, file->get_globalScope()}, {4, canonical}};
  auto *unrelated = SageBuilder::buildEnumDeclaration(
      SageBuilder::declaration_ownership::sourceLexical(), "rex_other_enum",
      false, file->get_globalScope());
  SgEnumType *originalType = canonical->get_type();
  const auto typeCount = SgEnumType::numberOfNodes();
  const auto declarationCount = SgEnumDeclaration::numberOfNodes();
  const auto typeJson = parseJson(rawTypeJson(originalType, {{canonical, 4}}));
  for (SgEnumType *invalidType :
       {static_cast<SgEnumType *>(nullptr), unrelated->get_type()}) {
    canonical->set_type(invalidType);
    bool constructionRejected = false;
    try {
      std::unique_ptr<SgNode> unexpected(
          createNodeFromRecord(record, nullptr, enum_dependencies));
    } catch (const std::runtime_error &error) {
      constructionRejected =
          std::string(error.what()).find("no exact constructed type owner") !=
          std::string::npos;
    }
    bool rejected = false;
    try {
      (void)typeFromJson(typeJson, nodes);
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what()).find("no exact constructed type") !=
                 std::string::npos;
    }
    canonical->set_type(originalType);
    ROSE_ASSERT(rejected && SgEnumType::numberOfNodes() == typeCount);
    ROSE_ASSERT(constructionRejected &&
                SgEnumDeclaration::numberOfNodes() == declarationCount);
  }
  ROSE_ASSERT(typeFromJson(typeJson, nodes) == originalType);
  {
    auto *name = SageBuilder::buildInitializedName_nfi(
        "rex_value", declaration->get_type(), nullptr);
    name->set_enum_constant_value(7);
    auto *initializer = SageBuilder::buildAssignInitializer_nfi(
        SageBuilder::buildEnumVal_nfi(8, declaration, "rex_value"),
        declaration->get_type());
    NodeRecord record;
    record.id = 10;
    record.kind = "SgInitializedName";
    record.properties = parseJson(R"({
      "structured_binding_scope":0,
      "fortran_cray_pointer_pointee_shape":0,"structured_binding_kind":0,
      "structured_binding_owner":0,"structured_binding_value":0,
      "structured_binding_holding_variable":0
    })");
    record.edges = {{"initptr", 11, 0}};
    bool rejected = false;
    try {
      linkNodeEdges(record, {{10, name}, {11, initializer}});
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what())
              .find("enum initializer disagrees with its evaluated value") !=
          std::string::npos;
    }
    ROSE_ASSERT(rejected && name->get_initializer() == nullptr);
    ROSE_ASSERT(initializer->get_parent() == nullptr);
    SageInterface::deleteAST(initializer);
    SageInterface::deleteAST(name);
  }
  const size_t count = SgEnumVal::numberOfNodes();
  {
    std::unique_ptr<SgEnumVal> restored(
        enumValueFromProperties(properties, nodes));
    ROSE_ASSERT(restored->get_declaration() == declaration);
    ROSE_ASSERT(restored->get_literal_type() == declaration->get_type());
    ROSE_ASSERT(restored->get_value() == 7);
  }
  for (int malformed = 0; malformed < 5; ++malformed) {
    auto bad = properties;
    std::string expected;
    if (malformed == 0) {
      bad.object.at("declaration") = parseJson("0");
      expected = "enum literal requires a declaration";
    } else if (malformed == 1) {
      bad.object.at("declaration") = parseJson("3");
      expected = "node id has unexpected Sage type";
    } else if (malformed == 2) {
      bad.object.at("type") =
          parseJson(rawTypeJson(SageBuilder::buildIntType(), {}));
      expected = "enum literal type does not name its declaration";
    } else {
      const std::string key =
          malformed == 3 ? "name" : "has_literal_semantic_type";
      bad.object.erase(key);
      expected = "missing key: " + key;
    }
    bool rejected = false;
    try {
      std::unique_ptr<SgEnumVal> unexpected(
          enumValueFromProperties(bad, nodes));
    } catch (const std::runtime_error &error) {
      ROSE_ASSERT(std::string(error.what()).find(expected) !=
                  std::string::npos);
      rejected = true;
    }
    ROSE_ASSERT(rejected && SgEnumVal::numberOfNodes() == count);
  }
  auto *field = SageBuilder::buildInitializedName(
      "rex_value", declaration->get_type(),
      SageBuilder::buildAssignInitializer(SageBuilder::buildIntVal(7),
                                          declaration->get_type()));
  field->set_enum_constant_value(7);
  field->set_enum_constant_source_ownership(
      SgInitializedName::e_enum_constant_source_body);
  field->get_startOfConstruct()->setCompilerGenerated();
  field->get_endOfConstruct()->setCompilerGenerated();
  field->set_declptr(declaration);
  field->set_scope(file->get_globalScope());
  declaration->append_enumerator(field);
  file->get_globalScope()->insert_symbol(field->get_name(),
                                         new SgEnumFieldSymbol(field));
  auto *aliasValue = SageBuilder::buildEnumVal(7, declaration, "rex_value");
  aliasValue->set_literal_type(declaration->get_type());
  auto *alias = SageBuilder::buildInitializedName(
      "rex_alias", declaration->get_type(),
      SageBuilder::buildAssignInitializer(aliasValue, declaration->get_type()));
  alias->set_enum_constant_value(7);
  alias->set_enum_constant_source_ownership(
      SgInitializedName::e_enum_constant_source_body);
  alias->get_startOfConstruct()->setCompilerGenerated();
  alias->get_endOfConstruct()->setCompilerGenerated();
  alias->set_declptr(declaration);
  alias->set_scope(file->get_globalScope());
  declaration->append_enumerator(alias);
  file->get_globalScope()->insert_symbol(alias->get_name(),
                                         new SgEnumFieldSymbol(alias));
  declaration->validate_enumerator_source_ownership();
  struct EnumCopy final : SgTreeCopy {
    const SgInitializedName *field;
    bool checked = false;
    bool literalChecked = false;
    explicit EnumCopy(const SgInitializedName *field) : field(field) {}
    SgNode *copyAst(const SgNode *node) override {
      if (node == field) {
        const auto *owner = isSgEnumDeclaration(field->get_parent());
        const auto type = get_copiedNodeMap().find(owner->get_type());
        ROSE_ASSERT(type != get_copiedNodeMap().end());
        auto *copiedType = isSgEnumType(type->second);
        ROSE_ASSERT(copiedType != nullptr && copiedType != owner->get_type());
        ROSE_ASSERT(
            copiedType->get_declaration() ==
            get_copiedNodeMap().at(owner->get_firstNondefiningDeclaration()));
        checked = true;
      }
      SgNode *result = SgTreeCopy::copyAst(node);
      if (const auto *value = isSgEnumVal(node)) {
        auto *copiedValue = isSgEnumVal(result);
        ROSE_ASSERT(copiedValue != nullptr &&
                    copiedValue->get_literal_type() ==
                        get_copiedNodeMap().at(value->get_literal_type()));
        literalChecked = true;
      }
      return result;
    }
  } copy(field);
  std::unique_ptr<SgProject, DeleteFixtureAst> copied(
      isSgProject(project->copy(copy)));
  ROSE_ASSERT(copied != nullptr && copy.checked && copy.literalChecked);
  auto *copiedField = isSgInitializedName(copy.get_copiedNodeMap().at(field));
  ROSE_ASSERT(copiedField != field &&
              copiedField->get_type() ==
                  copy.get_copiedNodeMap().at(field->get_type()));
  ROSE_ASSERT(field->get_type() == declaration->get_type());
}

void requireTemplateParameterValueConstruction() {
  using namespace Rose::AstJson;
  SgName previousParameterMangle;
  for (SgType *type : {static_cast<SgType *>(SageBuilder::buildIntType()),
                       static_cast<SgType *>(SageBuilder::buildLongType())}) {
    auto *parameter = SageBuilder::buildTemplateParameter(
        SgTemplateParameter::nontype_parameter, type, SgName("rex_value"),
        nullptr, SgTemplateParameter::keyword_unspecified);
    const SgName parameterMangle = parameter->get_mangled_name();
    ROSE_ASSERT(!parameterMangle.is_null());
    ROSE_ASSERT(previousParameterMangle != parameterMangle);
    previousParameterMangle = parameterMangle;
    parameter->set_is_parameter_pack(true);
    ROSE_ASSERT(parameter->get_mangled_name() != parameterMangle);
    parameter->set_is_parameter_pack(false);
    auto *original = new SgTemplateParameterVal(2, parameter);
    SgType *literal_type = isSgTypeLong(type) != nullptr ? type : nullptr;
    original->set_literal_type(literal_type);
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    NodeRecord record;
    record.id = 1;
    record.kind = "SgTemplateParameterVal";
    record.flags = parseJson(rawNodeFlagsJson(original));
    record.location = parseJson(rawLocationJson(original));
    record.properties =
        parseJson(rawNodeProperties(original, {{original, 1}, {parameter, 2}}));
    const auto owned =
        parseJson(rawTypeOwnedExpressionRef(original, {{parameter, 2}}));
    SageInterface::deleteAST(original);
    const size_t values = SgTemplateParameterVal::numberOfNodes();
    for (int repeat = 0; repeat < 25; ++repeat) {
      parameter->get_initializedName()->set_name(
          SgName(repeat % 2 == 0 ? "rex_value" : ""));
      ROSE_ASSERT(parameter->get_mangled_name() == parameterMangle);
      auto *restored_owned =
          isSgTemplateParameterVal(expressionFromRef(owned, {{2, parameter}}));
      ROSE_ASSERT(restored_owned != nullptr &&
                  restored_owned->get_type() == type &&
                  restored_owned->get_literal_type() == literal_type &&
                  restored_owned->get_template_parameter_position() == 2 &&
                  restored_owned->get_template_parameter() == parameter);
      SageInterface::deleteAST(restored_owned);
      AstFileRecord ast;
      ast.nodes = {record};
      NodeMap nodes{{2, parameter}};
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      auto *restored = isSgTemplateParameterVal(nodes.at(1));
      ROSE_ASSERT(restored != nullptr && restored->get_type() == type &&
                  restored->get_literal_type() == literal_type &&
                  restored->get_template_parameter() == parameter);
      SageInterface::deleteAST(restored);
      for (int malformed = 0; malformed != 6; ++malformed) {
        auto bad = record.properties;
        std::string expected = "has no exact position";
        if (malformed == 0) {
          bad.object.erase("type");
          expected = "missing key: type";
        } else if (malformed == 1) {
          bad.object.at("template_parameter_position") = parseJson("-1");
        } else if (malformed == 2) {
          bad.object.at("template_parameter_position") =
              parseJson("9223372036854775807");
        } else if (malformed == 3) {
          bad.object.erase("template_parameter");
          expected = "missing key: template_parameter";
        } else if (malformed == 4) {
          bad.object.erase("has_literal_semantic_type");
          expected = "missing key: has_literal_semantic_type";
        } else {
          bad.object.at("has_literal_semantic_type") = parseJson("1");
          expected = "AST JSON value is not a bool";
        }
        bool rejected = false;
        try {
          std::unique_ptr<SgTemplateParameterVal> unexpected(
              templateParameterValueFromProperties(bad, {{2, parameter}}));
        } catch (const std::runtime_error &error) {
          if (std::string(error.what()).find(expected) == std::string::npos)
            throw;
          rejected = true;
        }
        ROSE_ASSERT(rejected);
        ROSE_ASSERT(SgTemplateParameterVal::numberOfNodes() == values);
      }
    }
    const std::unordered_map<const SgNode *, uint64_t> parameter_ids{
        {parameter, 2}, {parameter->get_initializedName(), 3}};
    std::vector<NodeRecord> parameter_records;
    for (SgNode *node :
         {static_cast<SgNode *>(parameter),
          static_cast<SgNode *>(parameter->get_initializedName())}) {
      NodeRecord serialized;
      serialized.id = parameter_ids.at(node);
      serialized.kind = node->class_name();
      serialized.flags = parseJson(rawNodeFlagsJson(node));
      serialized.location = parseJson(rawLocationJson(node));
      serialized.properties = parseJson(rawNodeProperties(node, parameter_ids));
      parameter_records.push_back(serialized);
    }
    parameter_records[0].edges = {{"canonicalNonTypeParameter", 2, 0},
                                  {"initializedName", 3, 0}};
    parameter_records[1].edges = {{"parent", 2, 0}};
    SageInterface::deleteAST(parameter);
    const auto parameters = SgTemplateParameter::numberOfNodes();
    const auto names = SgInitializedName::numberOfNodes();
    for (int malformed = 0; malformed != 5; ++malformed) {
      auto records = parameter_records;
      if (malformed == 1)
        records[0].properties.object.at("initialized_name") = parseJson("2");
      else if (malformed == 2)
        records[0].properties.object.at("type") =
            parseJson(rawTypeJson(SageBuilder::buildDoubleType(), {}));
      else if (malformed == 3)
        records[1].edges.push_back({"declptr", 2, 0});
      else if (malformed == 4)
        records[0].properties.object.at("canonical_nontype_parameter") =
            parseJson("3");
      NodeMap nodes;
      bool rejected = false;
      try {
        const auto graph = recordGraph(records);
        rebuildConstructorOnlyNodes(graph, nodes);
        auto pending = collectDelayedDeclarations(graph, nodes);
        drainDelayedDeclarations(graph, pending, nodes, true);
      } catch (const std::runtime_error &error) {
        const char *expected =
            malformed == 1
                ? "conflicting pointer identity 'initialized_name'"
                : "scope-free template declarator has no exact canonical "
                  "parameter owner";
        if (malformed == 0 ||
            std::string(error.what()).find(expected) == std::string::npos)
          throw;
        rejected = true;
      }
      ROSE_ASSERT(rejected == (malformed != 0));
      if (!rejected) {
        auto *restored = isSgTemplateParameter(nodes.at(2));
        auto *name = isSgInitializedName(nodes.at(3));
        ROSE_ASSERT(restored != nullptr && name != nullptr);
        ROSE_ASSERT(restored->get_parent() == nullptr &&
                    restored->get_canonicalNonTypeParameter() == restored);
        ROSE_ASSERT(restored->get_initializedName() == name &&
                    name->get_parent() == restored && name->get_type() == type);
        ROSE_ASSERT(name->get_scope() == nullptr &&
                    name->get_declptr() == nullptr);
        SageInterface::deleteAST(restored);
      } else {
        ROSE_ASSERT(nodes.empty());
      }
      ROSE_ASSERT(SgTemplateParameter::numberOfNodes() == parameters);
      ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
    }
  }
}

void requireSourceLocationConstruction() {
  using namespace Rose::AstJson;
  using Builtin = SgSourceLocationBuiltinExp;
  for (auto kind : {Builtin::e_line, Builtin::e_file}) {
    SgType *type =
        kind == Builtin::e_line
            ? static_cast<SgType *>(SageBuilder::buildUnsignedIntType())
            : SageBuilder::buildPointerType(
                  SageBuilder::buildConstType(SageBuilder::buildCharType()));
    const auto serialized_type = parseJson(rawTypeJson(type, {}));
    const size_t modifier_count = SgModifierType::numberOfNodes();
    for (int repeat = 0; repeat < 3; ++repeat) {
      ROSE_ASSERT(typeFromJson(serialized_type, {}) == type);
      ROSE_ASSERT(SgModifierType::numberOfNodes() == modifier_count);
    }
    auto *original = new Builtin(kind, type);
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    NodeRecord record;
    record.id = 1;
    record.kind = "SgSourceLocationBuiltinExp";
    record.flags = parseJson(rawNodeFlagsJson(original));
    record.location = parseJson(rawLocationJson(original));
    record.properties = parseJson(rawNodeProperties(original, {{original, 1}}));
    const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
    SageInterface::deleteAST(original);
    const auto count = Builtin::numberOfNodes();
    const size_t positions = Sg_File_Info::numberOfNodes();
    for (const char *field :
         {"is_modified", "contains_transformation",
          "contains_transformation_to_surrounding_whitespace",
          "source_range_ends_in_macro_expansion",
          "source_range_is_macro_expansion_fragment"}) {
      for (int repeat = 0; repeat < 25; ++repeat) {
        AstFileRecord bad_ast;
        bad_ast.nodes = {record};
        bad_ast.nodes.front().flags.object.erase(field);
        NodeMap nodes;
        bool rejected = false;
        try {
          rebuildConstructorOnlyNodes(recordGraph(bad_ast.nodes), nodes);
        } catch (const std::runtime_error &error) {
          if (std::string(error.what())
                  .find(std::string("missing key: ") + field) ==
              std::string::npos)
            throw;
          rejected = true;
        }
        ROSE_ASSERT(rejected && nodes.empty());
        ROSE_ASSERT(Builtin::numberOfNodes() == count);
        ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
      }
    }
    for (int repeat = 0; repeat != 25; ++repeat) {
      auto *restored_owned =
          isSgSourceLocationBuiltinExp(expressionFromRef(owned, {}));
      ROSE_ASSERT(restored_owned != nullptr &&
                  restored_owned->get_kind() == kind);
      ROSE_ASSERT(restored_owned->get_type() == type);
      SageInterface::deleteAST(restored_owned);
      AstFileRecord ast;
      ast.nodes = {record};
      NodeMap nodes;
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      auto *restored = isSgSourceLocationBuiltinExp(nodes.at(1));
      ROSE_ASSERT(restored != nullptr && restored->get_kind() == kind &&
                  restored->get_type() == type);
      SageInterface::deleteAST(restored);
      for (bool invalid_kind : {false, true}) {
        auto bad = record.properties;
        if (invalid_kind)
          bad.object.at("source_location_builtin_kind") = parseJson("9999");
        else
          bad.object.erase("type");
        bool rejected = false;
        try {
          std::unique_ptr<Builtin> unexpected(
              sourceLocationBuiltinFromProperties(bad, {}));
        } catch (const std::runtime_error &error) {
          const std::string expected =
              invalid_kind ? "invalid source_location_builtin_kind enum value"
                           : "missing key: type";
          rejected =
              std::string(error.what()).find(expected) != std::string::npos;
        }
        ROSE_ASSERT(rejected);
        ROSE_ASSERT(Builtin::numberOfNodes() == count);
      }
    }
  }
}

void requirePseudoObjectConstruction() {
  using namespace Rose::AstJson;
  const auto category = SgCastExp::e_value_category_prvalue;
  const auto kind = SgOpaqueValueBinding::e_ordinary_object;
  auto semantic = [](auto *expression) {
    SageBuilder::initializeSemanticExpressionSourceProvenance(expression);
    return expression;
  };
  auto *type = SageBuilder::buildIntType();
  auto *binding = semantic(new SgOpaqueValueBinding(
      semantic(SageBuilder::buildIntVal_nfi(7)), type, category, kind));
  auto *result = semantic(new SgOpaqueValueReference(binding));
  auto *nested_result = semantic(new SgOpaqueValueReference(binding));
  auto *nested_steps = semantic(SageBuilder::buildExprListExp_nfi());
  nested_steps->append_expression(nested_result);
  auto *nested = semantic(new SgPseudoObjectExp(
      semantic(SageBuilder::buildIntVal_nfi(9)), nested_steps, nested_result,
      {binding}, type, category, kind));
  auto *steps = semantic(SageBuilder::buildExprListExp_nfi());
  steps->append_expression(binding);
  steps->append_expression(result);
  steps->append_expression(nested);
  auto *original =
      semantic(new SgPseudoObjectExp(semantic(SageBuilder::buildIntVal_nfi(8)),
                                     steps, result, {}, type, category, kind));
  auto check = [](SgPseudoObjectExp *expression) {
    ROSE_ASSERT(expression != nullptr);
    expression->get_written_expression_checked();
    const auto entry = expression->cfgOutEdges(0);
    ROSE_ASSERT(entry.size() == 1);
    ROSE_ASSERT(entry.front().target() ==
                expression->get_semantic_evaluations()->cfgForBeginning());
    ROSE_ASSERT(expression->cfgInEdges(1).front().source() ==
                expression->get_semantic_evaluations()->cfgForEnd());
    const auto &steps =
        expression->get_semantic_evaluations()->get_expressions();
    ROSE_ASSERT(steps.size() == 3 &&
                expression->get_result_expression() == steps[1]);
    auto *binding = isSgOpaqueValueBinding(steps[0]);
    ROSE_ASSERT(binding != nullptr);
    ROSE_ASSERT(isSgOpaqueValueReference(steps[1])->get_binding() == binding);
    auto *nested = isSgPseudoObjectExp(steps[2]);
    ROSE_ASSERT(nested != nullptr &&
                nested->get_captured_bindings().size() == 1);
    ROSE_ASSERT(nested->get_captured_bindings()[0] == binding);
    ROSE_ASSERT(isSgOpaqueValueReference(nested->get_result_expression())
                    ->get_binding() == binding);
  };
  check(original);
  auto *copy = isSgPseudoObjectExp(SageInterface::deepCopy(original));
  check(copy);
  ROSE_ASSERT(copy->get_semantic_evaluations()->get_expressions()[0] !=
              binding);
  SageInterface::deleteAST(copy);
  const auto serialized = parseJson(rawTypeOwnedExpressionRef(original, {}));
  auto *restored = isSgPseudoObjectExp(expressionFromRef(serialized, {}));
  check(restored);
  ROSE_ASSERT(restored->get_semantic_evaluations()->get_expressions()[0] !=
              binding);
  SageInterface::deleteAST(restored);
  for (int mutation = 0; mutation != 4; ++mutation) {
    auto malformed = serialized;
    auto &properties = malformed.object.at("properties").object;
    if (mutation == 0)
      properties.at("result_index") = parseJson("3");
    else if (mutation == 1)
      properties.at("object_kind") = parseJson("-1");
    else if (mutation == 2)
      properties.at("semantic_evaluations")
          .object.at("expressions")
          .array[1]
          .object.at("properties")
          .object.at("binding_reference")
          .object.at("binding_depth") = parseJson("1");
    else
      properties.at("semantic_evaluations")
          .object.at("expressions")
          .array[2]
          .object.at("properties")
          .object.at("captured_bindings") = parseJson("[]");
    const auto expressions = SgPseudoObjectExp::numberOfNodes();
    const auto bindings = SgOpaqueValueBinding::numberOfNodes();
    const auto references = SgOpaqueValueReference::numberOfNodes();
    const auto values = SgIntVal::numberOfNodes();
    const auto lists = SgExprListExp::numberOfNodes();
    bool rejected = false;
    try {
      (void)expressionFromRef(malformed, {});
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected);
    ROSE_ASSERT(expressions == SgPseudoObjectExp::numberOfNodes());
    ROSE_ASSERT(bindings == SgOpaqueValueBinding::numberOfNodes());
    ROSE_ASSERT(references == SgOpaqueValueReference::numberOfNodes());
    ROSE_ASSERT(values == SgIntVal::numberOfNodes());
    ROSE_ASSERT(lists == SgExprListExp::numberOfNodes());
  }
  const auto owned = collectNodes(original);
  std::unordered_map<const SgNode *, uint64_t> ids;
  for (size_t index = 0; index != owned.size(); ++index)
    ids.emplace(owned[index], index + 1);
  std::vector<NodeRecord> records;
  for (SgNode *node : owned) {
    std::ostringstream output;
    writeNodeJson(output, node, ids, false);
    const auto json = parseJson(output.str());
    NodeRecord record;
    record.id = json.requiredInt("id");
    record.kind = json.requiredString("kind");
    record.variant = static_cast<VariantT>(json.requiredInt("variant"));
    record.flags = json.at("flags");
    record.location = json.at("location");
    record.properties = json.at("properties");
    record.preprocessing = record.properties.at("preprocessing");
    for (const auto &edge : json.at("edges").array)
      record.edges.push_back(
          {edge.requiredString("field"),
           static_cast<uint64_t>(edge.requiredInt("target")),
           static_cast<uint64_t>(edge.requiredInt("index"))});
    records.push_back(std::move(record));
  }
  std::reverse(records.begin(), records.end());
  NodeMap nodes;
  for (const auto &record : records)
    if (!requiresDelayedRebuild(record) ||
        isJsonScalarLiteralKind(record.kind)) {
      auto *node = createNodeFromRecord(record, nullptr);
      validateConstructionFlags(record).initialize(node);
      nodes.emplace(record.id, node);
    }
  rebuildConstructorOnlyNodes(recordGraph(records), nodes);
  auto *graph_copy = nodeByIdAs<SgPseudoObjectExp>(nodes, ids.at(original));
  check(graph_copy);
  SageInterface::deleteAST(graph_copy);
  SageInterface::deleteAST(original);
}

void requireArrayInitializationConstruction() {
  using namespace Rose::AstJson;
  using Reference = SgCxxArrayInitReference;
  for (uint64_t count :
       {UINT64_C(0), UINT64_C(1), UINT64_C(1) << 63, UINT64_MAX}) {
    const auto encoded = parseJson(
        rawInteger128Value(Rose::Integer128Value::fromBits({count, 0}, true)));
    ROSE_ASSERT(unsigned64ValueFromJson(encoded) == count);
  }
  for (const auto value : {Rose::Integer128Value::fromBits({1, 0}, false),
                           Rose::Integer128Value::fromBits({0, 1}, true)}) {
    bool rejected = false;
    try {
      (void)unsigned64ValueFromJson(parseJson(rawInteger128Value(value)));
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what()).find("unsigned 64-bit") !=
                 std::string::npos;
    }
    ROSE_ASSERT(rejected);
  }
  auto semantic = [](SgExpression *expression) {
    SageBuilder::initializeSemanticExpressionSourceProvenance(expression);
    return expression;
  };
  SgType *integer = SageBuilder::buildIntType();
  SgType *index_type = SageBuilder::buildUnsignedLongType();
  auto *row = SageBuilder::buildArrayType(integer, SageBuilder::buildIntVal(2));
  auto *matrix = SageBuilder::buildArrayType(row, SageBuilder::buildIntVal(2));
  auto *list = isSgExprListExp(semantic(SageBuilder::buildExprListExp_nfi()));
  auto *source = semantic(SageBuilder::buildAggregateInitializer_nfi(
      list, matrix,
      SgAggregateInitializer::e_aggregate_initializer_source_braced));
  auto *outer_binding =
      new SgCxxArrayInitBinding(source, SgCastExp::e_value_category_prvalue);
  auto make_element = [&](SgCxxArrayInitBinding *binding, SgType *array,
                          SgType *element, long long storage_size) {
    auto *common =
        semantic(new Reference(binding, Reference::e_common_value, array,
                               binding->get_common_value_category()));
    auto *index =
        semantic(new Reference(binding, Reference::e_current_index, index_type,
                               SgCastExp::e_value_category_prvalue));
    return semantic(constructBinaryOp("SgPntrArrRefExp", common, index, element,
                                      std::nullopt, storage_size,
                                      {storage_size * 8}));
  };
  auto *inner_source = make_element(outer_binding, matrix, row, 8);
  auto *inner_binding = new SgCxxArrayInitBinding(
      inner_source, SgCastExp::e_value_category_xvalue);
  auto *inner_element = make_element(inner_binding, row, integer, 4);
  auto *inner = static_cast<SgCxxArrayInitLoop *>(
      semantic(new SgCxxArrayInitLoop(inner_binding, inner_element, row, 2)));
  auto *original = static_cast<SgCxxArrayInitLoop *>(
      semantic(new SgCxxArrayInitLoop(outer_binding, inner, matrix, 2)));
  auto *retired =
      isSgCxxArrayInitBinding(SageInterface::deepCopy(outer_binding));
  ROSE_ASSERT(retired != nullptr);
  SgExpression *retired_source = retired->get_common_source();
  retired_source->set_parent(nullptr);
  delete retired;
  ROSE_ASSERT(!SgNode::isLiveNode(retired));
  ROSE_ASSERT(
      !Reference::is_valid_reference(retired, Reference::e_common_value, matrix,
                                     SgCastExp::e_value_category_prvalue));
  ROSE_ASSERT(!SgCxxArrayInitLoop::is_valid_loop(retired, inner, matrix, 2));
  SageInterface::deleteAST(retired_source);
  ROSE_ASSERT(!SgNode::isLiveNode(retired_source));
  ROSE_ASSERT(!SgCxxArrayInitBinding::is_valid_source(
      retired_source, SgCastExp::e_value_category_prvalue));
  const auto serialized = parseJson(rawTypeOwnedExpressionRef(original, {}));
  auto check = [](SgCxxArrayInitLoop *loop) {
    ROSE_ASSERT(loop != nullptr && loop->get_element_count() == 2);
    loop->validate();
    auto *nested = isSgCxxArrayInitLoop(loop->get_element_initializer());
    ROSE_ASSERT(nested != nullptr && nested->get_element_count() == 2);
    auto *source =
        isSgPntrArrRefExp(nested->get_binding()->get_common_source());
    auto *element = isSgPntrArrRefExp(nested->get_element_initializer());
    ROSE_ASSERT(source != nullptr && element != nullptr);
    ROSE_ASSERT(source->get_result_storage_size_bytes() == 8);
    ROSE_ASSERT(element->get_result_storage_size_bytes() == 4);
    ROSE_ASSERT(source->get_subscript_stride_bits() ==
                std::vector<std::optional<long long>>{64});
    ROSE_ASSERT(element->get_subscript_stride_bits() ==
                std::vector<std::optional<long long>>{32});
    for (SgExpression *reference :
         {source->get_lhs_operand_i(), source->get_rhs_operand_i()})
      ROSE_ASSERT(isSgCxxArrayInitReference(reference)->get_binding() ==
                  loop->get_binding());
    for (SgExpression *reference :
         {element->get_lhs_operand_i(), element->get_rhs_operand_i()})
      ROSE_ASSERT(isSgCxxArrayInitReference(reference)->get_binding() ==
                  nested->get_binding());
  };
  auto *restored = isSgCxxArrayInitLoop(expressionFromRef(serialized, {}));
  check(restored);
  ROSE_ASSERT(restored->get_binding() != outer_binding);
  SageInterface::deleteAST(restored);
  auto *index_reference = isSgCxxArrayInitReference(
      isSgPntrArrRefExp(inner_element)->get_rhs_operand_i());
  const auto borrowed_reference = parseJson(
      rawTypeOwnedExpressionRef(index_reference, {{inner_binding, 1}}));
  auto *borrowed_copy = isSgCxxArrayInitReference(
      expressionFromRef(borrowed_reference, {{1, inner_binding}}));
  ROSE_ASSERT(borrowed_copy != index_reference &&
              borrowed_copy->get_binding() == inner_binding);
  SageInterface::deleteAST(borrowed_copy);
  ROSE_ASSERT(inner_binding->get_parent() == inner);

  auto require_rejected = [&](const JsonValue &malformed,
                              const std::string &diagnostic) {
    const auto loops = SgCxxArrayInitLoop::numberOfNodes();
    const auto bindings = SgCxxArrayInitBinding::numberOfNodes();
    const auto references = Reference::numberOfNodes();
    const auto aggregates = SgAggregateInitializer::numberOfNodes();
    const auto arrays = SgArrayType::numberOfNodes();
    const auto values = SgIntVal::numberOfNodes();
    const auto positions = Sg_File_Info::numberOfNodes();
    const auto pointers = SgPointerType::numberOfNodes();
    const auto symbols = SgFunctionTypeSymbol::numberOfNodes();
    SgNode *row_parent = row->get_parent();
    SgNode *matrix_parent = matrix->get_parent();
    bool rejected = false;
    try {
      SageInterface::deleteAST(expressionFromRef(malformed, {}));
    } catch (const std::runtime_error &error) {
      if (std::string(error.what()).find(diagnostic) == std::string::npos)
        throw;
      rejected = true;
    }
    ROSE_ASSERT(rejected && loops == SgCxxArrayInitLoop::numberOfNodes());
    ROSE_ASSERT(bindings == SgCxxArrayInitBinding::numberOfNodes());
    ROSE_ASSERT(references == Reference::numberOfNodes());
    ROSE_ASSERT(aggregates == SgAggregateInitializer::numberOfNodes());
    ROSE_ASSERT(arrays == SgArrayType::numberOfNodes());
    ROSE_ASSERT(values == SgIntVal::numberOfNodes());
    ROSE_ASSERT(positions == Sg_File_Info::numberOfNodes());
    ROSE_ASSERT(pointers == SgPointerType::numberOfNodes());
    ROSE_ASSERT(symbols == SgFunctionTypeSymbol::numberOfNodes());
    ROSE_ASSERT(row->get_parent() == row_parent &&
                matrix->get_parent() == matrix_parent);
    check(original);
  };
  for (int mutation = 0; mutation != 17; ++mutation) {
    auto malformed = serialized;
    auto &outer = malformed.object.at("properties");
    auto &inner =
        outer.object.at("element_initializer").object.at("properties");
    auto &operand = inner.object.at("element_initializer")
                        .object.at("properties")
                        .object.at("rhs_operand")
                        .object.at("properties");
    std::string diagnostic;
    if (mutation == 0) {
      outer.object.erase("element_count");
      diagnostic = "missing key: element_count";
    } else if (mutation == 1) {
      outer.object.at("element_count") = parseJson(
          rawInteger128Value(Rose::Integer128Value::fromBits({3, 0}, true)));
      diagnostic = "count disagrees";
    } else if (mutation == 2) {
      operand.object.at("binding_depth") = parseJson("2");
      diagnostic = "no enclosing binding";
    } else if (mutation == 3) {
      operand.object.at("binding_depth") = parseJson("1");
      diagnostic = "innermost binding";
    } else if (mutation == 4) {
      operand.object.emplace("binding", parseJson("1"));
      diagnostic = "exactly one binding identity";
    } else if (mutation == 5) {
      operand.object.at("value_category") =
          parseJson(std::to_string(SgCastExp::e_value_category_lvalue));
      diagnostic = "inconsistent value category";
    } else if (mutation == 6) {
      operand.object.at("reference_kind") = parseJson("99");
      diagnostic = "invalid reference_kind enum value";
    } else if (mutation == 7) {
      outer.object.at("binding").object.at("common_source") =
          inner.object.at("element_initializer")
              .object.at("properties")
              .object.at("lhs_operand");
      diagnostic = "no enclosing binding";
    } else if (mutation == 8) {
      outer.object.at("binding").object.erase("common_value_category");
      diagnostic = "missing key: common_value_category";
    } else if (mutation == 9) {
      inner.object.at("binding").object.at("common_value_category") =
          parseJson(std::to_string(SgCastExp::e_value_category_prvalue));
      diagnostic = "reference has invalid typed input";
    } else {
      auto &reference =
          inner.object.at("element_initializer").object.at("properties");
      if (mutation == 10) {
        reference.object.erase("result_storage_size_bytes");
        diagnostic = "missing key: result_storage_size_bytes";
      } else if (mutation == 11) {
        reference.object.at("result_storage_size_bytes") = parseJson("-1");
        diagnostic = "storage size is negative";
      } else if (mutation == 12) {
        reference.object.at("result_storage_size_bytes") = parseJson("1.5");
        diagnostic = "number is not an integer";
      } else if (mutation == 13) {
        reference.object.erase("subscript_stride_bits");
        diagnostic = "missing key: subscript_stride_bits";
      } else if (mutation == 14) {
        reference.object.at("subscript_stride_bits") = parseJson("null");
        diagnostic = "subscript strides must be an array";
      } else if (mutation == 15) {
        reference.object.at("subscript_stride_bits") = parseJson("[1.5]");
        diagnostic = "number is not an integer";
      } else {
        reference.object.at("subscript_stride_bits") = parseJson("[4, 4]");
        diagnostic = "subscript stride count disagrees";
      }
    }
    require_rejected(malformed, diagnostic);
  }
  auto *original_pointer = SageBuilder::buildPointerType(matrix);
  const auto pointer_key = original_pointer->get_mangled();
  auto *original_index =
      SgNode::get_globalTypeTable()->lookup_type(pointer_key);
  auto pointer_result = serialized;
  pointer_result.object.at("properties").object.at("type") =
      parseJson(rawTypeJson(original_pointer, {}));
  require_rejected(pointer_result, "count disagrees");
  ROSE_ASSERT(matrix->get_ptr_to() == original_pointer);
  ROSE_ASSERT(SgNode::get_globalTypeTable()->lookup_type(pointer_key) ==
              original_index);

  std::vector<SgNode *> owned;
  std::function<void(SgNode *)> collect = [&](SgNode *node) {
    owned.push_back(node);
    for (auto *child : node->get_traversalSuccessorContainer())
      if (child != nullptr)
        collect(child);
  };
  collect(original);
  std::unordered_map<const SgNode *, uint64_t> ids;
  for (size_t index = 0; index < owned.size(); ++index)
    ids.emplace(owned[index], index + 1);
  std::vector<NodeRecord> records;
  for (SgNode *node : owned) {
    std::ostringstream output;
    writeNodeJson(output, node, ids, false);
    const auto json = parseJson(output.str());
    NodeRecord record;
    record.id = json.requiredInt("id");
    record.kind = json.requiredString("kind");
    record.variant = static_cast<VariantT>(json.requiredInt("variant"));
    record.flags = json.at("flags");
    record.location = json.at("location");
    record.properties = json.at("properties");
    record.preprocessing = record.properties.at("preprocessing");
    for (const auto &edge : json.at("edges").array)
      record.edges.push_back({edge.requiredString("field"),
                              static_cast<uint64_t>(edge.requiredInt("target")),
                              static_cast<size_t>(edge.requiredInt("index"))});
    records.push_back(std::move(record));
  }
  std::reverse(records.begin(), records.end());
  auto *outside_bound = SageBuilder::buildIntVal_nfi(1);
  semantic(outside_bound);
  auto *outside = SageBuilder::buildNewExp_nfi(
      matrix, SgPointerType::createType(matrix), outside_bound,
      SgNewExp::e_written_array_bound, nullptr, nullptr, nullptr, 0, nullptr,
      1);
  semantic(outside);
  NodeRecord outside_record;
  outside_record.id = owned.size() + 1;
  outside_record.kind = "SgNewExp";
  outside_record.flags = parseJson(rawNodeFlagsJson(outside));
  outside_record.location = parseJson(rawLocationJson(outside));
  outside_record.properties = parseJson(rawNodeProperties(outside, ids));
  NodeRecord bound_record;
  bound_record.id = owned.size() + 2;
  bound_record.kind = "SgIntVal";
  bound_record.flags = parseJson(rawNodeFlagsJson(outside_bound));
  bound_record.location = parseJson(rawLocationJson(outside_bound));
  bound_record.properties = parseJson(rawNodeProperties(outside_bound, ids));
  bound_record.edges = {{"parent", outside_record.id, 0}};
  outside_record.edges = {{"array_bound", bound_record.id, 0}};
  records.push_back(bound_record);
  records.push_back(outside_record);
  SageInterface::deleteAST(outside);
  for (int mutation = 0; mutation != 11; ++mutation) {
    const bool malformed = mutation != 0;
    auto graph = recordGraph(records);
    std::string diagnostic = "invalid typed operands";
    if (mutation == 1)
      graph.nodes.at(graph.index_by_id.at(ids.at(original)))
          .properties.object.at("element_count") = parseJson(
          rawInteger128Value(Rose::Integer128Value::fromBits({3, 0}, true)));
    else if (mutation == 2) {
      auto *index = isSgPntrArrRefExp(inner_source)->get_rhs_operand_i();
      auto &record = graph.nodes.at(graph.index_by_id.at(ids.at(index)));
      record.properties.object.at("binding") =
          parseJson(std::to_string(ids.at(inner_binding)));
      for (auto &edge : record.edges)
        if (edge.field == "binding")
          edge.target = ids.at(inner_binding);
      diagnostic = "no enclosing element binding";
    } else if (mutation == 3) {
      auto &record = graph.nodes.at(graph.index_by_id.at(ids.at(original)));
      for (auto &edge : record.edges)
        if (edge.field == "element_initializer")
          edge.target = ids.at(outer_binding);
      diagnostic = "no enclosing element binding";
    } else if (mutation >= 4) {
      auto &properties =
          graph.nodes.at(graph.index_by_id.at(ids.at(inner_element)))
              .properties;
      if (mutation == 4) {
        properties.object.erase("result_storage_size_bytes");
        diagnostic = "missing key: result_storage_size_bytes";
      } else if (mutation == 5) {
        properties.object.at("result_storage_size_bytes") = parseJson("-1");
        diagnostic = "storage size is negative";
      } else if (mutation == 6) {
        properties.object.at("result_storage_size_bytes") = parseJson("1.5");
        diagnostic = "number is not an integer";
      } else if (mutation == 7) {
        properties.object.erase("subscript_stride_bits");
        diagnostic = "missing key: subscript_stride_bits";
      } else if (mutation == 8) {
        properties.object.at("subscript_stride_bits") = parseJson("null");
        diagnostic = "subscript strides must be an array";
      } else if (mutation == 9) {
        properties.object.at("subscript_stride_bits") = parseJson("[1.5]");
        diagnostic = "number is not an integer";
      } else {
        properties.object.at("subscript_stride_bits") = parseJson("[4, 4]");
        diagnostic = "subscript stride count disagrees";
      }
    }
    NodeMap nodes;
    for (const auto &record : graph.nodes)
      if (!requiresDelayedRebuild(record) ||
          isJsonScalarLiteralKind(record.kind)) {
        auto *node = createNodeFromRecord(record, nullptr);
        validateConstructionFlags(record).initialize(node);
        nodes.emplace(record.id, node);
      }
    const auto borrowed = nodes;
    const auto loops = SgCxxArrayInitLoop::numberOfNodes();
    const auto bindings = SgCxxArrayInitBinding::numberOfNodes();
    const auto references = Reference::numberOfNodes();
    const auto arrays = SgArrayType::numberOfNodes();
    const auto values = SgIntVal::numberOfNodes();
    const auto positions = Sg_File_Info::numberOfNodes();
    const auto new_expressions = SgNewExp::numberOfNodes();
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(graph, nodes);
    } catch (const std::runtime_error &error) {
      if (!malformed ||
          std::string(error.what()).find(diagnostic) == std::string::npos)
        throw;
      rejected = true;
    }
    ROSE_ASSERT(rejected == malformed);
    if (malformed) {
      ROSE_ASSERT(nodes == borrowed);
      ROSE_ASSERT(loops == SgCxxArrayInitLoop::numberOfNodes());
      ROSE_ASSERT(bindings == SgCxxArrayInitBinding::numberOfNodes());
      ROSE_ASSERT(references == Reference::numberOfNodes());
      ROSE_ASSERT(arrays == SgArrayType::numberOfNodes());
      ROSE_ASSERT(values == SgIntVal::numberOfNodes());
      ROSE_ASSERT(positions == Sg_File_Info::numberOfNodes());
      ROSE_ASSERT(new_expressions == SgNewExp::numberOfNodes());
      for (const auto &[id, node] : borrowed) {
        ROSE_ASSERT(node->get_parent() == nullptr);
        SageInterface::deleteAST(node);
      }
    } else {
      auto *copy = isSgCxxArrayInitLoop(nodes.at(ids.at(original)));
      check(copy);
      auto *dependent = isSgNewExp(nodes.at(outside_record.id));
      ROSE_ASSERT(dependent != nullptr &&
                  dependent->get_specified_type() == copy->get_type());
      SageInterface::deleteAST(dependent);
      SageInterface::deleteAST(copy);
    }
  }
  SageInterface::deleteAST(original);
}

void requireGraphNewConstruction() {
  using namespace Rose::AstJson;
  auto *base = SageBuilder::buildIntType();
  auto make_new = [&] {
    auto *expression = SageBuilder::buildNewExp_nfi(
        base, SgPointerType::createType(base), nullptr,
        SgNewExp::e_no_array_bound, nullptr, nullptr, nullptr, 0, nullptr, 1);
    SageBuilder::initializeSemanticExpressionSourceProvenance(expression);
    return expression;
  };
  auto *original = make_new();
  NodeRecord outer;
  outer.id = 1;
  outer.kind = "SgNewExp";
  outer.flags = parseJson(rawNodeFlagsJson(original));
  outer.location = parseJson(rawLocationJson(original));
  outer.properties = parseJson(rawNodeProperties(original, {}));
  outer.edges = {{"placement_args", 2, 0}};
  NodeRecord inner = outer;
  inner.id = 3;
  inner.edges = {{"parent", 2, 0}, {"placement_args", 4, 0}};
  SageInterface::deleteAST(original);
  const auto count = SgNewExp::numberOfNodes();
  bool factory_rejected = false;
  try {
    std::unique_ptr<SgNode> unexpected(createNodeFromRecord(outer, nullptr));
  } catch (const std::runtime_error &error) {
    factory_rejected =
        std::string(error.what())
            .find("requires exact type and operand construction") !=
        std::string::npos;
  }
  ROSE_ASSERT(factory_rejected && SgNewExp::numberOfNodes() == count);
  for (int mutation = 0; mutation != 8; ++mutation) {
    const bool duplicate = mutation == 1;
    NodeMap nodes{{2, new SgExprListExp()},
                  {4, new SgExprListExp()},
                  {5, SageBuilder::buildIntVal_nfi(7, "7")}};
    AstFileRecord ast;
    ast.nodes = {outer, inner};
    for (const auto &[id, parent] :
         std::vector<std::pair<uint64_t, uint64_t>>{{2, 1}, {4, 3}, {5, 4}}) {
      NodeRecord record;
      record.id = id;
      record.kind = nodes.at(id)->class_name();
      record.edges = {{"parent", parent, 0}};
      if (id == 2)
        record.edges.push_back({"expressions", 3, 0});
      if (id == 4) {
        record.edges.push_back({"expressions", 5, 0});
        if (duplicate)
          record.edges.push_back({"expressions", 5, 1});
      }
      ast.nodes.push_back(record);
    }
    std::string diagnostic = "conflicting ownership";
    if (mutation >= 6) {
      ast.nodes.front().properties.object.at(
          "allocation_implicit_argument_count") =
          parseJson(mutation == 6 ? "0" : "4");
      diagnostic = "implicit argument count is out of range";
    } else if (mutation >= 2) {
      const char *field = mutation < 4 ? "allocation_implicit_argument_count"
                                       : "array_bound_source_form";
      if (mutation % 2 == 0) {
        ast.nodes.front().properties.object.erase(field);
        diagnostic = std::string("missing key: ") + field;
      } else {
        ast.nodes.front().properties.object.at(field) = parseJson("true");
        diagnostic = "value is not a number";
      }
    }
    nodes.at(5)->set_parent(nodes.at(4));
    if (mutation != 0) {
      bool rejected = false;
      try {
        rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      } catch (const std::runtime_error &error) {
        rejected =
            std::string(error.what()).find(diagnostic) != std::string::npos;
      }
      ROSE_ASSERT(rejected && nodes.count(1) == 0 && nodes.count(3) == 0);
      ROSE_ASSERT(SgNewExp::numberOfNodes() == count);
      ROSE_ASSERT(isSgExprListExp(nodes.at(2))->get_expressions().empty());
      ROSE_ASSERT(isSgExprListExp(nodes.at(4))->get_expressions().empty());
      ROSE_ASSERT(nodes.at(5)->get_parent() == nodes.at(4));
      nodes.at(5)->set_parent(nullptr);
      for (uint64_t id : {5, 4, 2})
        SageInterface::deleteAST(nodes.at(id));
    } else {
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      auto *root = isSgNewExp(nodes.at(1));
      auto *nested = isSgNewExp(nodes.at(3));
      ROSE_ASSERT(root->get_type() == base->get_ptr_to());
      ROSE_ASSERT(nested->get_type() == root->get_type());
      ROSE_ASSERT(root->get_placement_args()->get_expressions().front() ==
                  nested);
      ROSE_ASSERT(nested->get_parent() == root->get_placement_args());
      ROSE_ASSERT(nested->get_placement_args()->get_expressions().front() ==
                  nodes.at(5));
      linkNodeEdges(outer, nodes);
      linkNodeEdges(inner, nodes);
      SageInterface::deleteAST(root);
      ROSE_ASSERT(SgNewExp::numberOfNodes() == count);
    }
  }
}

void requireGraphBinaryConstruction() {
  using namespace Rose::AstJson;
  auto *type = SageBuilder::buildIntType();
  auto *inner =
      SageBuilder::buildAddOp(SageBuilder::buildIntVal_nfi(7, "7"),
                              SageBuilder::buildIntVal_nfi(8, "8"), type);
  auto *outer = SageBuilder::buildAddOp(
      inner, SageBuilder::buildIntVal_nfi(9, "9"), type);
  // Non-_nfi builders already classify source provenance during construction;
  // explicit classification here would double-classify the nested operands.
  std::unordered_map<const SgNode *, uint64_t> ids{
      {outer, 1},
      {inner, 2},
      {outer->get_rhs_operand(), 3},
      {inner->get_lhs_operand(), 4},
      {inner->get_rhs_operand(), 5}};
  AstFileRecord ast;
  for (SgNode *node : std::vector<SgNode *>{
           outer, inner, outer->get_rhs_operand(), inner->get_lhs_operand(),
           inner->get_rhs_operand()}) {
    NodeRecord record;
    record.id = ids.at(node);
    record.kind = node->class_name();
    if (isSgAddOp(node) != nullptr) {
      record.flags = parseJson(rawNodeFlagsJson(node));
      record.location = parseJson(rawLocationJson(node));
      record.properties = parseJson(rawNodeProperties(node, ids));
    }
    ast.nodes.push_back(record);
  }
  ast.nodes[0].edges = {{"lhs_operand_i", 2, 0}, {"rhs_operand_i", 3, 0}};
  ast.nodes[1].edges = {
      {"parent", 1, 0}, {"lhs_operand_i", 4, 0}, {"rhs_operand_i", 5, 0}};
  ast.nodes[2].edges = {{"parent", 1, 0}};
  ast.nodes[3].edges = {{"parent", 2, 0}};
  ast.nodes[4].edges = {{"parent", 2, 0}};
  const NodeRecord outer_record = ast.nodes[0];
  const NodeRecord inner_record = ast.nodes[1];
  SageInterface::deleteAST(outer);
  const auto sums = SgAddOp::numberOfNodes();
  const auto arrows = SgArrowExp::numberOfNodes();
  const auto values = SgIntVal::numberOfNodes();
  bool factory_rejected = false;
  try {
    std::unique_ptr<SgNode> unexpected(
        createNodeFromRecord(outer_record, nullptr));
  } catch (const std::runtime_error &error) {
    factory_rejected =
        std::string(error.what())
            .find("requires exact operand and type construction") !=
        std::string::npos;
  }
  ROSE_ASSERT(factory_rejected && SgAddOp::numberOfNodes() == sums);
  for (bool shared : {false, true}) {
    NodeMap nodes{{3, SageBuilder::buildIntVal_nfi(9, "9")},
                  {4, SageBuilder::buildIntVal_nfi(7, "7")},
                  {5, SageBuilder::buildIntVal_nfi(8, "8")}};
    AstFileRecord attempt;
    attempt.nodes = {outer_record, inner_record, ast.nodes[2], ast.nodes[3],
                     ast.nodes[4]};
    if (shared)
      attempt.nodes[0].edges = {{"lhs_operand_i", 2, 0},
                                {"rhs_operand_i", 2, 0}};
    if (shared) {
      bool rejected = false;
      try {
        rebuildConstructorOnlyNodes(recordGraph(attempt.nodes), nodes);
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what()).find("distinct unowned") !=
                   std::string::npos;
      }
      ROSE_ASSERT(rejected && nodes.count(1) == 0 && nodes.count(2) == 1);
      ROSE_ASSERT(SgAddOp::numberOfNodes() == sums + 1);
      auto *restored_inner = isSgAddOp(nodes.at(2));
      ROSE_ASSERT(restored_inner->get_parent() == nullptr);
      ROSE_ASSERT(restored_inner->get_lhs_operand_i() == nodes.at(4));
      ROSE_ASSERT(restored_inner->get_rhs_operand_i() == nodes.at(5));
      ROSE_ASSERT(nodes.at(3)->get_parent() == nullptr);
      SageInterface::deleteAST(restored_inner);
      SageInterface::deleteAST(nodes.at(3));
      ROSE_ASSERT(SgAddOp::numberOfNodes() == sums);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
    } else {
      // Outer-before-inner record order must still construct inner first.
      std::reverse(attempt.nodes.begin(), attempt.nodes.end());
      rebuildConstructorOnlyNodes(recordGraph(attempt.nodes), nodes);
      auto *root = isSgAddOp(nodes.at(1));
      auto *nested = isSgAddOp(nodes.at(2));
      ROSE_ASSERT(root != nullptr && nested != nullptr);
      ROSE_ASSERT(root->get_type() == type && nested->get_type() == type);
      ROSE_ASSERT(root->get_lhs_operand_i() == nested &&
                  nested->get_parent() == root);
      ROSE_ASSERT(root->get_rhs_operand_i() == nodes.at(3) &&
                  nodes.at(3)->get_parent() == root);
      ROSE_ASSERT(nested->get_lhs_operand_i() == nodes.at(4) &&
                  nested->get_rhs_operand_i() == nodes.at(5));
      linkNodeEdges(outer_record, nodes);
      linkNodeEdges(inner_record, nodes);
      SageInterface::deleteAST(root);
      ROSE_ASSERT(SgAddOp::numberOfNodes() == sums);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
    }
  }
  for (bool missing : {true, false}) {
    auto malformed = outer_record;
    malformed.kind = "SgArrowExp";
    malformed.properties.object.at("type") = JsonValue::objectValue({});
    if (!missing)
      malformed.properties.object["arrow_emission_role"] =
          JsonValue::number("-1");
    NodeMap nodes{{3, SageBuilder::buildIntVal_nfi(9, "9")},
                  {4, SageBuilder::buildIntVal_nfi(7, "7")},
                  {5, SageBuilder::buildIntVal_nfi(8, "8")}};
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(
          recordGraph({malformed, inner_record, ast.nodes[2], ast.nodes[3],
                       ast.nodes[4]}),
          nodes);
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what()) ==
          (missing ? "AST JSON object is missing key: arrow_emission_role"
                   : "AST JSON SgArrowExp has an invalid "
                     "arrow_emission_role enum value");
    }
    ROSE_ASSERT(rejected && nodes.size() == 3);
    ROSE_ASSERT(SgArrowExp::numberOfNodes() == arrows);
    ROSE_ASSERT(SgAddOp::numberOfNodes() == sums);
    for (const auto &[id, node] : nodes) {
      ROSE_ASSERT(node->get_parent() == nullptr);
      SageInterface::deleteAST(node);
    }
    ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
  }
}

void requireGraphUnaryConstruction() {
  using namespace Rose::AstJson;
  auto *type = SageBuilder::buildIntType();
  auto *minus = SageBuilder::buildMinusOp(SageBuilder::buildIntVal_nfi(7, "7"),
                                          type, SgUnaryOp::prefix);
  // The non-_nfi builder classifies provenance at construction; only the
  // plain-new rethrow below needs explicit classification.
  NodeRecord record;
  record.id = 1;
  record.kind = "SgMinusOp";
  record.flags = parseJson(rawNodeFlagsJson(minus));
  record.location = parseJson(rawLocationJson(minus));
  record.properties = parseJson(
      rawNodeProperties(minus, {{minus, 1}, {minus->get_operand_i(), 2}}));
  record.edges = {{"operand_i", 2, 0}};
  auto *rethrow = new SgThrowOp(nullptr, SageBuilder::buildVoidType(),
                                SgUnaryOp::prefix, SgThrowOp::rethrow);
  SageBuilder::initializeSemanticExpressionSourceProvenance(rethrow);
  NodeRecord rethrow_record;
  rethrow_record.id = 3;
  rethrow_record.kind = "SgThrowOp";
  rethrow_record.flags = parseJson(rawNodeFlagsJson(rethrow));
  rethrow_record.location = parseJson(rawLocationJson(rethrow));
  rethrow_record.properties =
      parseJson(rawNodeProperties(rethrow, {{rethrow, 3}}));
  SageInterface::deleteAST(minus);
  SageInterface::deleteAST(rethrow);
  const auto counts = SgMinusOp::numberOfNodes();
  const auto throws = SgThrowOp::numberOfNodes();
  const auto values = SgIntVal::numberOfNodes();
  const auto positions = Sg_File_Info::numberOfNodes();
  bool factory_rejected = false;
  try {
    std::unique_ptr<SgNode> unexpected(createNodeFromRecord(record, nullptr));
  } catch (const std::runtime_error &error) {
    factory_rejected =
        std::string(error.what())
            .find("requires exact operand and type construction") !=
        std::string::npos;
  }
  ROSE_ASSERT(factory_rejected && SgMinusOp::numberOfNodes() == counts);
  {
    NodeMap nodes{{2, SageBuilder::buildIntVal_nfi(7, "7")}};
    NodeRecord leaf;
    leaf.id = 2;
    leaf.kind = "SgIntVal";
    leaf.edges = {{"parent", 1, 0}};
    AstFileRecord ast;
    ast.nodes = {leaf, record};
    rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    auto *restored = isSgMinusOp(nodes.at(1));
    ROSE_ASSERT(restored != nullptr && restored->get_type() == type);
    ROSE_ASSERT(restored->get_mode() == SgUnaryOp::prefix);
    ROSE_ASSERT(restored->get_operand_i() == nodes.at(2) &&
                nodes.at(2)->get_parent() == restored);
    linkNodeEdges(record, nodes);
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgMinusOp::numberOfNodes() == counts);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
  }
  {
    // A non-rethrow operation without its operand edge must be rejected
    // before allocation.
    NodeRecord missing = record;
    missing.edges.clear();
    NodeMap nodes;
    AstFileRecord missing_ast;
    missing_ast.nodes = {missing};
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph(missing_ast.nodes), nodes);
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what()).find("exact operand") != std::string::npos;
    }
    ROSE_ASSERT(rejected && nodes.empty());
    ROSE_ASSERT(SgMinusOp::numberOfNodes() == counts);
  }
  {
    // A rethrow without an operand is the only valid absent-operand graph.
    NodeMap nodes;
    AstFileRecord ast;
    ast.nodes = {rethrow_record};
    rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    auto *restored = isSgThrowOp(nodes.at(3));
    ROSE_ASSERT(restored != nullptr &&
                restored->get_throwKind() == SgThrowOp::rethrow);
    ROSE_ASSERT(restored->get_operand_i() == nullptr);
    linkNodeEdges(rethrow_record, nodes);
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgThrowOp::numberOfNodes() == throws);
  }
  {
    // A rethrow naming an operand must be rejected without publication.
    NodeMap nodes{{2, SageBuilder::buildIntVal_nfi(7, "7")}};
    NodeRecord leaf;
    leaf.id = 2;
    leaf.kind = "SgIntVal";
    leaf.edges = {{"parent", 3, 0}};
    NodeRecord bad = rethrow_record;
    bad.edges = {{"operand_i", 2, 0}};
    AstFileRecord ast;
    ast.nodes = {bad, leaf};
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what()).find("exclusive matching") !=
                 std::string::npos;
    }
    ROSE_ASSERT(rejected && nodes.count(3) == 0);
    ROSE_ASSERT(SgThrowOp::numberOfNodes() == throws);
    ROSE_ASSERT(nodes.at(2)->get_parent() == nullptr);
    SageInterface::deleteAST(nodes.at(2));
    ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
  }
  {
    // A non-void throw result must be rejected before allocation even though
    // the rethrow shape is otherwise valid.
    NodeRecord bad = rethrow_record;
    bad.properties.object.at("type") =
        parseJson(rawTypeJson(SageBuilder::buildIntType(), {}));
    NodeMap nodes;
    AstFileRecord ast;
    ast.nodes = {bad};
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what()).find("void") != std::string::npos;
    }
    ROSE_ASSERT(rejected && nodes.empty());
    ROSE_ASSERT(SgThrowOp::numberOfNodes() == throws);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
}

void requireComputedGotoConstruction() {
  using namespace Rose::AstJson;
  auto *literal = SageBuilder::buildIntVal(0);
  auto *selector = SageBuilder::buildCastExp(
      literal, SageBuilder::buildPointerType(SageBuilder::buildVoidType()),
      SgCastExp::e_C_style_cast);
  auto *original = SageBuilder::buildGotoStatement_nfi(selector);
  std::unordered_map<const SgNode *, uint64_t> ids{
      {original, 1}, {selector, 2}, {literal, 3}};
  std::vector<NodeRecord> records;
  for (SgNode *node : std::vector<SgNode *>{original, selector, literal}) {
    NodeRecord record;
    record.id = ids.at(node);
    record.kind = node->class_name();
    record.flags = parseJson(rawNodeFlagsJson(node));
    record.location = parseJson(rawLocationJson(node));
    record.properties = parseJson(rawNodeProperties(node, ids));
    if (node != original)
      record.edges.push_back({"parent", record.id - 1, 0});
    if (node == original)
      record.edges.push_back({"selector_expression", 2, 0});
    else if (node == selector)
      record.edges.push_back({"operand_i", 3, 0});
    records.push_back(std::move(record));
  }
  SageInterface::deleteAST(original);
  const auto gotos = SgGotoStatement::numberOfNodes();
  const auto casts = SgCastExp::numberOfNodes();
  const auto values = SgIntVal::numberOfNodes();
  const auto positions = Sg_File_Info::numberOfNodes();
  bool rejected = false;
  try {
    std::unique_ptr<SgNode> unexpected(
        createNodeFromRecord(records[0], nullptr));
  } catch (const std::runtime_error &error) {
    rejected = std::string(error.what()).find("exact typed selector") !=
               std::string::npos;
  }
  ROSE_ASSERT(rejected && SgGotoStatement::numberOfNodes() == gotos);
  for (int mutation = 0; mutation != 4; ++mutation) {
    auto malformed = records;
    if (mutation == 0)
      malformed[1].edges[0].target = 3;
    else if (mutation == 1)
      malformed[1].kind = "SgNullStatement";
    else
      malformed[0].edges.push_back(
          {mutation == 2 ? "label" : "label_expression", 3, 0});
    NodeMap nodes;
    rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph(malformed), nodes);
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what()).find("invalid selector ownership") !=
                 std::string::npos;
    }
    ROSE_ASSERT(rejected && nodes.empty());
    ROSE_ASSERT(SgGotoStatement::numberOfNodes() == gotos &&
                SgCastExp::numberOfNodes() == casts &&
                SgIntVal::numberOfNodes() == values &&
                Sg_File_Info::numberOfNodes() == positions);
  }
  NodeMap nodes{{3, SageBuilder::buildIntVal(0)}};
  rebuildConstructorOnlyNodes(recordGraph(records), nodes);
  auto *restored = isSgGotoStatement(nodes.at(1));
  ROSE_ASSERT(restored != nullptr &&
              restored->get_selector_expression() == nodes.at(2) &&
              nodes.at(2)->get_parent() == restored);
  linkNodeEdges(records[0], nodes);
  linkNodeEdges(records[1], nodes);
  for (int mutation = 0; mutation != 3; ++mutation) {
    auto changed = records[0];
    if (mutation == 0)
      changed.edges.clear();
    else if (mutation == 1)
      changed.edges[0].target = 3;
    else
      changed.edges.push_back({"label", 3, 0});
    rejected = false;
    try {
      linkNodeEdges(changed, nodes);
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what()).find("changed its constructed") !=
                 std::string::npos;
    }
    ROSE_ASSERT(rejected &&
                restored->get_selector_expression() == nodes.at(2) &&
                nodes.at(2)->get_parent() == restored &&
                restored->get_label() == nullptr);
  }
  SageInterface::deleteAST(restored);
  ROSE_ASSERT(SgGotoStatement::numberOfNodes() == gotos &&
              SgCastExp::numberOfNodes() == casts &&
              SgIntVal::numberOfNodes() == values &&
              Sg_File_Info::numberOfNodes() == positions);
}

void requireOwnedBinaryConstruction() {
  using namespace Rose::AstJson;
  const auto original_mode = SageBuilder::getSourcePositionClassificationMode();
  SageBuilder::setSourcePositionClassificationMode(
      SageBuilder::e_sourcePositionTransformation);
  auto *original = SageBuilder::buildAddOp(SageBuilder::buildIntVal(7),
                                           SageBuilder::buildIntVal(9),
                                           SageBuilder::buildIntType());
  constexpr auto wrappers =
      static_cast<SgExpression::semantic_wrapper_mask_enum>(
          SgExpression::e_all_semantic_wrappers &
          ~SgExpression::e_bound_temporary);
  original->set_semantic_wrapper_mask(
      wrappers, nullptr, SgExpression::e_temporary_storage_full_expression);
  const auto record = parseJson(rawTypeOwnedExpressionRef(original, {}));
  const size_t sums = SgAddOp::numberOfNodes();
  const size_t arrows = SgArrowExp::numberOfNodes();
  const size_t integers = SgIntVal::numberOfNodes();
  const size_t positions = Sg_File_Info::numberOfNodes();
  for (int repeat = 0; repeat != 100; ++repeat) {
    auto *restored = isSgAddOp(expressionFromRef(record, {}));
    ROSE_ASSERT(restored != nullptr &&
                restored->get_type() == original->get_type());
    ROSE_ASSERT(restored->get_semantic_wrapper_mask() == wrappers);
    ROSE_ASSERT(restored->get_materialized_storage_duration() ==
                SgExpression::e_temporary_storage_full_expression);
    ROSE_ASSERT(restored->get_materialized_lifetime_owner() == nullptr);
    auto *lhs = isSgIntVal(restored->get_lhs_operand_i());
    auto *rhs = isSgIntVal(restored->get_rhs_operand_i());
    ROSE_ASSERT(lhs != nullptr && lhs->get_value() == 7 &&
                lhs->get_parent() == restored);
    ROSE_ASSERT(rhs != nullptr && rhs->get_value() == 9 &&
                rhs->get_parent() == restored);
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgAddOp::numberOfNodes() == sums);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == integers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    for (int mutation = 0; mutation != 19; ++mutation) {
      auto malformed = record;
      auto &properties = malformed.object.at("properties");
      if (mutation == 0)
        properties.object.erase("lhs_operand");
      else if (mutation == 1)
        properties.object.at("rhs_operand") = parseJson(R"({"node":0})");
      else if (mutation == 2)
        properties.object.at("type") = parseJson(R"({"present":false})");
      else if (mutation == 3)
        properties.object.at("lhs_operand") = parseJson(R"({"node":1})");
      else if (mutation == 4)
        properties.object.at("semantic_wrapper_mask") = parseJson("4294967296");
      else if (mutation == 5) {
        properties.object.at("fortran_integer_constant_value") =
            JsonValue::number("1");
        malformed.object.at("original_expression") = JsonValue::objectValue({});
      } else if (mutation == 8) {
        properties.object.at("semantic_wrapper_mask") =
            parseJson(std::to_string(SgExpression::e_all_semantic_wrappers));
      } else if (mutation == 9) {
        properties.object.erase("materialized_storage_duration");
      } else if (mutation == 10) {
        properties.object.erase("materialized_lifetime_owner");
      } else if (mutation == 11 || mutation == 12) {
        properties.object.at("materialized_storage_duration") =
            JsonValue::number(mutation == 11 ? "0" : "99");
      } else if (mutation == 13 || mutation == 14) {
        properties.object.at("materialized_lifetime_owner") =
            JsonValue::number(mutation == 13 ? "-1" : "1");
      } else if (mutation == 15 || mutation == 16 || mutation == 18) {
        properties.object.at("materialized_storage_duration") =
            JsonValue::number(std::to_string(
                mutation == 18
                    ? SgExpression::e_temporary_storage_containing_object
                    : SgExpression::e_temporary_storage_automatic));
        if (mutation != 15)
          properties.object.at("materialized_lifetime_owner") =
              JsonValue::number("1");
      } else if (mutation == 17) {
        properties.object.at("semantic_wrapper_mask") = JsonValue::number("0");
      } else {
        malformed.object.at("owned_kind") = JsonValue::string("SgArrowExp");
        properties.object.at("type") = JsonValue::objectValue({});
        malformed.object.at("original_expression") = JsonValue::objectValue({});
        if (mutation == 7)
          properties.object["arrow_emission_role"] = JsonValue::number("-1");
      }
      bool rejected = false;
      try {
        (void)expressionFromRef(malformed, {{1, original->get_lhs_operand()}});
      } catch (const std::runtime_error &error) {
        if (mutation == 5)
          ROSE_ASSERT(std::string(error.what())
                          .find("folded selector value without availability") !=
                      std::string::npos);
        if (mutation == 6 || mutation == 7)
          ROSE_ASSERT(
              std::string(error.what()) ==
              (mutation == 6
                   ? "AST JSON object is missing key: arrow_emission_role"
                   : "AST JSON SgArrowExp has an invalid "
                     "arrow_emission_role enum value"));
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(original->get_lhs_operand()->get_parent() == original &&
                  original->get_rhs_operand()->get_parent() == original);
      ROSE_ASSERT(SgAddOp::numberOfNodes() == sums);
      ROSE_ASSERT(SgArrowExp::numberOfNodes() == arrows);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == integers);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
  }
  const auto functions = SgFunctionDeclaration::numberOfNodes();
  const auto tokens = SgCxxLiteralToken::numberOfNodes();
  for (const char *kind : {"SgFunctionDeclaration", "SgCxxLiteralToken",
                           "SgTypeInt", "rex_invalid_owned_expression"}) {
    auto malformed = record;
    malformed.object.at("owned_kind") = JsonValue::string(kind);
    malformed.object.erase("flags");
    malformed.object.erase("properties");
    malformed.object.erase("original_expression");
    bool rejected = false;
    try {
      (void)expressionFromRef(malformed, {{1, original->get_lhs_operand()}});
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what()) ==
          std::string("AST JSON type-owned kind is not an expression: ") + kind;
    }
    ROSE_ASSERT(rejected);
    ROSE_ASSERT(original->get_lhs_operand()->get_parent() == original &&
                original->get_rhs_operand()->get_parent() == original);
    ROSE_ASSERT(SgFunctionDeclaration::numberOfNodes() == functions);
    ROSE_ASSERT(SgCxxLiteralToken::numberOfNodes() == tokens);
    ROSE_ASSERT(SgAddOp::numberOfNodes() == sums);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == integers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  SageInterface::deleteAST(original);
  SageBuilder::setSourcePositionClassificationMode(original_mode);
}

void requireDefinedUnaryConstruction() {
  using namespace Rose::AstJson;
  auto *file = SageBuilder::buildGeneratedSourceFile("rex_defined_unary.f90");
  std::unique_ptr<SgProject, DeleteFixtureAst> project(file->get_project());
  auto *resultType = SageBuilder::buildFloatType();
  auto *parameters = SageBuilder::buildFunctionParameterList();
  parameters->append_arg(SageBuilder::buildInitializedName_nfi(
      "value", SageBuilder::buildIntType(), nullptr));
  auto *function = SageBuilder::buildNondefiningFunctionDeclaration(
      SageBuilder::function_declaration_ownership::sourceLexical(),
      "rex_defined_unary", resultType, parameters, file->get_globalScope());
  auto *symbol =
      isSgFunctionSymbol(function->search_for_symbol_from_symbol_table());
  ROSE_ASSERT(symbol != nullptr);
  std::unique_ptr<SgUserDefinedUnaryOp, DeleteFixtureAst> original(
      new SgUserDefinedUnaryOp(SageBuilder::buildIntVal(7), resultType,
                               SgUnaryOp::prefix, ".rexunary.", symbol));
  SageBuilder::initializeSemanticExpressionSourceProvenance(original.get());
  const NodeMap bindings{{1, function}, {2, file->get_globalScope()}};
  const std::unordered_map<const SgNode *, uint64_t> ids{
      {function, 1}, {file->get_globalScope(), 2}};
  {
    std::unique_ptr<SgFunctionRefExp, DeleteFixtureAst> reference(
        SageBuilder::buildFortranFunctionRefExp_nfi(
            symbol, symbol,
            SgFunctionRefExp::e_fortran_source_visible_binding_exact_typed));
    auto properties = parseJson(rawNodeProperties(reference.get(), ids));
    {
      std::unique_ptr<SgFunctionRefExp, DeleteFixtureAst> restored(
          functionReferenceFromProperties(properties, bindings));
      ROSE_ASSERT(restored->get_symbol() == symbol);
      ROSE_ASSERT(restored->get_fortran_source_visible_symbol() == symbol);
    }
    auto malformed = properties;
    malformed.object.at("type") =
        parseJson(rawTypeJson(SageBuilder::buildIntType(), {}));
    const auto before_references = SgFunctionRefExp::numberOfNodes();
    bool type_rejected = false;
    try {
      std::unique_ptr<SgFunctionRefExp, DeleteFixtureAst> invalid(
          functionReferenceFromProperties(malformed, bindings));
    } catch (const std::runtime_error &error) {
      ROSE_ASSERT(std::string(error.what()).find("function reference type") !=
                  std::string::npos);
      type_rejected = true;
    }
    ROSE_ASSERT(type_rejected &&
                SgFunctionRefExp::numberOfNodes() == before_references);
    auto *scope = file->get_globalScope();
    auto *rename =
        new SgRenameSymbol(function, symbol, "rex_missing_provenance");
    scope->insert_symbol(rename->get_name(), rename);
    for (auto kind :
         {SgFunctionRefExp::
              e_fortran_source_visible_binding_semantic_publication,
          SgFunctionRefExp::e_fortran_source_visible_binding_use_rename,
          SgFunctionRefExp::
              e_fortran_source_visible_binding_generic_overload}) {
      properties.object["fortran_source_visible_binding_kind"] =
          JsonValue::number(std::to_string(kind));
      properties.object["fortran_source_visible_symbol"] =
          parseJson(rawExactBoundSymbolRef(
              kind == SgFunctionRefExp::
                          e_fortran_source_visible_binding_semantic_publication
                  ? symbol
                  : rename,
              ids));
      const auto references = SgFunctionRefExp::numberOfNodes();
      const auto renames = SgRenameSymbol::numberOfNodes();
      bool rejected = false;
      try {
        std::unique_ptr<SgFunctionRefExp, DeleteFixtureAst> unexpected(
            functionReferenceFromProperties(properties, bindings));
      } catch (const std::runtime_error &error) {
        if (std::string(error.what()) != "AST JSON SgFunctionRefExp has no "
                                         "exact Fortran binding for its role")
          throw;
        rejected = true;
      }
      ROSE_ASSERT(rejected && SgFunctionRefExp::numberOfNodes() == references);
      ROSE_ASSERT(SgRenameSymbol::numberOfNodes() == renames);
      ROSE_ASSERT(scope->find_symbol_from_declaration(function) == symbol);
    }
    scope->remove_symbol(rename);
    delete rename;
  }
  const auto encoded =
      parseJson(rawTypeOwnedExpressionRef(original.get(), ids));
  {
    std::unique_ptr<SgUserDefinedUnaryOp, DeleteFixtureAst> restored(
        isSgUserDefinedUnaryOp(expressionFromRef(encoded, bindings)));
    ROSE_ASSERT(restored != nullptr && restored->get_symbol() == symbol);
    ROSE_ASSERT(restored->get_type() == resultType);
    ROSE_ASSERT(restored->get_operand_i() != original->get_operand_i());
  }
  NodeRecord record;
  record.id = 3;
  record.kind = original->class_name();
  record.flags = parseJson(rawNodeFlagsJson(original.get()));
  record.location = parseJson(rawLocationJson(original.get()));
  record.properties = parseJson(rawNodeProperties(original.get(), ids));
  record.edges = {{"operand_i", 4, 0}};
  NodeRecord leaf;
  leaf.id = 4;
  leaf.kind = "SgIntVal";
  leaf.edges = {{"parent", 3, 0}};
  {
    NodeMap nodes = bindings;
    nodes.emplace(4, SageBuilder::buildIntVal(7));
    rebuildConstructorOnlyNodes(recordGraph({leaf, record}), nodes);
    std::unique_ptr<SgUserDefinedUnaryOp, DeleteFixtureAst> restored(
        isSgUserDefinedUnaryOp(nodes.at(3)));
    ROSE_ASSERT(restored != nullptr && restored->get_symbol() == symbol);
    ROSE_ASSERT(restored->get_type() == resultType);
    linkNodeEdges(record, nodes);
  }
  for (int invalid = 0; invalid != 4; ++invalid) {
    auto malformed = encoded;
    auto &properties = malformed.object.at("properties");
    if (invalid == 0)
      properties.object.erase("operator_name");
    else if (invalid == 1)
      properties.object.at("operator_name") = JsonValue::string("");
    else if (invalid == 2)
      properties.object.at("symbol") = parseJson("null");
    else
      properties.object.at("mode") =
          JsonValue::number(std::to_string(SgUnaryOp::postfix));
    const auto count = SgUserDefinedUnaryOp::numberOfNodes();
    const auto values = SgIntVal::numberOfNodes();
    bool rejected = false;
    try {
      std::unique_ptr<SgNode, DeleteFixtureAst> unexpected(
          expressionFromRef(malformed, bindings));
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected && SgUserDefinedUnaryOp::numberOfNodes() == count);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
  }
}

void requireOwnedUnaryConstruction() {
  using namespace Rose::AstJson;
  const auto original_mode = SageBuilder::getSourcePositionClassificationMode();
  SageBuilder::setSourcePositionClassificationMode(
      SageBuilder::e_sourcePositionTransformation);
  auto *original =
      SageBuilder::buildMinusOp(SageBuilder::buildIntVal(7),
                                SageBuilder::buildIntType(), SgUnaryOp::prefix);
  const auto record = parseJson(rawTypeOwnedExpressionRef(original, {}));
  const size_t counts = SgMinusOp::numberOfNodes();
  const size_t integers = SgIntVal::numberOfNodes();
  const size_t positions = Sg_File_Info::numberOfNodes();
  for (int repeat = 0; repeat != 100; ++repeat) {
    auto *restored = isSgMinusOp(expressionFromRef(record, {}));
    ROSE_ASSERT(restored != nullptr &&
                restored->get_type() == original->get_type());
    ROSE_ASSERT(restored->get_mode() == SgUnaryOp::prefix);
    auto *operand = isSgIntVal(restored->get_operand_i());
    ROSE_ASSERT(operand != nullptr && operand->get_value() == 7 &&
                operand->get_parent() == restored);
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgMinusOp::numberOfNodes() == counts);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == integers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    for (int mutation = 0; mutation != 4; ++mutation) {
      auto malformed = record;
      auto &properties = malformed.object.at("properties");
      if (mutation == 0)
        properties.object.erase("operand");
      else if (mutation == 1)
        properties.object.at("operand") = parseJson(R"({"node":1})");
      else if (mutation == 2)
        properties.object.at("type") = parseJson(R"({"present":false})");
      else
        properties.object.at("mode") =
            JsonValue::number(std::to_string(SgUnaryOp::postfix));
      bool rejected = false;
      try {
        (void)expressionFromRef(malformed, {{1, original->get_operand_i()}});
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(original->get_operand_i()->get_parent() == original);
      ROSE_ASSERT(SgMinusOp::numberOfNodes() == counts);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == integers);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
  }
  SageInterface::deleteAST(original);
  auto *rethrow_original = new SgThrowOp(nullptr, SageBuilder::buildVoidType(),
                                         SgUnaryOp::prefix, SgThrowOp::rethrow);
  SageBuilder::initializeSemanticExpressionSourceProvenance(rethrow_original);
  const auto rethrow_record =
      parseJson(rawTypeOwnedExpressionRef(rethrow_original, {}));
  const size_t throws = SgThrowOp::numberOfNodes();
  const size_t rethrow_positions = Sg_File_Info::numberOfNodes();
  for (int repeat = 0; repeat != 100; ++repeat) {
    auto *restored = isSgThrowOp(expressionFromRef(rethrow_record, {}));
    ROSE_ASSERT(restored != nullptr &&
                restored->get_throwKind() == SgThrowOp::rethrow);
    ROSE_ASSERT(restored->get_operand_i() == nullptr);
    ROSE_ASSERT(restored->get_type() == rethrow_original->get_type());
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgThrowOp::numberOfNodes() == throws);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == rethrow_positions);
  }
  {
    // A non-void throw result must be rejected before allocation even though
    // the rethrow shape is otherwise valid.
    auto malformed = rethrow_record;
    malformed.object.at("properties").object.at("type") =
        parseJson(rawTypeJson(SageBuilder::buildIntType(), {}));
    const size_t bad_throws = SgThrowOp::numberOfNodes();
    const size_t bad_positions = Sg_File_Info::numberOfNodes();
    for (int repeat = 0; repeat != 100; ++repeat) {
      bool rejected = false;
      try {
        (void)expressionFromRef(malformed, {});
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what()).find("void") != std::string::npos;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgThrowOp::numberOfNodes() == bad_throws);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == bad_positions);
    }
  }
  SageInterface::deleteAST(rethrow_original);
  SageBuilder::setSourcePositionClassificationMode(original_mode);
}

void requireThrowResultTypeContract() {
  using namespace Rose::AstJson;
  // The throw void-result invariant aborts inside get_type. Construction must
  // reject a non-void result before allocation, without touching operands.
  // Borrow the operand of a complete holder expression: holder deletion is
  // proven to reclaim the whole subtree, so any surviving node after the
  // contract is a genuine leak.
  const auto throws = SgThrowOp::numberOfNodes();
  const auto values = SgIntVal::numberOfNodes();
  const auto holders = SgMinusOp::numberOfNodes();
  auto *holder =
      SageBuilder::buildMinusOp(SageBuilder::buildIntVal_nfi(7, "7"),
                                SageBuilder::buildIntType(), SgUnaryOp::prefix);
  auto *operand = isSgIntVal(holder->get_operand_i());
  ROSE_ASSERT(operand != nullptr && operand->get_parent() == holder);
  ROSE_ASSERT(SgIntVal::numberOfNodes() == values + 1);
  ROSE_ASSERT(SgMinusOp::numberOfNodes() == holders + 1);
  for (auto kind : {SgThrowOp::throw_expression, SgThrowOp::rethrow}) {
    JsonValue properties =
        parseJson("{\"mode\":" + std::to_string(SgUnaryOp::prefix) +
                  ",\"throw_kind\":" + std::to_string(kind) + "}");
    const auto fields =
        unaryConstructionFieldsFromJson(properties, "SgThrowOp", {});
    for (int repeat = 0; repeat != 100; ++repeat) {
      bool rejected = false;
      try {
        (void)constructUnaryOp("SgThrowOp", operand, fields,
                               SageBuilder::buildIntType());
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what()).find("void") != std::string::npos;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgThrowOp::numberOfNodes() == throws);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == values + 1);
      ROSE_ASSERT(SgMinusOp::numberOfNodes() == holders + 1);
      ROSE_ASSERT(operand->get_parent() == holder);
    }
  }
  SageInterface::deleteAST(holder);
  ROSE_ASSERT(SgThrowOp::numberOfNodes() == throws);
  ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
  ROSE_ASSERT(SgMinusOp::numberOfNodes() == holders);
}

void requireTypedefDeclarationConstruction() {
  using namespace Rose::AstJson;
  auto *integer = SageBuilder::buildIntType();
  const TypedefMetadata metadata{
      SgTypedefDeclaration::e_typedef, false, false, false, false, false, {}};
  // Chain T2 over T1 with records in reverse dependency order: the worklist
  // must schedule the base declaration first without any primed nodes.
  // Fixtures go through the same exact constructor: ROSE deletion
  // traversal requires every typedef declaration to own a wired wrapper.
  auto first =
      std::unique_ptr<SgTypedefDeclaration>(constructTypedefDeclaration(
          SgName("rex_json_t1"), integer, nullptr, false,
          V_SgTypedefDeclaration, nullptr, {}, {}, metadata));
  SageInterface::setSourcePosition(first.get());
  auto second =
      std::unique_ptr<SgTypedefDeclaration>(constructTypedefDeclaration(
          SgName("rex_json_t2"), integer, nullptr, false,
          V_SgTypedefDeclaration, nullptr, {}, {}, metadata));
  SageInterface::setSourcePosition(second.get());
  first->set_source_sequence_value(11);
  second->set_source_sequence_value(23);
  auto record_for = [](uint64_t id, SgTypedefDeclaration *declaration) {
    NodeRecord record;
    record.id = id;
    record.kind = "SgTypedefDeclaration";
    record.flags = parseJson(rawNodeFlagsJson(declaration));
    record.location = parseJson(rawLocationJson(declaration));
    record.properties =
        parseJson(rawNodeProperties(declaration, {{declaration, id}}));
    return record;
  };
  NodeRecord first_record = record_for(1, first.get());
  NodeRecord second_record = record_for(2, second.get());
  second_record.properties.object.at("base_type") = parseJson(
      R"({"present":true,"kind":"SgTypedefType","fortran_source_syntax":false,)"
      R"("declaration":1})");
  const auto declarations = SgTypedefDeclaration::numberOfNodes();
  const auto wrappers = SgTypedefType::numberOfNodes();
  SgTypedefType *firstWrapper = first->get_type();
  for (SgTypedefType *invalidWrapper :
       {static_cast<SgTypedefType *>(nullptr), second->get_type()}) {
    first->set_type(invalidWrapper);
    bool rejected = false;
    try {
      (void)typeFromJson(second_record.properties.at("base_type"),
                         {{1, first.get()}});
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what())
                     .find("no exact constructed declaration wrapper") !=
                 std::string::npos;
    }
    first->set_type(firstWrapper);
    ROSE_ASSERT(rejected && SgTypedefType::numberOfNodes() == wrappers);
  }
  const auto positions = Sg_File_Info::numberOfNodes();
  const auto templates = SgTemplateTypedefDeclaration::numberOfNodes();
  const auto instantiations =
      SgTemplateInstantiationTypedefDeclaration::numberOfNodes();
  const auto typedef_pointers = SgPointerType::numberOfNodes();
  const auto typedef_references = SgReferenceType::numberOfNodes();
  {
    auto source_storage =
        std::make_unique<SgUsingDeclarationStatement>(first.get(), nullptr);
    auto &source = *source_storage;
    source.set_source_terminal_name("rex_json_t1");
    source.set_source_sequence_value(43);
    NodeRecord record;
    record.id = 3;
    record.kind = source.class_name();
    record.flags = parseJson(rawNodeFlagsJson(&source));
    record.location = parseJson(rawLocationJson(&source));
    record.properties =
        parseJson(rawNodeProperties(&source, {{first.get(), 1}}));
    record.edges = {{"declaration", 1, 0}, {"parent", 4, 0}};
    auto graph = recordGraph({record});
    NodeMap nodes{{1, first.get()}};
    auto pending = collectDelayedDeclarations(graph, nodes);
    drainDelayedDeclarations(graph, pending, nodes, true);
    std::unique_ptr<SgUsingDeclarationStatement, DeleteFixtureAst> restored(
        isSgUsingDeclarationStatement(nodes.at(3)));
    ROSE_ASSERT(restored != nullptr &&
                restored->get_declaration() == first.get());
    ROSE_ASSERT(restored->get_source_sequence_value() == 43);
    ROSE_ASSERT(restored->get_parent() == nullptr);
    std::unique_ptr<SgCaseOptionStmt, DeleteFixtureAst> restored_case(
        new SgCaseOptionStmt(SageBuilder::buildIntVal(1), restored.get()));
    restored.release();
    ROSE_ASSERT(restored_case->get_body() == nodes.at(3));
    ROSE_ASSERT(nodes.at(3)->get_parent() == restored_case.get());
  }
  for (const char *kind :
       {"SgTypedefDeclaration", "SgTemplateTypedefDeclaration",
        "SgTemplateInstantiationTypedefDeclaration"}) {
    NodeRecord base_record = first_record;
    NodeRecord dependent = second_record;
    dependent.kind = kind;
    if (dependent.kind == "SgTemplateInstantiationTypedefDeclaration") {
      base_record.kind = "SgTemplateTypedefDeclaration";
      dependent.edges.push_back({"templateDeclaration", 1, 0});
      dependent.properties.object["template_name"] =
          parseJson("\"rex_json_t2\"");
      dependent.properties.object["template_header"] = parseJson("\"\"");
    }
    AstFileRecord ast;
    ast.nodes = {dependent, base_record};
    NodeMap nodes;
    auto pending = collectDelayedDeclarations(ast, nodes);
    drainDelayedDeclarations(ast, pending, nodes, true);
    auto *base = isSgTypedefDeclaration(nodes.at(1));
    auto *chained = isSgTypedefDeclaration(nodes.at(2));
    ROSE_ASSERT(base != nullptr && chained != nullptr);
    ROSE_ASSERT(chained->class_name() == kind);
    ROSE_ASSERT(base->get_base_type() == integer);
    ROSE_ASSERT(base->get_name().getString() == "rex_json_t1");
    auto *chained_base = isSgTypedefType(chained->get_base_type());
    ROSE_ASSERT(chained_base != nullptr &&
                chained_base->get_declaration() == base);
    ROSE_ASSERT(chained->get_name().getString() == "rex_json_t2");
    ROSE_ASSERT(base->get_source_sequence_value() == 11);
    ROSE_ASSERT(chained->get_source_sequence_value() == 23);
    if (auto *instantiation =
            isSgTemplateInstantiationTypedefDeclaration(chained)) {
      ROSE_ASSERT(instantiation->get_templateDeclaration() ==
                  isSgTemplateTypedefDeclaration(base));
    }
    ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() ==
                declarations + (base_record.kind == "SgTypedefDeclaration") +
                    (dependent.kind == "SgTypedefDeclaration"));
    ROSE_ASSERT(SgTemplateTypedefDeclaration::numberOfNodes() ==
                templates +
                    (base_record.kind == "SgTemplateTypedefDeclaration") +
                    (dependent.kind == "SgTemplateTypedefDeclaration"));
    ROSE_ASSERT(SgTemplateInstantiationTypedefDeclaration::numberOfNodes() ==
                instantiations + (dependent.kind ==
                                  "SgTemplateInstantiationTypedefDeclaration"));
    auto *chained_wrapper = isSgTypedefType(chained->get_type());
    ROSE_ASSERT(chained_wrapper != nullptr &&
                chained_wrapper->get_declaration() == chained);
    // The base-type decode reuses the eagerly constructed wrapper instead
    // of installing a competing identity.
    ROSE_ASSERT(base->get_type() == chained_base);
    ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers + 2);
    SageInterface::deleteAST(chained);
    SageInterface::deleteAST(base);
    // Canonical wrappers are owned by their declarations, which whole-tree
    // deletion does not traverse. Reclaim each explicitly when it survives
    // so pool accounting proves the full lifecycle; never double-delete.
    if (SgNode::isLiveNode(chained_base)) {
      delete chained_base;
    }
    if (SgNode::isLiveNode(chained_wrapper)) {
      delete chained_wrapper;
    }
    ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
    ROSE_ASSERT(SgTemplateTypedefDeclaration::numberOfNodes() == templates);
    ROSE_ASSERT(SgTemplateInstantiationTypedefDeclaration::numberOfNodes() ==
                instantiations);
    ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  for (bool malformed_flags : {false, true}) {
    NodeRecord malformed = second_record;
    if (malformed_flags)
      malformed.flags.object.at("is_modified") = parseJson("null");
    else
      malformed.location.object.at("start").object.erase("raw_line");
    auto graph = recordGraph({first_record, malformed});
    NodeMap nodes;
    std::vector<const NodeRecord *> pending{&graph.nodes[0], &graph.nodes[1]};
    const auto sequence = SgNode::get_globalAstModificationSequence();
    bool rejected = false;
    try {
      drainDelayedDeclarations(graph, pending, nodes, true);
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected && nodes.empty() && pending.size() == 2);
    ROSE_ASSERT(SgNode::get_globalAstModificationSequence() == sequence);
    ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
    ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  for (const char *field :
       {"source_sequence_value", "directive_end_kind", "omp_fortran_spelling",
        "binding_label", "declaration_modifier_vector",
        "declaration_storage_modifier", "declaration_type_modifier_vector",
        "declaration_gnu_attribute_visibility",
        "declaration_gnu_type_visibility"}) {
    for (bool missing : {false, true}) {
      NodeRecord malformed = first_record;
      if (missing)
        malformed.properties.object.erase(field);
      else
        malformed.properties.object.at(field) = parseJson("null");
      const auto sequence = SgNode::get_globalAstModificationSequence();
      auto graph = recordGraph({malformed});
      NodeMap nodes;
      bool rejected = false;
      try {
        auto pending = collectDelayedDeclarations(graph, nodes);
        drainDelayedDeclarations(graph, pending, nodes, true);
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected && nodes.empty());
      ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
      ROSE_ASSERT(SgTemplateTypedefDeclaration::numberOfNodes() == templates);
      ROSE_ASSERT(SgTemplateInstantiationTypedefDeclaration::numberOfNodes() ==
                  instantiations);
      ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
      ROSE_ASSERT(SgNode::get_globalAstModificationSequence() == sequence);
    }
  }
  const JsonValue pointed_typedef =
      parseJson(R"({"present":true,"kind":"SgPointerType",)"
                R"("fortran_source_syntax":false,"base":{"present":true,)"
                R"("kind":"SgTypedefType","fortran_source_syntax":false,)"
                R"("declaration":1}})");
  for (SgType *placeholder :
       {static_cast<SgType *>(SageBuilder::buildUnknownType()),
        static_cast<SgType *>(SgTypeDefault::createType())}) {
    first->set_base_type(placeholder);
    bool rejected = false;
    try {
      (void)typeFromJson(pointed_typedef, {{1, first.get()}});
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what()).find("unresolved declaration base type") !=
          std::string::npos;
    }
    first->set_base_type(integer);
    ROSE_ASSERT(rejected);
    ROSE_ASSERT(SgPointerType::numberOfNodes() == typedef_pointers);
    ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
  }
  for (int mutation = 0; mutation != 12; ++mutation) {
    NodeRecord bad = first_record;
    auto &properties = bad.properties.object;
    if (mutation == 0)
      properties.at("base_type") = parseJson(R"({"present":false})");
    else if (mutation == 1)
      properties.at("base_type") =
          parseJson(R"({"present":true,"kind":"SgTypeUnknown",)"
                    R"("fortran_source_syntax":false})");
    else if (mutation == 2)
      properties.erase("base_type");
    else if (mutation == 3)
      properties.erase("typedef_type");
    else if (mutation == 4)
      properties.at("base_type") =
          parseJson(R"({"present":true,"kind":"SgTypedefType",)"
                    R"("fortran_source_syntax":false,)"
                    R"("declaration":999})");
    else if (mutation == 5)
      bad.flags.object.erase("is_modified");
    else if (mutation == 6)
      bad.location = parseJson("null");
    else if (mutation == 7)
      properties.at("base_type") =
          parseJson(R"({"present":true,"kind":"SgTypedefType",)"
                    R"("fortran_source_syntax":false,)"
                    R"("declaration":999})");
    else if (mutation == 8) {
      // A location object with valid start fields but an out-of-range end
      // must fail during restoration without leaking the start position.
      JsonValue partial = first_record.location;
      partial.object.at("end") = parseJson(
          R"({"present":true,"raw_filename":"NULL_FILE","raw_line":2147483648,)"
          R"("raw_column":0,"physical_line":0,"physical_file_id":-1,)"
          R"("physical_internal_file_id":-1,"source_sequence":0,)"
          R"("physical_raw_filename":"","physical_filename":"",)"
          R"("compiler_generated":false,"transformation":false,)"
          R"("frontend_specific":false,"shared":false,)"
          R"("source_position_unavailable_in_frontend":false,)"
          R"("comment_or_directive":false,"token":false,)"
          R"("default_argument":false,"implicit_cast":false,)"
          R"("output_in_code_generation":false})");
      bad.location = partial;
    } else if (mutation == 9) {
      properties.at("base_type") = parseJson(
          R"({"present":true,"kind":"SgPointerType",)"
          R"("fortran_source_syntax":false,"base":{"present":true,)"
          R"("kind":"SgTypeUnknown","fortran_source_syntax":false}})");
    } else if (mutation == 10) {
      properties.at("base_type") = parseJson(
          R"({"present":true,"kind":"SgReferenceType",)"
          R"("fortran_source_syntax":false,"base":{"present":true,)"
          R"("kind":"SgTypeDefault","fortran_source_syntax":false}})");
    } else if (mutation == 11) {
      properties.erase("type_elaboration_required_for_base_type");
    }
    AstFileRecord ast;
    if (mutation == 5 || mutation == 6 || mutation == 8 || mutation == 11) {
      // Malformed input alongside a resolvable valid declaration must fail
      // immediately, before anything is published.
      bad.id = 2;
      ast.nodes = {bad, first_record};
    } else if (mutation == 7) {
      // Duplicate identifiers are rejected at collection, before scheduling.
      ast.nodes = {first_record, bad};
    } else {
      ast.nodes = {bad};
    }
    NodeMap nodes;
    if (mutation == 4) {
      // An unresolvable dependency waits silently in a non-final drain and
      // is reported with its missing identifiers in a final drain. Neither
      // diagnostic is retained from an earlier attempt.
      auto pending = collectDelayedDeclarations(ast, nodes);
      drainDelayedDeclarations(ast, pending, nodes, false);
      ROSE_ASSERT(nodes.empty() && !pending.empty());
      bool reported = false;
      try {
        drainDelayedDeclarations(ast, pending, nodes, true);
      } catch (const std::runtime_error &error) {
        const std::string message = error.what();
        reported = message.find("missing or cyclic") != std::string::npos &&
                   message.find("999") != std::string::npos;
      }
      ROSE_ASSERT(reported && nodes.empty());
    } else {
      bool rejected = false;
      try {
        auto pending = collectDelayedDeclarations(ast, nodes);
        drainDelayedDeclarations(ast, pending, nodes, true);
      } catch (const std::runtime_error &error) {
        rejected =
            std::string(error.what())
                .find(
                    mutation == 0   ? "present base type"
                    : mutation == 1 ? "exact base type"
                    : mutation == 2 ? "missing key: base_type"
                    : mutation == 3 ? "missing key: typedef_type"
                    : mutation == 5 ? "missing key: is_modified"
                    : mutation == 6 ? "location must be an object"
                    : mutation == 8 ? "out of range"
                    : mutation == 11
                        ? "missing key: type_elaboration_required_for_base_type"
                    : mutation >= 9
                        ? "type component requires an exact type"
                        : "duplicate delayed declaration") != std::string::npos;
      }
      ROSE_ASSERT(rejected && nodes.empty());
    }
    ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
    ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    ROSE_ASSERT(SgPointerType::numberOfNodes() == typedef_pointers);
    ROSE_ASSERT(SgReferenceType::numberOfNodes() == typedef_references);
  }
  {
    // A record that is both malformed and unresolvable reports its malformed
    // flags in either drain path: validation precedes scheduling, so the
    // missing dependency never masks the schema failure.
    NodeRecord bad = first_record;
    bad.flags.object.erase("is_modified");
    bad.properties.object.at("base_type") =
        parseJson(R"({"present":true,"kind":"SgTypedefType",)"
                  R"("fortran_source_syntax":false,)"
                  R"("declaration":999})");
    for (bool final : {false, true}) {
      AstFileRecord ast;
      ast.nodes = {bad};
      NodeMap nodes;
      bool flagged = false;
      try {
        auto pending = collectDelayedDeclarations(ast, nodes);
        drainDelayedDeclarations(ast, pending, nodes, final);
      } catch (const std::runtime_error &error) {
        flagged = std::string(error.what()).find("missing key: is_modified") !=
                      std::string::npos &&
                  nodes.empty();
      }
      ROSE_ASSERT(flagged);
      ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
      ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
  }
  for (const char *invalid_id : {"null", "true", "\"1\"", "-1", "1.5"}) {
    NodeRecord bad = second_record;
    bad.properties.object.at("base_type").object.at("declaration") =
        parseJson(invalid_id);
    bad.edges.push_back({"scope", 999, 0});
    AstFileRecord ast;
    ast.nodes = {bad};
    NodeMap nodes;
    auto pending = collectDelayedDeclarations(ast, nodes);
    bool rejected = false;
    try {
      // An unavailable scope must not hide a malformed type dependency.
      drainDelayedDeclarations(ast, pending, nodes, false);
    } catch (const std::runtime_error &error) {
      const std::string message = error.what();
      rejected = message.find("not a number") != std::string::npos ||
                 message.find("not an integer") != std::string::npos ||
                 message.find("must be nonnegative") != std::string::npos;
    }
    ROSE_ASSERT(rejected && nodes.empty() && pending.size() == 1);
    ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
    ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  // A typedef nested inside a pointer base proves recursive dependency
  // collection across scrambled record order.
  auto third =
      std::unique_ptr<SgTypedefDeclaration>(constructTypedefDeclaration(
          SgName("rex_json_t3"), integer, nullptr, false,
          V_SgTypedefDeclaration, nullptr, {}, {}, metadata));
  SageInterface::setSourcePosition(third.get());
  auto *third_fixture_wrapper = isSgTypedefType(third->get_type());
  ROSE_ASSERT(third_fixture_wrapper != nullptr);
  NodeRecord third_record;
  third_record.id = 3;
  third_record.kind = "SgTypedefDeclaration";
  third_record.flags = parseJson(rawNodeFlagsJson(third.get()));
  third_record.location = parseJson(rawLocationJson(third.get()));
  third_record.properties = parseJson(rawNodeProperties(third.get(), {}));
  third_record.properties.object.at("base_type") = parseJson(
      R"({"present":true,"kind":"SgPointerType","fortran_source_syntax":false,)"
      R"("base":{"present":true,"kind":"SgTypedefType",)"
      R"("fortran_source_syntax":false,)"
      R"("declaration":1}})");
  SageInterface::deleteAST(third.release());
  if (SgNode::isLiveNode(third_fixture_wrapper)) {
    delete third_fixture_wrapper;
  }
  ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
  ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
  ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  const auto pointers = SgPointerType::numberOfNodes();
  {
    auto scope_storage = std::make_unique<SgGlobal>();
    auto &scope = *scope_storage;
    NodeRecord scoped_first = first_record;
    scoped_first.edges.push_back({"scope", 4, 0});
    third_record.edges.push_back({"scope", 4, 0});
    AstFileRecord ast;
    ast.nodes = {third_record, scoped_first};
    NodeMap nodes{{4, &scope}};
    auto pending = collectDelayedDeclarations(ast, nodes);
    drainDelayedDeclarations(ast, pending, nodes, true);
    ROSE_ASSERT(pending.empty());
    // This drain interns exactly one canonical pointer type for the nested
    // base; no other contract in this binary names this typedef, so the +1
    // delta proves exclusive fixture ownership of the interned node.
    ROSE_ASSERT(SgPointerType::numberOfNodes() == pointers + 1);
    auto *nested = isSgTypedefDeclaration(nodes.at(3));
    auto *nested_base = isSgPointerType(nested->get_base_type());
    ROSE_ASSERT(nested_base != nullptr);
    auto *nested_target = isSgTypedefType(nested_base->get_base_type());
    auto *nested_wrapper = isSgTypedefType(nested->get_type());
    ROSE_ASSERT(nested_target != nullptr &&
                nested_target->get_declaration() == nodes.at(1));
    ROSE_ASSERT(nested_wrapper != nullptr &&
                nested_wrapper->get_declaration() == nested);
    SageInterface::deleteAST(nested);
    ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations + 1);
    // Native retirement clears the exclusive pointer's reverse cache.
    const auto symbols = SgFunctionTypeSymbol::numberOfNodes();
    ROSE_ASSERT(nested_base->get_parent() == nullptr);
    ROSE_ASSERT(nested_target->get_ptr_to() == nested_base);
    SageInterface::deleteAST(nested_base,
                             SageInterface::DeleteAstMode::kRequireIsolated);
    ROSE_ASSERT(!SgNode::isLiveNode(nested_base));
    ROSE_ASSERT(nested_target->get_ptr_to() == nullptr);
    ROSE_ASSERT(SgFunctionTypeSymbol::numberOfNodes() == symbols);
    SageInterface::deleteAST(nodes.at(1));
    ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
    if (SgNode::isLiveNode(nested_target)) {
      delete nested_target;
    }
    if (SgNode::isLiveNode(nested_wrapper)) {
      delete nested_wrapper;
    }
    ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
    ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  SageInterface::deleteAST(first.release());
  SageInterface::deleteAST(second.release());
}

void requireDelayedDeclarationSplitDrain() {
  using namespace Rose::AstJson;
  // A declaration whose type borrows a not-yet-built expression waits
  // through a non-final drain and completes once the dependency arrives.
  // The borrowed node is adopted by decltype construction; pool accounting
  // covers every outcome without double deletion.
  auto *integer = SageBuilder::buildIntType();
  NodeRecord record;
  record.id = 2;
  record.kind = "SgTypedefDeclaration";
  {
    auto fixture_storage = std::make_unique<SgTypedefDeclaration>(
        nullptr, SgName("rex_json_split"), integer);
    auto &fixture = *fixture_storage;
    fixture.set_typedef_type(SgTypedefDeclaration::e_typedef);
    fixture.set_isAutonomousDeclaration(false);
    fixture.initialize_translation_unit_source_order(17);
    fixture.set_isModified(false);
    record.flags = parseJson(rawNodeFlagsJson(&fixture));
    record.location = parseJson(rawLocationJson(&fixture));
    record.properties = parseJson(rawNodeProperties(&fixture, {}));
    record.location = parseJson(rawLocationJson(&fixture));
  }
  record.properties.object.at("base_type") =
      parseJson(R"({"present":true,"kind":"SgDeclType",)"
                R"("fortran_source_syntax":false,"is_gnu_decltype":false,)"
                R"("base_type":)" +
                rawTypeJson(integer, {}) + R"(,"base_expression":{"node":7}})");
  const auto declarations = SgTypedefDeclaration::numberOfNodes();
  const auto wrappers = SgTypedefType::numberOfNodes();
  const auto values = SgIntVal::numberOfNodes();
  const auto positions = Sg_File_Info::numberOfNodes();
  const auto decltypes = SgDeclType::numberOfNodes();
  AstFileRecord ast;
  ast.nodes = {record};
  NodeMap nodes;
  {
    auto pending = collectDelayedDeclarations(ast, nodes);
    drainDelayedDeclarations(ast, pending, nodes, false);
    ROSE_ASSERT(nodes.empty() && !pending.empty());
    nodes.emplace(7, SageBuilder::buildIntVal_nfi(7, "7"));
    drainDelayedDeclarations(ast, pending, nodes, true);
    ROSE_ASSERT(pending.empty());
  }
  auto *declaration = isSgTypedefDeclaration(nodes.at(2));
  auto *borrowed = isSgIntVal(nodes.at(7));
  ROSE_ASSERT(declaration != nullptr && borrowed != nullptr);
  ROSE_ASSERT(declaration->get_translation_unit_source_order() == 17);
  auto *decltype_base = isSgDeclType(declaration->get_base_type());
  ROSE_ASSERT(decltype_base != nullptr);
  ROSE_ASSERT(decltype_base->get_base_expression() == borrowed);
  auto *wrapper = isSgTypedefType(declaration->get_type());
  ROSE_ASSERT(wrapper != nullptr && wrapper->get_declaration() == declaration);
  // Base types are not traversed from declarations: reclaim the fresh
  // decltype before its adopted operand, then the operand and wrapper, each
  // only when still live, so every sweep outcome balances exactly once.
  SageInterface::deleteAST(declaration);
  if (SgNode::isLiveNode(decltype_base)) {
    delete decltype_base;
  }
  if (SgNode::isLiveNode(borrowed)) {
    SageInterface::deleteAST(borrowed);
  }
  if (SgNode::isLiveNode(wrapper)) {
    delete wrapper;
  }
  ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
  ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
  ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
  ROSE_ASSERT(SgDeclType::numberOfNodes() == decltypes);
  ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);

  auto *size_type = SageBuilder::buildUnsignedLongType();
  record.properties.object.at("base_type").object.at("base_type") =
      parseJson(rawTypeJson(size_type, {}));
  NodeRecord size_record;
  size_record.id = 7;
  size_record.kind = "SgSizeOfOp";
  {
    std::unique_ptr<SgSizeOfOp, DeleteFixtureAst> fixture(
        SageBuilder::buildSizeOfOp_nfi(integer, size_type));
    SageBuilder::initializeSemanticExpressionSourceProvenance(fixture.get());
    size_record.flags = parseJson(rawNodeFlagsJson(fixture.get()));
    size_record.location = parseJson(rawLocationJson(fixture.get()));
    size_record.properties = parseJson(rawNodeProperties(fixture.get(), {}));
  }
  size_record.properties.object.at("type") =
      parseJson(R"({"present":true,"kind":"SgTypedefType",)"
                R"("fortran_source_syntax":false,"declaration":2})");
  const auto sizes = SgSizeOfOp::numberOfNodes();
  for (bool malformed_flags : {false, true}) {
    auto malformed = size_record;
    if (malformed_flags)
      malformed.flags.object.at("is_modified") = parseJson("null");
    else
      malformed.location.object.erase("operator");
    auto graph = recordGraph({record, malformed});
    NodeMap reconstructed;
    auto pending = collectDelayedDeclarations(graph, reconstructed);
    const auto sequence = SgNode::get_globalAstModificationSequence();
    bool rejected = false;
    try {
      drainDelayedDeclarations(graph, pending, reconstructed, true);
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected && reconstructed.empty() && pending.size() == 1);
    ROSE_ASSERT(SgNode::get_globalAstModificationSequence() == sequence);
    ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
    ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
    ROSE_ASSERT(SgDeclType::numberOfNodes() == decltypes);
    ROSE_ASSERT(SgSizeOfOp::numberOfNodes() == sizes);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  for (bool malformed : {true, false}) {
    auto expression_record = size_record;
    if (malformed)
      expression_record.properties.object.at("operand_type") =
          parseJson(rawTypeJson(nullptr, {}));
    auto graph = recordGraph({record, expression_record});
    NodeMap reconstructed;
    auto pending = collectDelayedDeclarations(graph, reconstructed);
    bool rejected = false;
    try {
      drainDelayedDeclarations(graph, pending, reconstructed, true);
    } catch (const std::runtime_error &error) {
      if (std::string(error.what()) !=
          "AST JSON unary trait must have exactly one operand")
        throw;
      rejected = true;
    }
    ROSE_ASSERT(rejected == malformed);
    if (malformed)
      ROSE_ASSERT(reconstructed.empty());
    else {
      auto *alias = isSgTypedefDeclaration(reconstructed.at(2));
      auto *source_type = isSgDeclType(alias->get_base_type());
      auto *expression = isSgSizeOfOp(reconstructed.at(7));
      ROSE_ASSERT(pending.empty() && source_type != nullptr &&
                  source_type->get_parent() == alias);
      ROSE_ASSERT(source_type->get_base_expression() == expression &&
                  expression->get_parent() == source_type);
      ROSE_ASSERT(expression->get_type() == alias->get_type() &&
                  alias->get_type()->get_base_type() == size_type);
      SageInterface::deleteAST(alias,
                               SageInterface::DeleteAstMode::kRequireIsolated);
    }
    ROSE_ASSERT(SgTypedefDeclaration::numberOfNodes() == declarations);
    ROSE_ASSERT(SgTypedefType::numberOfNodes() == wrappers);
    ROSE_ASSERT(SgDeclType::numberOfNodes() == decltypes);
    ROSE_ASSERT(SgSizeOfOp::numberOfNodes() == sizes);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
}

void requireDelayedDeclarationSymbolInsertion() {
  using namespace Rose::AstJson;
  // A symbol-table entry whose basis is a delayed declaration is inserted
  // canonically when the basis builds, so dependent inline expressions
  // resolve through the restored table instead of waiting on it.
  auto *integer = SageBuilder::buildIntType();
  auto *scope = new SgGlobal();
  NodeRecord scope_record;
  scope_record.id = 10;
  scope_record.kind = "SgGlobal";
  scope_record.flags = parseJson(rawNodeFlagsJson(scope));
  scope_record.location = parseJson(rawLocationJson(scope));
  scope_record.properties =
      parseJson(R"({"case_insensitive":false,"symbol_table":[{"symbol_kind":)"
                R"("SgVariableSymbol","entry_name":"rex_json_sym",)"
                R"("symbol":{"symbol_kind":"SgVariableSymbol",)"
                R"("symbol_name":"rex_json_sym","symbol_declaration":2},)"
                R"("lookup_preferred":true}]})");
  NodeRecord name_record;
  name_record.id = 2;
  name_record.kind = "SgInitializedName";
  name_record.edges = {{"scope", 10, 0}};
  auto *fixture =
      new SgInitializedName(nullptr, SgName("rex_json_sym"), integer);
  fixture->set_scope(scope);
  name_record.flags = parseJson(rawNodeFlagsJson(fixture));
  name_record.location = parseJson(rawLocationJson(fixture));
  name_record.properties = parseJson(rawNodeProperties(fixture, {}));
  SageInterface::deleteAST(fixture);
  const auto names = SgInitializedName::numberOfNodes();
  const auto symbols = SgVariableSymbol::numberOfNodes();
  const auto positions = Sg_File_Info::numberOfNodes();
  AstFileRecord ast;
  ast.nodes = {scope_record, name_record};
  ast.index_by_id = {{10, 0}, {2, 1}};
  NodeMap nodes{{10, scope}};
  SerializedSymbolTableConstruction construction;
  restoreSerializedSymbolTables(ast, nodes, {10}, &construction);
  ROSE_ASSERT(construction.pending.size() == 1);
  ROSE_ASSERT(construction.preferences.empty());
  {
    auto pending = collectDelayedDeclarations(ast, nodes);
    drainDelayedDeclarations(ast, pending, nodes, true,
                             [&](const NodeMap &available) {
                               return constructPendingSerializedSymbols(
                                   construction, available, false);
                             });
    ROSE_ASSERT(pending.empty());
  }
  auto *name = isSgInitializedName(nodes.at(2));
  ROSE_ASSERT(name != nullptr && name->get_typeptr() == integer);
  ROSE_ASSERT(name->get_scope() == scope);
  SgVariableSymbol *symbol = scope->lookup_variable_symbol("rex_json_sym");
  ROSE_ASSERT(symbol != nullptr && symbol->get_symbol_basis() == name);
  ROSE_ASSERT(scope->lookup_variable_symbol("rex_json_sym") == symbol);
  ROSE_ASSERT(construction.pending.empty());
  ROSE_ASSERT(construction.preferences_finalized);
  ROSE_ASSERT(construction.preferences.size() == 1);
  ROSE_ASSERT(construction.preferences.front().symbol == symbol);
  const auto constructed_symbols = SgVariableSymbol::numberOfNodes();
  {
    AstFileRecord partial = ast;
    NodeRecord missing = name_record;
    missing.id = 3;
    partial.index_by_id.emplace(missing.id, partial.nodes.size());
    partial.nodes.push_back(std::move(missing));
    auto &entries =
        partial.nodes.front().properties.object.at("symbol_table").array;
    JsonValue deferred = entries.front();
    deferred.object.at("symbol").object.at("symbol_declaration") =
        JsonValue::number("3");
    deferred.object.at("lookup_preferred") = JsonValue::boolean(false);
    entries.insert(entries.begin(), std::move(deferred));
    SerializedSymbolTableConstruction pending;
    restoreSerializedSymbolTables(partial, nodes, {10}, &pending);
    ROSE_ASSERT(pending.pending.size() == 1);
    ROSE_ASSERT(scope->lookup_variable_symbol("rex_json_sym") == symbol);
    ROSE_ASSERT(SgVariableSymbol::numberOfNodes() == constructed_symbols);
    bool rejected = false;
    try {
      constructPendingSerializedSymbols(pending, nodes, true);
    } catch (const std::runtime_error &error) {
      if (std::string(error.what()).find("missing or cyclic") ==
          std::string::npos)
        throw;
      rejected = true;
    }
    ROSE_ASSERT(rejected && pending.pending.size() == 1);
    ROSE_ASSERT(scope->lookup_variable_symbol("rex_json_sym") == symbol);
    ROSE_ASSERT(SgVariableSymbol::numberOfNodes() == constructed_symbols);
  }
  JsonValue invalid_preference =
      ast.nodes.front().properties.at("symbol_table").array.front();
  invalid_preference.object.at("lookup_preferred") = parseJson("false");
  SerializedSymbolTableConstruction invalid;
  invalid.pending.emplace_back(scope->get_symbol_table(), invalid_preference);
  bool preference_rejected = false;
  try {
    constructPendingSerializedSymbols(invalid, nodes, true);
  } catch (const std::runtime_error &error) {
    if (std::string(error.what())
            .find("failed to restore symbol lookup preference") ==
        std::string::npos)
      throw;
    preference_rejected = true;
  }
  ROSE_ASSERT(preference_rejected);
  ROSE_ASSERT(SgVariableSymbol::numberOfNodes() == constructed_symbols);
  ROSE_ASSERT(scope->lookup_variable_symbol("rex_json_sym") == symbol);
  for (bool missing : {false, true}) {
    JsonValue malformed = invalid_preference;
    malformed.object.at("entry_name") =
        JsonValue::string("rex_json_unpublished");
    if (missing)
      malformed.object.erase("lookup_preferred");
    else
      malformed.object.at("lookup_preferred") = JsonValue::number("-1");
    SerializedSymbolTableConstruction pending;
    const auto sequence = SgNode::get_globalAstModificationSequence();
    bool rejected = false;
    try {
      pending.pending.emplace_back(scope->get_symbol_table(), malformed);
      constructPendingSerializedSymbols(pending, nodes, true);
    } catch (const std::runtime_error &error) {
      const std::string diagnostic =
          missing ? "missing key: lookup_preferred" : "not a bool";
      if (std::string(error.what()).find(diagnostic) == std::string::npos)
        throw;
      rejected = true;
    }
    ROSE_ASSERT(rejected && pending.pending.empty() &&
                pending.preferences.empty());
    ROSE_ASSERT(SgVariableSymbol::numberOfNodes() == constructed_symbols);
    ROSE_ASSERT(scope->lookup_variable_symbol("rex_json_unpublished") ==
                nullptr);
    ROSE_ASSERT(scope->lookup_variable_symbol("rex_json_sym") == symbol);
    ROSE_ASSERT(SgNode::get_globalAstModificationSequence() == sequence);
  }
  auto alias = parseJson(R"({
    "symbol_kind":"SgAliasSymbol","entry_name":"rex_json_alias",
    "lookup_preferred":false,"alias_is_renamed":true,
    "alias_new_name":"rex_json_alias","alias_causal_nodes":[0],
    "alias_target":{"symbol_kind":"SgVariableSymbol",
      "symbol_name":"rex_json_sym","symbol_declaration":2}
  })");
  ast.nodes.front().properties.object.at("symbol_table").array.push_back(alias);
  const auto aliases = SgAliasSymbol::numberOfNodes();
  bool rejected = false;
  try {
    restoreSerializedSymbolTables(ast, nodes, {ast.nodes.front().id});
  } catch (const std::runtime_error &error) {
    if (std::string(error.what())
            .find("SgAliasSymbol has an invalid causal node ID") ==
        std::string::npos) {
      throw;
    }
    rejected = true;
  }
  ROSE_ASSERT(rejected);
  ROSE_ASSERT(SgAliasSymbol::numberOfNodes() == aliases);
  ROSE_ASSERT(scope->lookup_variable_symbol("rex_json_sym") == symbol);
  ROSE_ASSERT(scope->lookup_symbol("rex_json_alias") == nullptr);
  const auto renames = SgRenameSymbol::numberOfNodes();
  for (bool missing : {true, false}) {
    auto rename = alias;
    rename.object["symbol_kind"] = parseJson("\"SgRenameSymbol\"");
    if (missing)
      rename.object.erase("alias_causal_nodes");
    else
      rename.object["alias_causal_nodes"] = parseJson("null");
    ast.nodes.front().properties.object.at("symbol_table").array.back() =
        rename;
    bool rename_rejected = false;
    try {
      restoreSerializedSymbolTables(ast, nodes, {ast.nodes.front().id});
    } catch (const std::runtime_error &error) {
      if (std::string(error.what()).find("alias_causal_nodes") ==
          std::string::npos)
        throw;
      rename_rejected = true;
    }
    ROSE_ASSERT(rename_rejected);
    ROSE_ASSERT(SgRenameSymbol::numberOfNodes() == renames);
    ROSE_ASSERT(SgAliasSymbol::numberOfNodes() == aliases);
    ROSE_ASSERT(scope->lookup_variable_symbol("rex_json_sym") == symbol);
    ROSE_ASSERT(scope->lookup_symbol("rex_json_alias") == nullptr);
  }
  // The table owns the symbol and the symbol references the basis while the
  // basis names the scope back: neither conservative deletion can isolate
  // its node while the other lives. Release exactly the inserted symbol
  // first (the fixture owns its insertion), then the basis, then the scope.
  ROSE_ASSERT(SgNode::isLiveNode(symbol));
  scope->remove_symbol(symbol);
  ROSE_ASSERT(scope->lookup_variable_symbol("rex_json_sym") == nullptr);
  delete symbol;
  SageInterface::deleteAST(name);
  SageInterface::deleteAST(scope);
  ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
  ROSE_ASSERT(SgVariableSymbol::numberOfNodes() == symbols);
  ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
}

void requireInitializedNameConstruction() {
  using namespace Rose::AstJson;
  auto *integer = SageBuilder::buildIntType();
  // Plain-new plus explicit source positions yields deterministic file-info
  // records for the partial-location mutations below.
  auto *fixture = new SgInitializedName(nullptr, SgName("rex_json_x"), integer);
  fixture->set_auto_decltype(SageBuilder::buildAutoType());
  fixture->set_cxx_source_type(integer);
  fixture->set_fortran_source_type(integer);
  fixture->set_storage_size_bytes(4);
  fixture->set_cxx_field_index(7);
  fixture->set_enum_constant_source_ownership(
      SgInitializedName::e_enum_constant_source_unclassified);
  fixture->set_preinitialization(
      SgInitializedName::e_unknown_preinitialization);
  fixture->set_is_parameter_pack(false);
  fixture->set_is_pack_element(false);
  SageInterface::setSourcePosition(fixture);
  NodeRecord valid;
  valid.id = 1;
  valid.kind = "SgInitializedName";
  valid.flags = parseJson(rawNodeFlagsJson(fixture));
  valid.location = parseJson(rawLocationJson(fixture));
  valid.properties = parseJson(rawNodeProperties(fixture, {}));
  auto *alignment = new SgAlignmentSpecifier(
      SgAlignmentSpecifier::e_alignas, SageBuilder::buildIntVal(64), false);
  SageInterface::setSourcePosition(alignment);
  alignment->set_parent(fixture);
  fixture->get_alignment_specifiers().push_back(alignment);
  auto *alignment_copy =
      isSgAlignmentSpecifier(SageInterface::deepCopy(alignment));
  ROSE_ASSERT(alignment_copy != nullptr && alignment_copy != alignment);
  ROSE_ASSERT(alignment_copy->get_operand() != alignment->get_operand());
  ROSE_ASSERT(alignment_copy->get_operand()->get_parent() == alignment_copy);
  ROSE_ASSERT(alignment->get_operand()->get_parent() == alignment);
  ROSE_ASSERT(alignment_copy->get_spelling() == alignment->get_spelling());
  ROSE_ASSERT(isSgIntVal(alignment_copy->get_operand())->get_value() == 64);
  SageInterface::deleteAST(alignment_copy);
  NodeRecord alignment_record;
  alignment_record.id = 2;
  alignment_record.kind = "SgAlignmentSpecifier";
  alignment_record.flags = parseJson(rawNodeFlagsJson(alignment));
  alignment_record.location = parseJson(rawLocationJson(alignment));
  alignment_record.properties = parseJson(rawNodeProperties(alignment, {}));
  alignment_record.edges.push_back({"operand", 3, 0});
  auto *type_operand = SageBuilder::buildTypeExpression_nfi(integer);
  auto *type_alignment = alignmentSpecifierFromProperties(
      alignment_record.properties, type_operand);
  ROSE_ASSERT(type_alignment->get_operand() == type_operand);
  ROSE_ASSERT(type_operand->get_parent() == type_alignment);
  ROSE_ASSERT(type_operand->get_represented_type() == integer);
  SageInterface::deleteAST(type_alignment);
  JsonValue external = parseJson(
      rawExternalInitializedNameJson(fixture, {}, "auto source type"));
  SageInterface::deleteAST(fixture);
  const auto names = SgInitializedName::numberOfNodes();
  const auto positions = Sg_File_Info::numberOfNodes();
  const auto alignments = SgAlignmentSpecifier::numberOfNodes();
  const auto integers = SgIntVal::numberOfNodes();
  {
    AstFileRecord ast;
    NodeRecord operand_record;
    operand_record.id = 3;
    operand_record.kind = "SgIntVal";
    operand_record.edges.push_back({"parent", alignment_record.id, 0});
    ast.nodes = {alignment_record, operand_record};
    auto *operand = SageBuilder::buildIntVal(64);
    NodeMap nodes{{operand_record.id, operand}};
    const auto borrowed_positions = Sg_File_Info::numberOfNodes();
    for (bool malformed_location : {true, false}) {
      NodeRecord malformed = alignment_record;
      if (malformed_location)
        malformed.location.object.at("end").object.at("raw_line") =
            parseJson("2147483648");
      else
        malformed.flags.object.erase("contains_transformation");
      AstFileRecord rejected_ast;
      rejected_ast.nodes = {malformed, operand_record};
      bool rejected = false;
      try {
        rebuildConstructorOnlyNodes(recordGraph(rejected_ast.nodes), nodes);
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected && nodes.size() == 1 && nodes.at(3) == operand);
      ROSE_ASSERT(operand->get_parent() == nullptr);
      ROSE_ASSERT(SgAlignmentSpecifier::numberOfNodes() == alignments);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == integers + 1);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == borrowed_positions);
    }
    rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    auto *restored = isSgAlignmentSpecifier(nodes.at(alignment_record.id));
    ROSE_ASSERT(restored != nullptr && restored->get_operand() == operand);
    ROSE_ASSERT(operand->get_parent() == restored);
    linkNodeEdges(alignment_record, nodes);
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgAlignmentSpecifier::numberOfNodes() == alignments);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == integers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  {
    AstFileRecord ast;
    ast.nodes = {valid};
    NodeMap nodes;
    auto pending = collectDelayedDeclarations(ast, nodes);
    drainDelayedDeclarations(ast, pending, nodes, true);
    auto *restored = isSgInitializedName(nodes.at(valid.id));
    ROSE_ASSERT(restored != nullptr && restored->get_type() == integer);
    ROSE_ASSERT(isSgAutoType(restored->get_auto_decltype()) != nullptr);
    ROSE_ASSERT(restored->get_cxx_source_type() == integer);
    ROSE_ASSERT(restored->get_fortran_source_type() == integer);
    ROSE_ASSERT(restored->get_storage_size_bytes() == 4);
    ROSE_ASSERT(restored->get_cxx_field_index() == 7);
    SageInterface::deleteAST(restored);
  }
  auto reject_alignment = [&](const JsonValue &bad,
                              const std::string &diagnostic) {
    bool rejected = false;
    try {
      (void)externalInitializedNameFromJson(bad, {}, nullptr, nullptr, nullptr,
                                            "alignment ownership");
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what()).find(diagnostic) != std::string::npos;
    }
    ROSE_ASSERT(rejected);
    ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
    ROSE_ASSERT(SgAlignmentSpecifier::numberOfNodes() == alignments);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == integers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  };
  for (const char *field :
       {"alignment_specifiers", "source_name_qualification_present",
        "alignment_spelling", "alignment_pack_expansion"}) {
    JsonValue bad = external;
    if (std::string(field) == "alignment_spelling" ||
        std::string(field) == "alignment_pack_expansion") {
      auto &specifier = bad.object.at("alignment_specifiers").array.front();
      specifier.object.at("properties").object.erase(field);
      specifier.object.at("operand") = parseJson(R"({"node":999})");
    } else {
      bad.object.erase(field);
    }
    reject_alignment(bad, std::string("missing key: ") + field);
  }
  for (const char *field : {"start", "end"}) {
    JsonValue bad = external;
    auto &specifier = bad.object.at("alignment_specifiers").array.front();
    specifier.object.at("location").object.at(field).object.at("raw_line") =
        parseJson("2147483648");
    specifier.object.at("operand") = parseJson(R"({"node":999})");
    reject_alignment(bad, "raw_line");
    bad = external;
    bad.object.at("location").object.at(field).object.at("raw_line") =
        parseJson("2147483648");
    bad.object.at("type") =
        parseJson(R"({"present":true,"kind":"SgTypedefType",)"
                  R"("fortran_source_syntax":false,"declaration":999})");
    reject_alignment(bad, "raw_line");
  }
  {
    auto *restored = externalInitializedNameFromJson(
        external, {}, nullptr, nullptr, nullptr, "auto source type");
    ROSE_ASSERT(restored->get_alignment_specifiers().size() == 1);
    auto *specifier = restored->get_alignment_specifiers().front();
    ROSE_ASSERT(specifier->get_parent() == restored);
    ROSE_ASSERT(specifier->get_spelling() == SgAlignmentSpecifier::e_alignas);
    ROSE_ASSERT(specifier->get_operand()->get_parent() == specifier);
    ROSE_ASSERT(isSgIntVal(specifier->get_operand())->get_value() == 64);
    ROSE_ASSERT(restored->get_type() == integer);
    ROSE_ASSERT(isSgAutoType(restored->get_auto_decltype()) != nullptr);
    ROSE_ASSERT(restored->get_cxx_source_type() == integer);
    ROSE_ASSERT(restored->get_fortran_source_type() == integer);
    ROSE_ASSERT(restored->get_storage_size_bytes() == 4);
    ROSE_ASSERT(restored->get_cxx_field_index() == 7);
    SageInterface::deleteAST(restored);
  }
  for (const char *field :
       {"auto_decltype", "cxx_source_type", "fortran_source_type",
        "fortran_procedure_interface", "storage_size_bytes",
        "cxx_field_index"}) {
    JsonValue bad = external;
    bad.object.erase(field);
    bool rejected = false;
    try {
      (void)externalInitializedNameFromJson(bad, {}, nullptr, nullptr, nullptr,
                                            "auto source type");
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what())
              .find(std::string("missing key: ") + field) != std::string::npos;
    }
    ROSE_ASSERT(rejected);
    ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  for (const char *field :
       {"auto_decltype", "cxx_source_type", "fortran_source_type",
        "fortran_procedure_interface"}) {
    NodeRecord deferred = valid;
    deferred.properties.object.at(field) =
        parseJson(R"({"present":true,"kind":"SgTypedefType",)"
                  R"("fortran_source_syntax":false,)"
                  R"("declaration":999})");
    AstFileRecord ast;
    ast.nodes = {deferred};
    NodeMap nodes;
    auto pending = collectDelayedDeclarations(ast, nodes);
    drainDelayedDeclarations(ast, pending, nodes, false);
    ROSE_ASSERT(nodes.empty() && pending.size() == 1);
    bool reported = false;
    try {
      drainDelayedDeclarations(ast, pending, nodes, true);
    } catch (const std::runtime_error &error) {
      const std::string message = error.what();
      reported = message.find("missing or cyclic") != std::string::npos &&
                 message.find("999") != std::string::npos;
    }
    ROSE_ASSERT(reported && nodes.empty());
    ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  for (bool external_record : {false, true}) {
    for (const char *value :
         {"-1", "4.5", "\"4\"", "{}", "9223372036854775808"}) {
      JsonValue bad = external_record ? external : valid.properties;
      bad.object.at("storage_size_bytes") = parseJson(value);
      NodeMap nodes;
      bool rejected = false;
      try {
        if (external_record) {
          auto *restored = externalInitializedNameFromJson(
              bad, {}, nullptr, nullptr, nullptr, "object storage size");
          SageInterface::deleteAST(restored);
        } else {
          NodeRecord record = valid;
          record.properties = bad;
          auto graph = recordGraph({record});
          auto pending = collectDelayedDeclarations(graph, nodes);
          drainDelayedDeclarations(graph, pending, nodes, true);
        }
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected && nodes.empty());
      ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
  }
  const char *placeholder_types[] = {
      R"({"present":true,"kind":"SgTypeUnknown",)"
      R"("fortran_source_syntax":false})",
      R"({"present":true,"kind":"SgTypeDefault",)"
      R"("fortran_source_syntax":false})"};
  for (bool external_record : {false, true}) {
    JsonValue bad = external_record ? external : valid.properties;
    bad.object.at("cxx_source_type") =
        parseJson(rawTypeJson(SageBuilder::buildFloatType(), {}));
    bool rejected = false;
    NodeMap nodes;
    try {
      if (external_record) {
        auto *restored = externalInitializedNameFromJson(
            bad, {}, nullptr, nullptr, nullptr, "source type agreement");
        SageInterface::deleteAST(restored);
      } else {
        NodeRecord record = valid;
        record.properties = bad;
        auto graph = recordGraph({record});
        auto pending = collectDelayedDeclarations(graph, nodes);
        drainDelayedDeclarations(graph, pending, nodes, true);
      }
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what()) ==
                 "AST JSON initializedName has contradictory C++ source and "
                 "semantic types";
    }
    ROSE_ASSERT(rejected && nodes.empty());
    ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
    ROSE_ASSERT(SgAlignmentSpecifier::numberOfNodes() == alignments);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == integers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  for (const char *field :
       {"auto_decltype", "cxx_source_type", "fortran_source_type"}) {
    for (const char *placeholder : placeholder_types) {
      JsonValue bad = external;
      bad.object.at(field) = parseJson(placeholder);
      bool rejected = false;
      try {
        auto *restored = externalInitializedNameFromJson(
            bad, {}, nullptr, nullptr, nullptr, "auto source type");
        SageInterface::deleteAST(restored);
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what())
                       .find("optional type requires an exact type") !=
                   std::string::npos;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
  }
  for (int mutation = 0; mutation != 18; ++mutation) {
    NodeRecord bad = valid;
    auto &properties = bad.properties.object;
    if (mutation == 0)
      properties.at("type") =
          parseJson(R"({"present":true,"kind":"SgTypeUnknown",)"
                    R"("fortran_source_syntax":false})");
    else if (mutation == 1)
      properties.erase("type");
    else if (mutation == 2)
      properties.at("type") = parseJson(R"({"present":false})");
    else if (mutation == 3)
      properties.erase("name");
    else if (mutation == 4)
      properties.at("type") =
          parseJson(R"({"present":true,"kind":"SgTypedefType",)"
                    R"("fortran_source_syntax":false,)"
                    R"("declaration":999})");
    else if (mutation == 5)
      bad.flags.object.erase("is_modified");
    else if (mutation == 6)
      bad.location = parseJson("null");
    else if (mutation == 8) {
      // A location object with valid start fields but an out-of-range end
      // must fail during restoration without leaking the start position.
      JsonValue partial = valid.location;
      partial.object.at("end") = parseJson(
          R"({"present":true,"raw_filename":"NULL_FILE","raw_line":2147483648,)"
          R"("raw_column":0,"physical_line":0,"physical_file_id":-1,)"
          R"("physical_internal_file_id":-1,"source_sequence":0,)"
          R"("physical_raw_filename":"","physical_filename":"",)"
          R"("compiler_generated":false,"transformation":false,)"
          R"("frontend_specific":false,"shared":false,)"
          R"("source_position_unavailable_in_frontend":false,)"
          R"("comment_or_directive":false,"token":false,)"
          R"("default_argument":false,"implicit_cast":false,)"
          R"("output_in_code_generation":false})");
      bad.location = partial;
    } else if (mutation == 9)
      properties.erase("enum_constant_value");
    else if (mutation == 10)
      properties.at("enum_constant_value") = parseJson("\"0\"");
    else if (mutation == 11)
      properties.at("enum_constant_value") = parseJson("0");
    else if (mutation == 12)
      properties.at("enum_constant_source_ownership") = parseJson(
          std::to_string(SgInitializedName::e_enum_constant_source_body));
    else if (mutation == 13)
      properties.erase("auto_decltype");
    else if (mutation == 14)
      properties.erase("cxx_source_type");
    else if (mutation == 15)
      properties.erase("fortran_source_type");
    else if (mutation == 16)
      properties.erase("shape_deferred");
    else if (mutation == 17)
      properties.at("shape_deferred") = JsonValue::number("1");
    AstFileRecord ast;
    if (mutation == 5 || mutation == 6 || mutation == 8 || mutation >= 16) {
      // Malformed input alongside a resolvable valid declaration must fail
      // immediately, before anything is published.
      bad.id = 2;
      ast.nodes = {bad, valid};
    } else if (mutation == 7) {
      // Duplicate identifiers are rejected at collection, before scheduling.
      ast.nodes = {valid, bad};
    } else {
      ast.nodes = {bad};
    }
    NodeMap nodes;
    if (mutation == 4) {
      // An unresolvable cross-kind dependency waits silently in a non-final
      // drain and is reported with its missing identifiers in a final drain.
      auto pending = collectDelayedDeclarations(ast, nodes);
      drainDelayedDeclarations(ast, pending, nodes, false);
      ROSE_ASSERT(nodes.empty() && !pending.empty());
      bool reported = false;
      try {
        drainDelayedDeclarations(ast, pending, nodes, true);
      } catch (const std::runtime_error &error) {
        const std::string message = error.what();
        reported = message.find("missing or cyclic") != std::string::npos &&
                   message.find("999") != std::string::npos;
      }
      ROSE_ASSERT(reported && nodes.empty());
    } else {
      bool rejected = false;
      try {
        auto pending = collectDelayedDeclarations(ast, nodes);
        drainDelayedDeclarations(ast, pending, nodes, true);
      } catch (const std::runtime_error &error) {
        rejected =
            std::string(error.what())
                .find(mutation == 0    ? "requires an exact type"
                      : mutation == 1  ? "missing key: type"
                      : mutation == 2  ? "absent"
                      : mutation == 3  ? "missing key: name"
                      : mutation == 5  ? "missing key: is_modified"
                      : mutation == 6  ? "location must be an object"
                      : mutation == 8  ? "out of range"
                      : mutation == 9  ? "missing key: enum_constant_value"
                      : mutation == 10 ? "not a number"
                      : mutation == 13 ? "missing key: auto_decltype"
                      : mutation == 14 ? "missing key: cxx_source_type"
                      : mutation == 15 ? "missing key: fortran_source_type"
                      : mutation == 16 ? "missing key: shape_deferred"
                      : mutation == 17 ? "not a bool"
                      : mutation >= 11 ? "value and source role disagree"
                                       : "duplicate delayed declaration") !=
            std::string::npos;
      }
      ROSE_ASSERT(rejected && nodes.empty());
    }
    ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  {
    // A record that is both malformed and unresolvable reports its malformed
    // flags in either drain path: validation precedes scheduling, so the
    // missing dependency never masks the schema failure.
    NodeRecord bad = valid;
    bad.flags.object.erase("is_modified");
    bad.properties.object.at("type") =
        parseJson(R"({"present":true,"kind":"SgTypedefType",)"
                  R"("fortran_source_syntax":false,)"
                  R"("declaration":999})");
    for (bool final : {false, true}) {
      AstFileRecord ast;
      ast.nodes = {bad};
      NodeMap nodes;
      bool flagged = false;
      try {
        auto pending = collectDelayedDeclarations(ast, nodes);
        drainDelayedDeclarations(ast, pending, nodes, final);
      } catch (const std::runtime_error &error) {
        flagged = std::string(error.what()).find("missing key: is_modified") !=
                      std::string::npos &&
                  nodes.empty();
      }
      ROSE_ASSERT(flagged);
      ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
  }
}

void requireNewExpressionPointerIdentity() {
  using namespace Rose::AstJson;
  auto *base = SageBuilder::buildIntType();
  auto *canonical = buildCachedJsonPointerType(base);
  {
    std::unique_ptr<SgProject, DeleteFixtureAst> project(new SgProject());
    std::vector<std::string> arguments{"rex-json", "-c",
                                       "rex_ast_json_required_fields.cpp"};
    auto *file =
        new SgSourceFile(arguments, project.get(), project->get_fileList_ptr(),
                         std::filesystem::absolute(arguments.back()).string(),
                         SgSourceFile::e_parsed_source);
    project->get_fileList_ptr()->get_listOfFiles().push_back(file);
    file->initializeGlobalScope();
    auto *alias = SageBuilder::buildTypedefDeclaration_nfi(
        SageBuilder::typedef_declaration_ownership::semanticAuxiliary(),
        SgTypedefDeclaration::e_typedef, "rex_qualified_allocation_alias",
        SageBuilder::buildConstType(base), file->get_globalScope());
    auto *pointer = buildCachedJsonPointerType(alias->get_type());
    ROSE_ASSERT(SgNewExp::specifiedTypeMatchesResult(
        alias->get_type(), pointer, SgNewExp::e_no_array_bound));
    ROSE_ASSERT(!SgNewExp::specifiedTypeMatchesResult(
        alias->get_type(), canonical, SgNewExp::e_no_array_bound));
    auto *projection = SageBuilder::buildSemanticNonrealType(
        alias->get_name(), file->get_globalScope(), nullptr, alias);
    auto *nested = SageBuilder::buildTypedefDeclaration_nfi(
        SageBuilder::typedef_declaration_ownership::semanticAuxiliary(),
        SgTypedefDeclaration::e_typedef, "rex_nested_allocation_alias",
        projection, file->get_globalScope());
    auto *nested_pointer = buildCachedJsonPointerType(nested->get_type());
    ROSE_ASSERT(SgNewExp::specifiedTypeMatchesResult(
        nested->get_type(), nested_pointer, SgNewExp::e_no_array_bound));
    ROSE_ASSERT(!SgNewExp::specifiedTypeMatchesResult(
        nested->get_type(), canonical, SgNewExp::e_no_array_bound));
    auto *array = SageBuilder::buildConstType(
        SageBuilder::buildArrayType(base, SageBuilder::buildIntVal(3)));
    ROSE_ASSERT(SgNewExp::specifiedTypeMatchesResult(
        array, pointer, SgNewExp::e_type_array_bound));
    ROSE_ASSERT(!SgNewExp::specifiedTypeMatchesResult(
        array, canonical, SgNewExp::e_type_array_bound));
    ROSE_ASSERT(!SgNewExp::specifiedTypeMatchesResult(
        array, pointer, SgNewExp::e_no_array_bound));
  }
  for (unsigned int implicit_count : {1u, 2u, 3u}) {
    const bool initialized = implicit_count != 1;
    auto *builtin =
        initialized ? SageBuilder::buildIntVal_nfi(7, "7") : nullptr;
    if (builtin != nullptr)
      SageBuilder::initializeSemanticExpressionSourceProvenance(builtin);
    auto *original = constructNewExpression(
        {base, canonical, 0, false, implicit_count, SgNewExp::e_no_array_bound},
        nullptr, nullptr, nullptr, builtin, nullptr, {});
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    ROSE_ASSERT(original->get_type() == canonical);
    SgTreeCopy copy;
    auto *copied = isSgNewExp(original->copy(copy));
    ROSE_ASSERT(copied != nullptr && copied != original);
    ROSE_ASSERT(copied->get_allocation_implicit_argument_count() ==
                implicit_count);
    SageInterface::deleteAST(copied);
    {
      auto noncanonical = std::make_unique<SgPointerType>(base);
      ROSE_ASSERT(base->get_ptr_to() == canonical);
      const auto expressions = SgNewExp::numberOfNodes();
      bool rejected = false;
      try {
        SageInterface::deleteAST(constructNewExpression(
            {base, noncanonical.get(), 0, false, 1, SgNewExp::e_no_array_bound},
            nullptr, nullptr, nullptr, nullptr, nullptr, {}));
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what())
                       .find("requires its exact canonical result pointer") !=
                   std::string::npos;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgNewExp::numberOfNodes() == expressions);
      ROSE_ASSERT(base->get_ptr_to() == canonical);
      ROSE_ASSERT(original->get_type() == canonical);
    }
    const auto serialized = parseJson(rawTypeOwnedExpressionRef(original, {}));
    SageInterface::deleteAST(original);
    const auto expressions = SgNewExp::numberOfNodes();
    const auto values = SgIntVal::numberOfNodes();
    const auto lists = SgExprListExp::numberOfNodes();
    const auto positions = Sg_File_Info::numberOfNodes();
    auto require_rejection = [&](const JsonValue &malformed,
                                 const std::string &diagnostic) {
      bool rejected = false;
      try {
        SageInterface::deleteAST(expressionFromRef(malformed, {}));
      } catch (const std::runtime_error &error) {
        if (std::string(error.what()).find(diagnostic) == std::string::npos)
          throw;
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgNewExp::numberOfNodes() == expressions);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
      ROSE_ASSERT(SgExprListExp::numberOfNodes() == lists);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
      ROSE_ASSERT(base->get_ptr_to() == canonical);
    };
    for (const char *field :
         {"specified_type", "type", "placement_args", "constructor_args",
          "builtin_args", "new_operator_declaration", "need_global_specifier",
          "type_id_is_parenthesized", "allocation_implicit_argument_count",
          "array_bound_source_form", "array_bound"}) {
      auto malformed = serialized;
      malformed.object.at("properties").object.erase(field);
      require_rejection(malformed, std::string("missing key: ") + field);
    }
    for (const char *value : {"true", "0", "4", "-1", "4294967296"}) {
      auto malformed = serialized;
      malformed.object.at("properties")
          .object.at("allocation_implicit_argument_count") = parseJson(value);
      require_rejection(malformed,
                        std::string(value) == "true"
                            ? "value is not a number"
                            : "implicit argument count is out of range");
    }
    {
      auto malformed = serialized;
      malformed.object.at("properties").object.at("array_bound_source_form") =
          parseJson("true");
      require_rejection(malformed, "value is not a number");
    }
    for (const char *value : {"-1", "4", "4294967296"}) {
      auto malformed = serialized;
      malformed.object.at("properties").object.at("array_bound_source_form") =
          parseJson(value);
      require_rejection(malformed,
                        "invalid array_bound_source_form enum value");
    }
    for (const char *value : {"1", "2", "3"}) {
      auto malformed = serialized;
      malformed.object.at("properties").object.at("array_bound_source_form") =
          parseJson(value);
      require_rejection(malformed, "array bound and source form disagree");
    }
    for (const char *value : {"-1", "2", "65536"}) {
      auto malformed = serialized;
      malformed.object.at("properties").object.at("need_global_specifier") =
          parseJson(value);
      require_rejection(malformed, "global specifier must be zero or one");
    }
    auto negative_declaration = serialized;
    negative_declaration.object.at("properties")
        .object.at("new_operator_declaration") = parseJson("-1");
    require_rejection(negative_declaration, "negative operator declaration");
    auto *restored = isSgNewExp(expressionFromRef(serialized, {}));
    ROSE_ASSERT(restored != nullptr);
    ROSE_ASSERT(restored->get_specified_type() == base);
    ROSE_ASSERT(restored->get_type() == canonical);
    ROSE_ASSERT(restored->get_allocation_implicit_argument_count() ==
                implicit_count);
    ROSE_ASSERT(restored->get_array_bound_source_form() ==
                SgNewExp::e_no_array_bound);
    ROSE_ASSERT(base->get_ptr_to() == canonical);
    if (initialized) {
      auto *value = isSgIntVal(restored->get_builtin_args());
      ROSE_ASSERT(value != nullptr && value->get_value() == 7);
      ROSE_ASSERT(value->get_parent() == restored);
    } else {
      ROSE_ASSERT(restored->get_builtin_args() == nullptr);
    }
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(base->get_ptr_to() == canonical);
  }
  auto *array = SageBuilder::buildArrayType(base, SageBuilder::buildIntVal(3));
  auto *array_pointer = buildCachedJsonPointerType(array);
  auto make_bound = [](int count) {
    auto *bound = SageBuilder::buildIntVal_nfi(count);
    SageBuilder::initializeSemanticExpressionSourceProvenance(bound);
    return bound;
  };
  for (auto source_form :
       {SgNewExp::e_written_array_bound, SgNewExp::e_inferred_array_bound}) {
    auto *nested = constructNewExpression(
        {base, canonical, 0, false, 1, SgNewExp::e_written_array_bound},
        make_bound(3), nullptr, nullptr, nullptr, nullptr, {});
    SageBuilder::initializeSemanticExpressionSourceProvenance(nested);
    auto *placement = SageBuilder::buildExprListExp_nfi({nested});
    SageBuilder::initializeSemanticExpressionSourceProvenance(placement);
    auto *original = constructNewExpression(
        {array, array_pointer, 0, false, 1, source_form}, make_bound(5),
        placement, nullptr, nullptr, nullptr, {nested});
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    SgTreeCopy copy;
    auto *copied = isSgNewExp(original->copy(copy));
    ROSE_ASSERT(copied != nullptr && copied != original);
    ROSE_ASSERT(copied->get_array_bound_source_form() == source_form);
    ROSE_ASSERT(copied->get_array_bound() != original->get_array_bound());
    ROSE_ASSERT(copied->get_array_bound()->get_parent() == copied);
    SageInterface::deleteAST(copied);
    const auto serialized = parseJson(rawTypeOwnedExpressionRef(original, {}));
    auto *restored = isSgNewExp(expressionFromRef(serialized, {}));
    ROSE_ASSERT(restored != nullptr &&
                restored->get_array_bound_source_form() == source_form);
    ROSE_ASSERT(restored->get_array_bound()->get_parent() == restored);
    ROSE_ASSERT(restored->get_allocation_implicit_argument_count() == 1);
    auto *restored_nested =
        isSgNewExp(restored->get_placement_args()->get_expressions().front());
    ROSE_ASSERT(restored_nested != nullptr);
    ROSE_ASSERT(restored_nested->get_specified_type() == base);
    ROSE_ASSERT(restored_nested->get_type() == canonical);
    ROSE_ASSERT(restored_nested->get_array_bound()->get_parent() ==
                restored_nested);
    ROSE_ASSERT(isSgPointerType(restored->get_type())->get_base_type() ==
                restored->get_specified_type());
    ROSE_ASSERT(restored->get_specified_type()->get_ptr_to() ==
                restored->get_type());
    SageInterface::deleteAST(restored);
    SageInterface::deleteAST(original);
  }
}

void requireAggregateConstruction() {
  using namespace Rose::AstJson;
  SgType *type = SageBuilder::buildIntType();
  auto make_aggregate = [&](SgExpression *element) {
    auto *list = SageBuilder::buildExprListExp();
    if (element != nullptr)
      list->append_expression(element);
    auto *aggregate = SageBuilder::buildAggregateInitializer_nfi(
        list, type,
        SgAggregateInitializer::e_aggregate_initializer_source_braced);
    aggregate->set_is_braced_initialized(true);
    SageBuilder::initializeSemanticExpressionSourceProvenance(aggregate);
    return aggregate;
  };
  for (bool empty : {false, true}) {
    auto *original =
        make_aggregate(empty ? nullptr : SageBuilder::buildIntVal_nfi(7, "7"));
    const auto serialized = parseJson(rawTypeOwnedExpressionRef(original, {}));
    SageInterface::deleteAST(original);
    const size_t aggregates = SgAggregateInitializer::numberOfNodes();
    const size_t lists = SgExprListExp::numberOfNodes();
    const size_t positions = Sg_File_Info::numberOfNodes();
    for (const char *field :
         {"initializers", "type", "aggregate_source_form",
          "source_element_roles", "fortran_source_explicit_type",
          "fortran_source_derived_type_symbol", "is_braced_initialized"}) {
      auto malformed = serialized;
      malformed.object.at("properties").object.erase(field);
      if (std::string(field) == "is_braced_initialized")
        malformed.object.at("properties").object.at("type") =
            JsonValue::objectValue({});
      bool rejected = false;
      try {
        SageInterface::deleteAST(expressionFromRef(malformed, {}));
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what())
                       .find(std::string("missing key: ") + field) !=
                   std::string::npos;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgAggregateInitializer::numberOfNodes() == aggregates);
      ROSE_ASSERT(SgExprListExp::numberOfNodes() == lists);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
    for (const auto &[roles, diagnostic] :
         std::vector<std::pair<const char *, const char *>>{
             {"true", "source roles are not an array"},
             {"[true]", "value is not a number"},
             {"[1.5]", "number is not an integer"},
             {"[4]", "invalid source role"},
             {"[256]", "invalid source role"},
             {"[-1]", "invalid source role"},
             {"[2]", "invalid source role"},
             {"[1,0]", "source role count differs from elements"}}) {
      auto malformed = serialized;
      malformed.object.at("properties").object.at("source_element_roles") =
          parseJson(roles);
      for (bool graph : {false, true}) {
        bool rejected = false;
        try {
          if (graph) {
            NodeRecord aggregate_record;
            aggregate_record.id = 1;
            aggregate_record.kind = "SgAggregateInitializer";
            aggregate_record.properties = malformed.at("properties");
            aggregate_record.edges = {{"initializers", 2, 0}};
            NodeRecord list_record;
            list_record.id = 2;
            list_record.kind = "SgExprListExp";
            if (!empty)
              list_record.edges = {{"expressions", 3, 0}};
            SageInterface::deleteAST(reconstructSourceFile(
                recordGraph({aggregate_record, list_record}), nullptr));
          } else {
            SageInterface::deleteAST(expressionFromRef(malformed, {}));
          }
        } catch (const std::runtime_error &error) {
          rejected =
              std::string(error.what()).find(diagnostic) != std::string::npos;
        }
        ROSE_ASSERT(rejected);
        ROSE_ASSERT(SgAggregateInitializer::numberOfNodes() == aggregates);
        ROSE_ASSERT(SgExprListExp::numberOfNodes() == lists);
        ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
      }
    }
    auto mismatched_fortran = serialized;
    auto &fields = mismatched_fortran.object.at("properties").object;
    fields.at("aggregate_source_form") = parseJson(std::to_string(
        SgAggregateInitializer::e_aggregate_initializer_source_fortran));
    fields.at("fortran_has_source_explicit_type") = parseJson("true");
    fields.at("fortran_source_explicit_type") = fields.at("type");
    bool rejected = false;
    try {
      SageInterface::deleteAST(expressionFromRef(mismatched_fortran, {}));
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what())
              .find("contradictory explicit source/semantic type contract") !=
          std::string::npos;
    }
    ROSE_ASSERT(rejected);
    ROSE_ASSERT(SgAggregateInitializer::numberOfNodes() == aggregates);
    ROSE_ASSERT(SgExprListExp::numberOfNodes() == lists);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    auto *restored =
        isSgAggregateInitializer(expressionFromRef(serialized, {}));
    ROSE_ASSERT(restored != nullptr && restored->get_type() == type &&
                restored->get_is_braced_initialized());
    auto *list = restored->get_initializers();
    ROSE_ASSERT(list != nullptr && list->get_parent() == restored);
    ROSE_ASSERT(list->get_expressions().size() == (empty ? 0 : 1));
    if (!empty) {
      auto *value = isSgIntVal(list->get_expressions().front());
      ROSE_ASSERT(value != nullptr && value->get_value() == 7 &&
                  value->get_parent() == list);
    }
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgAggregateInitializer::numberOfNodes() == aggregates);
  }
  auto *inner = make_aggregate(SageBuilder::buildIntVal_nfi(7, "7"));
  auto *outer = make_aggregate(inner);
  auto record_for = [](uint64_t id, SgAggregateInitializer *aggregate) {
    NodeRecord record;
    record.id = id;
    record.kind = "SgAggregateInitializer";
    record.flags = parseJson(rawNodeFlagsJson(aggregate));
    record.location = parseJson(rawLocationJson(aggregate));
    record.properties = parseJson(rawNodeProperties(aggregate, {}));
    return record;
  };
  auto outer_record = record_for(1, outer);
  outer_record.edges = {{"initializers", 2, 0}};
  auto inner_record = record_for(3, inner);
  inner_record.edges = {{"parent", 2, 0}, {"initializers", 4, 0}};
  SageInterface::deleteAST(outer);
  for (bool duplicate : {false, true}) {
    AstFileRecord ast;
    ast.nodes = {outer_record, inner_record};
    NodeMap nodes{{2, new SgExprListExp()},
                  {4, new SgExprListExp()},
                  {5, SageBuilder::buildIntVal_nfi(7, "7")}};
    for (const auto &[id, parent] :
         std::vector<std::pair<uint64_t, uint64_t>>{{2, 1}, {4, 3}, {5, 4}}) {
      NodeRecord record;
      record.id = id;
      record.kind = nodes.at(id)->class_name();
      record.edges.push_back({"parent", parent, 0});
      if (id == 2)
        record.edges.push_back({"expressions", 3, 0});
      if (id == 4) {
        record.edges.push_back({"expressions", 5, 0});
        if (duplicate)
          record.edges.push_back({"expressions", 5, 1});
      }
      ast.nodes.push_back(record);
    }
    nodes.at(5)->set_parent(nodes.at(4));
    const size_t aggregates = SgAggregateInitializer::numberOfNodes();
    if (duplicate) {
      bool rejected = false;
      try {
        rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what()).find("conflicting ownership") !=
                   std::string::npos;
      }
      ROSE_ASSERT(rejected &&
                  SgAggregateInitializer::numberOfNodes() == aggregates);
      ROSE_ASSERT(nodes.count(1) == 0 && nodes.count(3) == 0);
      ROSE_ASSERT(isSgExprListExp(nodes.at(2))->get_expressions().empty());
      ROSE_ASSERT(isSgExprListExp(nodes.at(4))->get_expressions().empty());
      ROSE_ASSERT(nodes.at(5)->get_parent() == nodes.at(4));
      nodes.at(5)->set_parent(nullptr);
      for (uint64_t id : {5, 4, 2})
        SageInterface::deleteAST(nodes.at(id));
    } else {
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      auto *root = isSgAggregateInitializer(nodes.at(1));
      auto *nested = isSgAggregateInitializer(nodes.at(3));
      ROSE_ASSERT(root->get_type() == type && nested->get_type() == type);
      ROSE_ASSERT(root->get_is_braced_initialized() &&
                  nested->get_is_braced_initialized());
      ROSE_ASSERT(root->get_initializers()->get_expressions().front() ==
                  nested);
      ROSE_ASSERT(nested->get_parent() == root->get_initializers());
      ROSE_ASSERT(nested->get_initializers()->get_expressions().front() ==
                  nodes.at(5));
      SageInterface::deleteAST(root);
      ROSE_ASSERT(SgAggregateInitializer::numberOfNodes() == aggregates);
    }
  }
}

void requireGraphCallConstruction() {
  using namespace Rose::AstJson;
  auto *type = SageBuilder::buildIntType();
  auto *function_type = SageBuilder::buildFunctionType(
      type, SageBuilder::buildFunctionParameterTypeList(type));
  std::unique_ptr<SgFunctionDeclaration, DeleteFixtureAst> declaration(
      new SgFunctionDeclaration(SgName("rex_json_nested_call"), function_type,
                                nullptr, nullptr));
  auto symbol = std::make_unique<SgFunctionSymbol>(declaration.get());
  auto make_ref = [&] {
    auto *reference = new SgFunctionRefExp(symbol.get(), symbol->get_type());
    SageBuilder::initializeSemanticExpressionSourceProvenance(reference);
    return reference;
  };
  auto *inner = SageBuilder::buildFunctionCallExp_nfi(
      make_ref(), type,
      SageBuilder::buildExprListExp(SageBuilder::buildIntVal_nfi(7, "7")));
  auto *outer = SageBuilder::buildFunctionCallExp_nfi(
      make_ref(), type, SageBuilder::buildExprListExp(inner));
  SageBuilder::initializeSemanticExpressionSourceProvenance(inner);
  SageBuilder::initializeSemanticExpressionSourceProvenance(outer);
  auto record_for = [](uint64_t id, SgFunctionCallExp *call) {
    NodeRecord record;
    record.id = id;
    record.kind = "SgFunctionCallExp";
    record.flags = parseJson(rawNodeFlagsJson(call));
    record.location = parseJson(rawLocationJson(call));
    record.properties = parseJson(rawNodeProperties(call, {}));
    return record;
  };
  NodeRecord outer_record = record_for(1, outer);
  outer_record.edges = {{"function", 2, 0}, {"args", 3, 0}};
  NodeRecord inner_record = record_for(4, inner);
  inner_record.edges = {{"parent", 3, 0}, {"function", 5, 0}, {"args", 6, 0}};
  SageInterface::deleteAST(outer);
  for (bool duplicate : {false, true}) {
    AstFileRecord ast;
    ast.nodes = {outer_record, inner_record};
    NodeMap nodes{{2, make_ref()},
                  {3, new SgExprListExp()},
                  {5, make_ref()},
                  {6, new SgExprListExp()},
                  {7, SageBuilder::buildIntVal_nfi(7, "7")}};
    for (const auto &[id, parent] : std::vector<std::pair<uint64_t, uint64_t>>{
             {2, 1}, {3, 1}, {5, 4}, {6, 4}, {7, 6}}) {
      NodeRecord record;
      record.id = id;
      record.kind = nodes.at(id)->class_name();
      record.flags = parseJson(rawNodeFlagsJson(nodes.at(id)));
      record.location = parseJson(rawLocationJson(nodes.at(id)));
      std::vector<std::string> fields{rawIntegerField(
          "semantic_wrapper_mask",
          static_cast<int>(
              isSgExpression(nodes.at(id))->get_semantic_wrapper_mask()))};
      if (auto *reference = isSgFunctionRefExp(nodes.at(id))) {
        addExpressionQualificationFields(fields, reference);
      }
      std::ostringstream output;
      writeRawObject(output, 0, fields, false);
      record.properties = parseJson(output.str());
      record.edges.push_back({"parent", parent, 0});
      if (id == 3)
        record.edges.push_back({"expressions", 4, 0});
      if (id == 6) {
        record.edges.push_back({"expressions", 7, 0});
        if (duplicate)
          record.edges.push_back({"expressions", 7, 1});
      }
      ast.nodes.push_back(record);
    }
    // Existing leaves already have their recorded parent; delayed calls do not.
    nodes.at(7)->set_parent(nodes.at(6));
    const size_t count = SgFunctionCallExp::numberOfNodes();
    if (duplicate) {
      bool rejected = false;
      try {
        rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what()).find("conflicting ownership") !=
                   std::string::npos;
      }
      ROSE_ASSERT(rejected && SgFunctionCallExp::numberOfNodes() == count);
      ROSE_ASSERT(nodes.count(1) == 0 && nodes.count(4) == 0);
      ROSE_ASSERT(isSgExprListExp(nodes.at(3))->get_expressions().empty());
      ROSE_ASSERT(isSgExprListExp(nodes.at(6))->get_expressions().empty());
      ROSE_ASSERT(nodes.at(7)->get_parent() == nodes.at(6));
      nodes.at(7)->set_parent(nullptr);
      for (uint64_t id : {7, 2, 5, 3, 6})
        SageInterface::deleteAST(nodes.at(id));
    } else {
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      auto *root = isSgFunctionCallExp(nodes.at(1));
      auto *nested = isSgFunctionCallExp(nodes.at(4));
      ROSE_ASSERT(root->get_type() == type && nested->get_type() == type);
      ROSE_ASSERT(root->get_args()->get_expressions().size() == 1);
      ROSE_ASSERT(root->get_args()->get_expressions().front() == nested);
      ROSE_ASSERT(nested->get_parent() == root->get_args());
      ROSE_ASSERT(nested->get_args()->get_expressions().front() == nodes.at(7));
      SageInterface::deleteAST(root);
      ROSE_ASSERT(SgFunctionCallExp::numberOfNodes() == count);
    }
  }
}

void requireTypeOwnedCallConstruction() {
  using namespace Rose::AstJson;
  SgType *result_type = SageBuilder::buildIntType();
  SgFunctionType *function_type = SageBuilder::buildFunctionType(
      result_type, SageBuilder::buildFunctionParameterTypeList(result_type));
  std::unique_ptr<SgFunctionDeclaration, DeleteFixtureAst> declaration(
      new SgFunctionDeclaration(SgName("rex_json_call"), function_type, nullptr,
                                nullptr));
  auto symbol = std::make_unique<SgFunctionSymbol>(declaration.get());
  auto *callee = new SgFunctionRefExp(symbol.get(), symbol->get_type());
  SageBuilder::initializeSemanticExpressionSourceProvenance(callee);
  auto *arguments =
      SageBuilder::buildExprListExp(SageBuilder::buildIntVal_nfi(7, "7"));
  auto *original =
      SageBuilder::buildFunctionCallExp_nfi(callee, result_type, arguments);
  SageBuilder::initializeSemanticExpressionSourceProvenance(original);
  const auto serialized =
      parseJson(rawTypeOwnedExpressionRef(original, {{callee, 17}}));
  const auto fields =
      functionCallSourceFieldsFromJson(serialized.at("properties"));
  original->set_function(nullptr);
  callee->set_parent(nullptr);
  SageInterface::deleteAST(original);
  NodeMap nodes{{17, callee}};
  const size_t calls = SgFunctionCallExp::numberOfNodes();
  const size_t lists = SgExprListExp::numberOfNodes();
  const size_t positions = Sg_File_Info::numberOfNodes();
  for (const char *field : {"function", "args", "type"}) {
    auto malformed = serialized;
    malformed.object.at("properties").object.erase(field);
    bool rejected = false;
    try {
      SageInterface::deleteAST(expressionFromRef(malformed, nodes));
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what())
              .find(std::string("missing key: ") + field) != std::string::npos;
    }
    ROSE_ASSERT(rejected && callee->get_parent() == nullptr);
    ROSE_ASSERT(SgFunctionCallExp::numberOfNodes() == calls);
    ROSE_ASSERT(SgExprListExp::numberOfNodes() == lists);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  auto empty_arguments = std::make_unique<SgExprListExp>();
  for (SgType *invalid :
       {static_cast<SgType *>(nullptr), static_cast<SgType *>(function_type)}) {
    bool rejected = false;
    try {
      std::unique_ptr<SgFunctionCallExp> unexpected(constructFunctionCall(
          fields, callee, empty_arguments.get(), invalid, nullptr));
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what()).find("exact non-callable result type") !=
          std::string::npos;
    }
    ROSE_ASSERT(rejected && SgFunctionCallExp::numberOfNodes() == calls);
    ROSE_ASSERT(callee->get_parent() == nullptr &&
                empty_arguments->get_parent() == nullptr);
  }
  auto *restored = isSgFunctionCallExp(expressionFromRef(serialized, nodes));
  ROSE_ASSERT(restored != nullptr && restored->get_type() == result_type);
  ROSE_ASSERT(restored->get_function() == callee &&
              callee->get_parent() == restored);
  ROSE_ASSERT(restored->get_args()->get_parent() == restored);
  ROSE_ASSERT(restored->get_args()->get_expressions().size() == 1);
  auto *argument = isSgIntVal(restored->get_args()->get_expressions().front());
  ROSE_ASSERT(argument != nullptr && argument->get_value() == 7 &&
              argument->get_parent() == restored->get_args());
  auto *lexical = new SgCxxLiteralTokenList;
  auto *token =
      new SgCxxLiteralToken(SgCxxLiteralToken::e_numeric_token, "7_rex");
  SageInterface::setSourcePosition(token);
  auto comment = std::make_unique<PreprocessingInfo>(
      PreprocessingInfo::CplusplusStyleComment, "// rex_literal_comment\n",
      "rex_literal_comment.cpp", 1, 1, 1, PreprocessingInfo::before);
  token->attachPreprocessingInfo(
      comment.get(), PreprocessingInfo::before,
      SgLocatedNode::PreprocessingInfoInsertion::back);
  comment.release();
  token->set_parent(lexical);
  lexical->get_tokens().push_back(token);
  restored->set_source_user_defined_literal_operands(lexical);
  lexical->set_parent(restored);
  restored->set_uses_operator_syntax(true);
  restored->set_source_operator_surface(
      SgFunctionCallExp::e_user_defined_literal_surface);
  restored->set_source_operator_callee_form(
      SgFunctionCallExp::e_nonmember_operator_callee);
  restored->set_source_operator_operand_roles(
      {SgFunctionCallExp::e_semantic_operator_operand});
  restored->set_source_user_defined_literal_suffix("_rex");
  restored->set_source_user_defined_literal_suffix_roles(
      {SgFunctionCallExp::e_user_defined_literal_token_with_suffix});
  const auto literal =
      parseJson(rawTypeOwnedExpressionRef(restored, {{callee, 17}}));
  restored->set_function(nullptr);
  callee->set_parent(nullptr);
  SageInterface::deleteAST(restored);
  const auto literal_positions = Sg_File_Info::numberOfNodes();
  NodeRecord preprocessing_record;
  preprocessing_record.preprocessing =
      literal.at("properties")
          .at("source_user_defined_literal_operands")
          .at("tokens")
          .array.front()
          .at("properties")
          .at("preprocessing");
  preprocessing_record.preprocessing.array.push_back(
      preprocessing_record.preprocessing.array.front());
  preprocessing_record.preprocessing.array.back().object.at("directive") =
      JsonValue::number("9223372036854775807");
  const auto sequence = SgNode::get_globalAstModificationSequence();
  bool preprocessing_rejected = false;
  try {
    (void)preparePreprocessingInfo(preprocessing_record);
  } catch (const std::runtime_error &error) {
    preprocessing_rejected =
        std::string(error.what()).find("invalid directive") !=
        std::string::npos;
  }
  ROSE_ASSERT(preprocessing_rejected);
  ROSE_ASSERT(Sg_File_Info::numberOfNodes() == literal_positions);
  ROSE_ASSERT(SgNode::get_globalAstModificationSequence() == sequence);
  for (const char *invalid :
       {"attributes", "spelling", "location", "preprocessing", "shared"}) {
    auto malformed = literal;
    auto &literal_record =
        malformed.object.at("properties")
            .object.at("source_user_defined_literal_operands")
            .object.at("tokens")
            .array.front();
    auto &properties = literal_record.object.at("properties");
    if (std::string(invalid) == "spelling")
      properties.object.at("spelling") = JsonValue::string("");
    else if (std::string(invalid) == "location")
      literal_record.object.at("location") = JsonValue::number("0");
    else if (std::string(invalid) == "shared")
      properties.object.at("preprocessing")
          .array.front()
          .object.at("file_info")
          .object.at("shared") = JsonValue::boolean(true);
    else
      properties.object.at(invalid) = JsonValue::number("0");
    bool rejected = false;
    try {
      SageInterface::deleteAST(expressionFromRef(malformed, nodes));
    } catch (const std::runtime_error &error) {
      const std::string message = error.what();
      rejected = message.find(invalid) != std::string::npos;
    }
    ROSE_ASSERT(rejected && callee->get_parent() == nullptr);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == literal_positions);
  }
  auto *literal_copy = isSgFunctionCallExp(expressionFromRef(literal, nodes));
  ASSERT_not_null(literal_copy);
  auto *copied_tokens =
      literal_copy->get_source_user_defined_literal_operands();
  ROSE_ASSERT(copied_tokens->get_tokens().front()->get_spelling() == "7_rex");
  SageInterface::deleteAST(literal_copy);
  ROSE_ASSERT(SgFunctionCallExp::numberOfNodes() == calls);
}

void requireConditionalConstruction() {
  using namespace Rose::AstJson;
  for (bool gnu : {false, true}) {
    auto *condition = SageBuilder::buildIntVal_nfi(1, "1");
    auto *yes = gnu ? nullptr : SageBuilder::buildIntVal_nfi(2, "2");
    auto *no = SageBuilder::buildIntVal_nfi(3, "3");
    auto *original = new SgConditionalExp(
        condition, yes, no, SageBuilder::buildIntType(),
        gnu ? SgConditionalExp::e_conditional_operator_gnu_binary
            : SgConditionalExp::e_conditional_operator_standard);
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    NodeRecord record;
    record.id = 1;
    record.kind = "SgConditionalExp";
    record.flags = parseJson(rawNodeFlagsJson(original));
    record.location = parseJson(rawLocationJson(original));
    record.properties = parseJson(rawNodeProperties(original, {}));
    record.edges = {{"conditional_exp", 2, 0}, {"false_exp", 4, 0}};
    if (!gnu)
      record.edges.push_back({"true_exp", 3, 0});
    std::vector<NodeRecord> children;
    for (const auto &entry : std::vector<std::pair<uint64_t, SgExpression *>>{
             {2, condition}, {3, yes}, {4, no}}) {
      if (entry.second == nullptr)
        continue;
      NodeRecord child;
      child.id = entry.first;
      child.kind = entry.second->class_name();
      child.flags = parseJson(rawNodeFlagsJson(entry.second));
      child.location = parseJson(rawLocationJson(entry.second));
      child.properties = parseJson(rawNodeProperties(entry.second, {}));
      child.edges.push_back({"parent", 1, 0});
      children.push_back(child);
    }
    const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
    SageInterface::deleteAST(original);
    const size_t count = SgConditionalExp::numberOfNodes();
    const size_t value_count = SgIntVal::numberOfNodes();
    const size_t position_count = Sg_File_Info::numberOfNodes();
    for (const char *field : {"conditional_exp", "true_exp", "false_exp"}) {
      auto malformed = owned;
      malformed.object.at("properties").object.erase(field);
      bool rejected = false;
      try {
        SageInterface::deleteAST(expressionFromRef(malformed, {}));
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what())
                       .find(std::string("missing key: ") + field) !=
                   std::string::npos;
      }
      ROSE_ASSERT(rejected && SgConditionalExp::numberOfNodes() == count);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == value_count);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == position_count);
    }
    auto detached_condition = std::make_unique<SgIntVal>(1, "1");
    auto detached_true = std::make_unique<SgIntVal>(2, "2");
    auto detached_false = std::make_unique<SgIntVal>(3, "3");
    for (int invalid = 0; invalid < 4; ++invalid) {
      auto bad = record.properties;
      SgExpression *c = detached_condition.get();
      SgExpression *t = gnu ? nullptr : detached_true.get();
      SgExpression *f = detached_false.get();
      if (invalid == 0)
        c = nullptr;
      else if (invalid == 1)
        t = gnu ? detached_true.get() : nullptr;
      else if (invalid == 2)
        f = c;
      else
        bad.object.erase("type");
      bool rejected = false;
      try {
        std::unique_ptr<SgConditionalExp> unexpected(conditionalFromProperties(
            bad, {}, conditionalOperatorKindFromJson(bad), c, t, f));
      } catch (const std::runtime_error &error) {
        const char *expected = invalid < 2    ? "invalid operand arity"
                               : invalid == 2 ? "exclusive operands"
                                              : "missing key: type";
        rejected =
            std::string(error.what()).find(expected) != std::string::npos;
      }
      ROSE_ASSERT(rejected && SgConditionalExp::numberOfNodes() == count);
      ROSE_ASSERT(detached_condition->get_parent() == nullptr &&
                  detached_true->get_parent() == nullptr &&
                  detached_false->get_parent() == nullptr);
    }
    for (int repeat = 0; repeat < 3; ++repeat) {
      auto check = [&](SgConditionalExp *expression) {
        ROSE_ASSERT(expression != nullptr);
        expression->validate();
        ROSE_ASSERT(expression->get_type() == SageBuilder::buildIntType());
        ROSE_ASSERT((expression->get_true_exp() == nullptr) == gnu);
        ROSE_ASSERT(
            isSgIntVal(expression->get_conditional_exp())->get_value() == 1);
        ROSE_ASSERT(isSgIntVal(expression->get_false_exp())->get_value() == 3);
      };
      auto *restored = isSgConditionalExp(expressionFromRef(owned, {}));
      check(restored);
      SageInterface::deleteAST(restored);
      AstFileRecord ast;
      ast.nodes = {record};
      NodeMap nodes;
      for (const auto &child : children) {
        ast.nodes.push_back(child);
        nodes.emplace(child.id, createNodeFromRecord(child, nullptr));
      }
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      restored = isSgConditionalExp(nodes.at(1));
      check(restored);
      SageInterface::deleteAST(restored);
      bool rejected = false;
      try {
        std::unique_ptr<SgNode> unexpected(
            createNodeFromRecord(record, nullptr));
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what())
                       .find("exact operand and type construction") !=
                   std::string::npos;
      }
      ROSE_ASSERT(rejected && SgConditionalExp::numberOfNodes() == count);
      auto bad = record.properties;
      bad.object.at("conditional_operator_kind") = parseJson("9999");
      rejected = false;
      try {
        std::unique_ptr<SgConditionalExp> unexpected(conditionalFromProperties(
            bad, {}, conditionalOperatorKindFromJson(bad), nullptr, nullptr,
            nullptr));
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what())
                       .find("invalid conditional_operator_kind enum value") !=
                   std::string::npos;
      }
      ROSE_ASSERT(rejected && SgConditionalExp::numberOfNodes() == count);
    }
  }
}

void requireChooseConstruction() {
  using namespace Rose::AstJson;
  using Choose = SgChooseExpression;
  for (bool selected : {false, true}) {
    const auto selection = selected ? Choose::e_choose_selection_true
                                    : Choose::e_choose_selection_false;
    auto *original = SageBuilder::buildChooseExpression_nfi(
        SageBuilder::buildIntVal_nfi(selected ? 1 : 0),
        SageBuilder::buildIntVal_nfi(2), SageBuilder::buildIntVal_nfi(3),
        SageBuilder::buildIntType(), selection);
    SageBuilder::initializeSemanticExpressionSourceProvenance(original);
    NodeRecord record;
    record.id = 1;
    record.kind = original->class_name();
    record.flags = parseJson(rawNodeFlagsJson(original));
    record.location = parseJson(rawLocationJson(original));
    record.properties = parseJson(rawNodeProperties(original, {}));
    std::vector<NodeRecord> records{record};
    for (const auto &entry :
         std::vector<std::pair<const char *, SgExpression *>>{
             {"condition", original->get_condition()},
             {"true_expression", original->get_true_expression()},
             {"false_expression", original->get_false_expression()}}) {
      NodeRecord child;
      child.id = records.size() + 1;
      child.kind = entry.second->class_name();
      child.flags = parseJson(rawNodeFlagsJson(entry.second));
      child.location = parseJson(rawLocationJson(entry.second));
      child.properties = parseJson(rawNodeProperties(entry.second, {}));
      child.edges.push_back({"parent", 1, 0});
      records.front().edges.push_back({entry.first, child.id, 0});
      records.push_back(std::move(child));
    }
    const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
    SageInterface::deleteAST(original);
    const auto choices = Choose::numberOfNodes();
    const auto values = SgIntVal::numberOfNodes();
    const auto positions = Sg_File_Info::numberOfNodes();
    for (const char *invalid : {"", "0", "9999"}) {
      auto bad = owned;
      auto bad_record = records.front();
      for (auto *properties :
           {&bad.object.at("properties"), &bad_record.properties}) {
        if (*invalid == '\0')
          properties->object.erase("selection_kind");
        else
          properties->object.at("selection_kind") = parseJson(invalid);
      }
      for (bool inline_reader : {false, true}) {
        NodeMap nodes;
        bool rejected = false;
        try {
          if (inline_reader)
            SageInterface::deleteAST(expressionFromRef(bad, nodes));
          else {
            auto bad_records = records;
            bad_records.front() = bad_record;
            rebuildConstructorOnlyNodes(recordGraph(bad_records), nodes);
          }
        } catch (const std::runtime_error &error) {
          rejected = std::string(error.what()).find("selection_kind") !=
                     std::string::npos;
        }
        ROSE_ASSERT(rejected && nodes.empty());
        ROSE_ASSERT(Choose::numberOfNodes() == choices &&
                    SgIntVal::numberOfNodes() == values &&
                    Sg_File_Info::numberOfNodes() == positions);
      }
    }
    auto check = [&](SgChooseExpression *choice) {
      ROSE_ASSERT(choice != nullptr &&
                  choice->get_selection_kind() == selection &&
                  choice->get_type() == SageBuilder::buildIntType());
      choice->validate();
      ROSE_ASSERT(isSgIntVal(choice->get_condition())->get_value() == selected);
      ROSE_ASSERT(isSgIntVal(choice->get_true_expression())->get_value() == 2);
      ROSE_ASSERT(isSgIntVal(choice->get_false_expression())->get_value() == 3);
    };
    auto *restored = isSgChooseExpression(expressionFromRef(owned, {}));
    check(restored);
    SageInterface::deleteAST(restored);
    NodeMap nodes;
    for (size_t index = 1; index < records.size(); ++index)
      nodes.emplace(records[index].id,
                    createNodeFromRecord(records[index], nullptr));
    rebuildConstructorOnlyNodes(recordGraph(records), nodes);
    restored = isSgChooseExpression(nodes.at(1));
    check(restored);
    linkNodeEdges(records.front(), nodes);
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(Choose::numberOfNodes() == choices &&
                SgIntVal::numberOfNodes() == values &&
                Sg_File_Info::numberOfNodes() == positions);
  }
}

void requireBuiltinResultConstruction() {
  using namespace Rose::AstJson;
  using Builtin = SgTypeTraitBuiltinOperator;
  SgType *type = SageBuilder::buildBoolType();
  auto *argument = new SgTypeExpression(SageBuilder::buildIntType());
  SageBuilder::initializeSemanticExpressionSourceProvenance(argument);
  auto *original = SageBuilder::buildTypeTraitBuiltinOperator_nfi(
      SgName("__is_integral"), Builtin::e_type_trait_builtin, type, {argument});
  SageBuilder::initializeSemanticExpressionSourceProvenance(original);
  ROSE_ASSERT(original->get_type() == type &&
              argument->get_parent() == original);
  NodeRecord record;
  record.id = 1;
  record.kind = "SgTypeTraitBuiltinOperator";
  record.flags = parseJson(rawNodeFlagsJson(original));
  record.location = parseJson(rawLocationJson(original));
  record.properties = parseJson(rawNodeProperties(original, {{original, 1}}));
  record.edges.push_back({"args", 2, 0});
  NodeRecord child;
  child.id = 2;
  child.kind = "SgTypeExpression";
  child.flags = parseJson(rawNodeFlagsJson(argument));
  child.location = parseJson(rawLocationJson(argument));
  child.properties = parseJson(rawNodeProperties(argument, {{argument, 2}}));
  child.edges.push_back({"parent", 1, 0});
  const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
  SageInterface::deleteAST(original);
  const size_t count = Builtin::numberOfNodes();
  auto detached =
      std::make_unique<SgTypeExpression>(SageBuilder::buildIntType());
  for (const SgExpressionPtrList &bad_arguments :
       {SgExpressionPtrList{}, SgExpressionPtrList{nullptr},
        SgExpressionPtrList{detached.get(), detached.get()}}) {
    bool rejected = false;
    try {
      std::unique_ptr<Builtin> unexpected(
          typeTraitBuiltinFromProperties(record.properties, {}, bad_arguments));
    } catch (const std::runtime_error &error) {
      const std::string message = error.what();
      rejected =
          message.find("exclusive operands") != std::string::npos ||
          message.find("invalid typed argument roles") != std::string::npos;
    }
    ROSE_ASSERT(rejected && Builtin::numberOfNodes() == count);
    ROSE_ASSERT(detached->get_parent() == nullptr);
  }
  for (int repeat = 0; repeat < 3; ++repeat) {
    auto *restored = isSgTypeTraitBuiltinOperator(expressionFromRef(owned, {}));
    ROSE_ASSERT(restored != nullptr && restored->get_type() == type);
    ROSE_ASSERT(restored->get_args().size() == 1);
    ROSE_ASSERT(restored->get_args().front()->get_parent() == restored);
    SageInterface::deleteAST(restored);
    AstFileRecord ast;
    ast.nodes = {record, child};
    NodeMap nodes;
    rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    restored = isSgTypeTraitBuiltinOperator(nodes.at(1));
    ROSE_ASSERT(restored != nullptr && restored->get_type() == type);
    ROSE_ASSERT(restored->get_args().size() == 1);
    ROSE_ASSERT(restored->get_args().front() == nodes.at(2));
    ROSE_ASSERT(restored->get_args().front()->get_parent() == restored);
    SageInterface::deleteAST(restored);
    for (int invalid = 0; invalid < 3; ++invalid) {
      auto bad = record.properties;
      if (invalid == 0)
        bad.object.erase("type");
      else if (invalid == 1)
        bad.object.at("builtin_operator_kind") = parseJson("9999");
      else
        bad.object.at("name") = JsonValue::string("");
      bool rejected = false;
      try {
        std::unique_ptr<Builtin> unexpected(
            typeTraitBuiltinFromProperties(bad, {}, {}));
      } catch (const std::runtime_error &error) {
        const char *expected = invalid == 0 ? "missing key: type"
                               : invalid == 1
                                   ? "invalid builtin_operator_kind enum value"
                                   : "empty name";
        rejected =
            std::string(error.what()).find(expected) != std::string::npos;
      }
      ROSE_ASSERT(rejected && Builtin::numberOfNodes() == count);
    }
  }
}

void requireUnaryTraitConstruction() {
  using namespace Rose::AstJson;
  for (auto kind :
       {SgExpression::e_sizeof, SgExpression::e_datasizeof,
        SgExpression::e_alignof, SgExpression::e_preferred_alignof}) {
    const bool size_of =
        kind == SgExpression::e_sizeof || kind == SgExpression::e_datasizeof;
    for (bool expression_operand : {false, true}) {
      SgExpression *operand =
          expression_operand ? SageBuilder::buildIntVal(7) : nullptr;
      SgType *operand_type =
          expression_operand ? nullptr : SageBuilder::buildIntType();
      SgType *result_type = SageBuilder::buildUnsignedLongType();
      const std::optional<Rose::Integer128Value> evaluated_value =
          expression_operand
              ? std::make_optional(
                    Rose::Integer128Value::fromBits({4, 0}, true))
              : std::nullopt;
      SgExpression *original =
          size_of
              ? static_cast<SgExpression *>(new SgSizeOfOp(
                    operand, operand_type, result_type, kind, evaluated_value))
              : static_cast<SgExpression *>(new SgAlignOfOp(
                    operand, operand_type, result_type, kind, evaluated_value));
      const auto source_kind =
          expression_operand ? SgNonrealDecl::e_source_elaboration_unspecified
                             : SgNonrealDecl::e_source_elaboration_none;
      if (size_of)
        isSgSizeOfOp(original)->set_source_type_elaboration_kind(source_kind);
      else
        isSgAlignOfOp(original)->set_source_type_elaboration_kind(source_kind);
      if (operand != nullptr)
        operand->set_parent(original);
      SageBuilder::initializeSemanticExpressionSourceProvenance(original);
      auto *copy = isSgExpression(SageInterface::deepCopy(original));
      ROSE_ASSERT(copy != nullptr && copy != original);
      if (size_of) {
        auto *trait = isSgSizeOfOp(copy);
        ROSE_ASSERT(trait->get_evaluated_value() == evaluated_value);
        trait->set_operator_kind(kind);
        ROSE_ASSERT(trait->get_evaluated_value() == evaluated_value);
        trait->set_operator_kind(kind == SgExpression::e_sizeof
                                     ? SgExpression::e_datasizeof
                                     : SgExpression::e_sizeof);
        ROSE_ASSERT(!trait->get_evaluated_value());
      } else {
        auto *trait = isSgAlignOfOp(copy);
        ROSE_ASSERT(trait->get_evaluated_value() == evaluated_value);
        trait->set_operator_kind(kind);
        ROSE_ASSERT(trait->get_evaluated_value() == evaluated_value);
        trait->set_operator_kind(kind == SgExpression::e_alignof
                                     ? SgExpression::e_preferred_alignof
                                     : SgExpression::e_alignof);
        ROSE_ASSERT(!trait->get_evaluated_value());
      }
      SageInterface::deleteAST(copy);
      std::unordered_map<const SgNode *, uint64_t> ids{{original, 1}};
      if (operand != nullptr)
        ids.emplace(operand, 2);
      NodeRecord record;
      record.id = 1;
      record.kind = original->class_name();
      record.flags = parseJson(rawNodeFlagsJson(original));
      record.location = parseJson(rawLocationJson(original));
      record.properties = parseJson(rawNodeProperties(original, ids));
      if (operand != nullptr)
        record.edges.push_back({"operand_expr", 2, 0});
      const JsonValue owned =
          parseJson(rawTypeOwnedExpressionRef(original, {}));
      SageInterface::deleteAST(original);
      const auto sizes = SgSizeOfOp::numberOfNodes();
      const auto alignments = SgAlignOfOp::numberOfNodes();
      for (int repeat = 0; repeat != 25; ++repeat) {
        auto *restored_owned = expressionFromRef(owned, {});
        ROSE_ASSERT(restored_owned != nullptr &&
                    restored_owned->get_type() == result_type);
        ROSE_ASSERT(
            (size_of ? isSgSizeOfOp(restored_owned)->get_evaluated_value()
                     : isSgAlignOfOp(restored_owned)->get_evaluated_value()) ==
            evaluated_value);
        ROSE_ASSERT(
            size_of
                ? isSgSizeOfOp(restored_owned)->get_operator_kind() == kind
                : isSgAlignOfOp(restored_owned)->get_operator_kind() == kind);
        ROSE_ASSERT((size_of ? isSgSizeOfOp(restored_owned)
                                   ->get_source_type_elaboration_kind()
                             : isSgAlignOfOp(restored_owned)
                                   ->get_source_type_elaboration_kind()) ==
                    source_kind);
        SageInterface::deleteAST(restored_owned);
        for (int invalid = 0; invalid != 12; ++invalid) {
          const char *expected =
              invalid == 1   ? "not the exact unsigned target size_t type"
              : invalid == 2 ? "missing key: operator_kind"
              : invalid == 3 ? "invalid operator_kind enum value"
              : invalid == 5 ? "missing key: type_elaboration_required"
              : invalid == 6 ? "missing key: source_type_elaboration_kind"
              : invalid == 7 ? "invalid source_type_elaboration_kind enum value"
              : invalid == 8
                  ? (size_of ? "missing key: "
                               "is_objectless_nonstatic_data_member_reference"
                             : "invalid evaluated value")
              : invalid == 9  ? "missing key: evaluated_value"
              : invalid == 10 ? "invalid evaluated value"
              : invalid == 11 ? "128-bit integer requires four words"
                              : "retired is_sizeof_pack field";
          auto corrupt = [&](JsonValue &properties) {
            if (invalid == 1)
              properties.object.at("type") =
                  parseJson(rawTypeJson(SageBuilder::buildIntType(), {}));
            else if (invalid == 2)
              properties.object.erase("operator_kind");
            else if (invalid == 3)
              properties.object.at("operator_kind") = JsonValue::number(
                  std::to_string(size_of ? SgExpression::e_alignof
                                         : SgExpression::e_sizeof));
            else if (invalid == 4)
              properties.object.emplace("is_sizeof_pack",
                                        JsonValue::boolean(false));
            else if (invalid == 5)
              properties.object.erase("type_elaboration_required");
            else if (invalid == 6)
              properties.object.erase("source_type_elaboration_kind");
            else if (invalid == 7)
              properties.object.at("source_type_elaboration_kind") =
                  JsonValue::number("9999");
            else if (invalid == 8) {
              if (size_of) {
                properties.object.erase(
                    "is_objectless_nonstatic_data_member_reference");
                properties.object.at("type") = JsonValue::objectValue({});
              } else {
                properties.object.at("evaluated_value") =
                    parseJson(rawInteger128Value(
                        Rose::Integer128Value::fromBits({0, 0}, true)));
              }
            } else if (invalid == 9) {
              properties.object.erase("evaluated_value");
            } else if (invalid == 10) {
              properties.object.at("evaluated_value") =
                  parseJson(rawInteger128Value(
                      Rose::Integer128Value::fromBits({4, 0}, false)));
            } else if (invalid == 11) {
              properties.object.at("evaluated_value") =
                  parseJson("{\"unsigned\": true, \"words\": [4, 0]}");
            }
          };
          AstFileRecord ast;
          ast.nodes = {record};
          corrupt(ast.nodes[0].properties);
          NodeMap nodes;
          SgExpression *fresh_operand = nullptr;
          if (expression_operand) {
            fresh_operand = SageBuilder::buildIntVal(7);
            nodes.emplace(2, fresh_operand);
            NodeRecord child;
            child.id = 2;
            child.kind = "SgIntVal";
            child.edges.push_back({"parent", 1, 0});
            ast.nodes.push_back(child);
          }
          bool rejected = false;
          try {
            rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
          } catch (const std::runtime_error &error) {
            if (std::string(error.what()).find(expected) == std::string::npos)
              throw;
            rejected = true;
          }
          if (invalid != 0) {
            ROSE_ASSERT(rejected && nodes.count(1) == 0);
            if (fresh_operand != nullptr) {
              ROSE_ASSERT(fresh_operand->get_parent() == nullptr);
              SageInterface::deleteAST(fresh_operand);
            }
          } else {
            ROSE_ASSERT(!rejected);
            auto *restored = isSgExpression(nodes.at(1));
            ROSE_ASSERT(restored != nullptr &&
                        restored->get_type() == result_type);
            ROSE_ASSERT(
                (size_of ? isSgSizeOfOp(restored)->get_evaluated_value()
                         : isSgAlignOfOp(restored)->get_evaluated_value()) ==
                evaluated_value);
            ROSE_ASSERT(
                size_of ? isSgSizeOfOp(restored)->get_operator_kind() == kind
                        : isSgAlignOfOp(restored)->get_operator_kind() == kind);
            ROSE_ASSERT((size_of ? isSgSizeOfOp(restored)
                                       ->get_source_type_elaboration_kind()
                                 : isSgAlignOfOp(restored)
                                       ->get_source_type_elaboration_kind()) ==
                        source_kind);
            if (fresh_operand != nullptr)
              ROSE_ASSERT(fresh_operand->get_parent() == restored);
            SageInterface::deleteAST(restored);
          }
          ROSE_ASSERT(SgSizeOfOp::numberOfNodes() == sizes &&
                      SgAlignOfOp::numberOfNodes() == alignments);
          if (invalid != 0) {
            auto malformed = owned;
            corrupt(malformed.object.at("properties"));
            bool inline_rejected = false;
            try {
              auto *unexpected = expressionFromRef(malformed, {});
              SageInterface::deleteAST(unexpected);
            } catch (const std::runtime_error &error) {
              ROSE_ASSERT(std::string(error.what()).find(expected) !=
                          std::string::npos);
              inline_rejected = true;
            }
            ROSE_ASSERT(inline_rejected);
            ROSE_ASSERT(SgSizeOfOp::numberOfNodes() == sizes &&
                        SgAlignOfOp::numberOfNodes() == alignments);
          }
        }
      }
    }
  }
}

void requireGraphCastConstruction() {
  using namespace Rose::AstJson;
  auto *literal = SageBuilder::buildIntVal(7);
  auto *inner =
      SageBuilder::buildCastExp(literal, SageBuilder::buildDoubleType());
  auto *outer =
      SageBuilder::buildCastExp(inner, SageBuilder::buildLongDoubleType());
  auto *assignment = SageBuilder::buildAssignInitializer_nfi(
      outer, SageBuilder::buildLongDoubleType());
  assignment->set_is_braced_initialized(true);
  SageBuilder::initializeSemanticExpressionSourceProvenance(assignment);
  std::unordered_map<const SgNode *, uint64_t> ids{
      {assignment, 1}, {outer, 2}, {inner, 3}, {literal, 4}};
  AstFileRecord ast;
  for (SgNode *node :
       std::vector<SgNode *>{assignment, outer, inner, literal}) {
    NodeRecord record;
    record.id = ids.at(node);
    record.kind = node->class_name();
    record.flags = parseJson(rawNodeFlagsJson(node));
    record.location = parseJson(rawLocationJson(node));
    record.properties = parseJson(rawNodeProperties(node, ids));
    if (node != assignment)
      record.edges.push_back({"parent", record.id - 1, 0});
    if (node != literal)
      record.edges.push_back({"operand_i", record.id + 1, 0});
    ast.nodes.push_back(record);
  }
  SageInterface::deleteAST(assignment);
  const auto casts = SgCastExp::numberOfNodes();
  const auto initializers = SgAssignInitializer::numberOfNodes();
  for (int repeat = 0; repeat != 100; ++repeat) {
    std::reverse(ast.nodes.begin(), ast.nodes.end());
    auto *operand = SageBuilder::buildIntVal(7);
    NodeMap nodes{{4, operand}};
    rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    auto *restored_inner = isSgCastExp(nodes.at(3));
    auto *restored_outer = isSgCastExp(nodes.at(2));
    auto *restored_assignment = isSgAssignInitializer(nodes.at(1));
    ROSE_ASSERT(restored_inner != nullptr && restored_outer != nullptr &&
                restored_assignment != nullptr);
    ROSE_ASSERT(restored_assignment->get_is_braced_initialized());
    ROSE_ASSERT(restored_inner->get_type() == SageBuilder::buildDoubleType());
    ROSE_ASSERT(restored_outer->get_type() ==
                SageBuilder::buildLongDoubleType());
    ROSE_ASSERT(restored_inner->get_operand_i() == operand &&
                operand->get_parent() == restored_inner &&
                restored_outer->get_operand_i() == restored_inner &&
                restored_inner->get_parent() == restored_outer &&
                restored_assignment->get_operand_i() == restored_outer &&
                restored_outer->get_parent() == restored_assignment);
    SageInterface::deleteAST(restored_assignment);
    ROSE_ASSERT(SgCastExp::numberOfNodes() == casts &&
                SgAssignInitializer::numberOfNodes() == initializers);
  }
}

void requireInitializerInputBeforeAllocation() {
  using namespace Rose::AstJson;
  auto *operand = SageBuilder::buildIntVal(7);
  auto *original = SageBuilder::buildAssignInitializer_nfi(
      operand, SageBuilder::buildIntType());
  original->set_is_braced_initialized(true);
  SageBuilder::initializeSemanticExpressionSourceProvenance(original);
  NodeRecord owner_record;
  owner_record.id = 1;
  owner_record.kind = "SgAssignInitializer";
  owner_record.flags = parseJson(rawNodeFlagsJson(original));
  owner_record.location = parseJson(rawLocationJson(original));
  owner_record.properties =
      parseJson(rawNodeProperties(original, {{original, 1}, {operand, 2}}));
  owner_record.edges.push_back({"operand_i", 2, 0});
  NodeRecord operand_record;
  operand_record.id = 2;
  operand_record.kind = "SgIntVal";
  operand_record.edges.push_back({"parent", 1, 0});
  const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
  SageInterface::deleteAST(original);

  const auto initializers = SgAssignInitializer::numberOfNodes();
  for (int repeat = 0; repeat != 100; ++repeat) {
    for (int mutation = 0; mutation != 4; ++mutation) {
      AstFileRecord ast;
      ast.nodes = repeat % 2 == 0
                      ? std::vector<NodeRecord>{owner_record, operand_record}
                      : std::vector<NodeRecord>{operand_record, owner_record};
      NodeRecord &record = ast.nodes[repeat % 2 == 0 ? 0 : 1];
      auto corrupt = [&](JsonValue &properties) {
        if (mutation == 1) {
          properties.object.erase("assignment_initializer_source_form");
        } else if (mutation == 2) {
          properties.object.at("assignment_initializer_source_form") =
              parseJson("-1");
        } else if (mutation == 3) {
          properties.object.erase("is_braced_initialized");
          properties.object.at("type") = JsonValue::objectValue({});
        }
      };
      corrupt(record.properties);
      auto *fresh_operand = SageBuilder::buildIntVal(7);
      NodeMap nodes{{2, fresh_operand}};
      bool rejected = false;
      try {
        rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
      } catch (const std::runtime_error &error) {
        if (mutation == 3)
          ROSE_ASSERT(std::string(error.what())
                          .find("missing key: is_braced_initialized") !=
                      std::string::npos);
        rejected = true;
      }
      if (mutation == 0) {
        ROSE_ASSERT(!rejected);
        auto *restored = isSgAssignInitializer(nodes.at(1));
        ROSE_ASSERT(restored != nullptr &&
                    restored->get_operand_i() == fresh_operand &&
                    fresh_operand->get_parent() == restored &&
                    restored->get_type() == SageBuilder::buildIntType() &&
                    restored->get_is_braced_initialized());
        SageInterface::deleteAST(restored);
      } else {
        ROSE_ASSERT(rejected && nodes.count(1) == 0);
        ROSE_ASSERT(fresh_operand->get_parent() == nullptr);
        SageInterface::deleteAST(fresh_operand);
      }
      ROSE_ASSERT(SgAssignInitializer::numberOfNodes() == initializers);
      auto malformed_owned = owned;
      corrupt(malformed_owned.object.at("properties"));
      const auto values = SgIntVal::numberOfNodes();
      bool owned_rejected = false;
      try {
        auto *restored =
            isSgAssignInitializer(expressionFromRef(malformed_owned, {}));
        ROSE_ASSERT(restored != nullptr &&
                    restored->get_is_braced_initialized());
        SageInterface::deleteAST(restored);
      } catch (const std::runtime_error &error) {
        if (mutation == 3)
          ROSE_ASSERT(std::string(error.what())
                          .find("missing key: is_braced_initialized") !=
                      std::string::npos);
        owned_rejected = true;
      }
      ROSE_ASSERT(owned_rejected == (mutation != 0));
      ROSE_ASSERT(SgAssignInitializer::numberOfNodes() == initializers &&
                  SgIntVal::numberOfNodes() == values);
    }
  }
}

void requirePseudoDestructorCallableIdentity() {
  using namespace Rose::AstJson;
  FunctionTypeDeserializationIdentityGuard identity;
  SgType *object_type = SageBuilder::buildIntType();
  auto *original = new SgPseudoDestructorRefExp(
      object_type,
      new SgMemberFunctionType(SageBuilder::buildVoidType(), false,
                               new SgFunctionParameterTypeList(), object_type));
  SageInterface::setOneSourcePositionNull(original);
  SageBuilder::initializeSemanticExpressionSourceProvenance(original);
  NodeRecord valid;
  valid.id = 1;
  valid.kind = "SgPseudoDestructorRefExp";
  valid.flags = parseJson(rawNodeFlagsJson(original));
  valid.location = parseJson(rawLocationJson(original));
  valid.properties = parseJson(rawNodeProperties(original, {{original, 1}}));
  SageInterface::deleteAST(original);
  for (int variant = 0; variant != 4; ++variant) {
    SgType *argument_type = nullptr;
    if (variant == 2)
      argument_type = object_type;
    else if (variant == 3)
      argument_type = SgTypeEllipse::createType();
    auto arguments = std::unique_ptr<SgFunctionParameterTypeList>(
        SageBuilder::buildFunctionParameterTypeList(argument_type));
    auto *signature = SageBuilder::buildMemberFunctionType(
        SageBuilder::buildVoidType(), arguments.get(),
        variant == 1 ? SageBuilder::buildDoubleType() : object_type, 0);
    if (signature->get_argument_list() == arguments.get())
      arguments.release();

    NodeRecord record = valid;
    record.properties.object["type"] = parseJson(rawTypeJson(signature, {}));
    AstFileRecord ast;
    ast.nodes = {record};
    NodeMap nodes;
    const auto expressions = SgPseudoDestructorRefExp::numberOfNodes();
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    } catch (const std::runtime_error &error) {
      if (std::string(error.what())
              .find("SgPseudoDestructorRefExp has incomplete exact type") ==
          std::string::npos)
        throw;
      rejected = true;
    }
    if (variant == 0) {
      ROSE_ASSERT(!rejected);
      auto *restored = isSgPseudoDestructorRefExp(nodes.at(1));
      ROSE_ASSERT(restored != nullptr &&
                  restored->get_object_type() == object_type);
      SageInterface::deleteAST(restored);
    } else {
      ROSE_ASSERT(rejected && nodes.count(1) == 0);
    }
    ROSE_ASSERT(SgPseudoDestructorRefExp::numberOfNodes() == expressions);
  }
}

void requireGraphTypeExpressionConstruction() {
  using namespace Rose::AstJson;
  auto *precision = SageBuilder::buildFloatType(SageBuilder::buildIntVal(8));
  auto *original = new SgTypeExpression(precision);
  original->set_name_qualification_length(2);
  original->set_type_elaboration_required(true);
  original->set_global_qualification_required(true);
  SageInterface::setOneSourcePositionNull(original);
  SageBuilder::initializeSemanticExpressionSourceProvenance(original);
  NodeRecord record;
  record.id = 1;
  record.kind = "SgTypeExpression";
  record.flags = parseJson(rawNodeFlagsJson(original));
  record.location = parseJson(rawLocationJson(original));
  record.properties = parseJson(rawNodeProperties(original, {{original, 1}}));
  SageBuilder::buildUnknownType();
  SgTypeDefault::createType();
  const auto expressions = SgTypeExpression::numberOfNodes();
  const auto positions = Sg_File_Info::numberOfNodes();
  for (int repeat = 0; repeat != 100; ++repeat) {
    AstFileRecord ast;
    ast.nodes = {record};
    NodeMap nodes;
    rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    auto *result = isSgTypeExpression(nodes.at(1));
    ROSE_ASSERT(result != nullptr &&
                result->get_represented_type() == precision);
    ROSE_ASSERT(result->get_name_qualification_length() == 2);
    ROSE_ASSERT(result->get_type_elaboration_required());
    ROSE_ASSERT(result->get_global_qualification_required());
    SageInterface::deleteAST(result);
    ROSE_ASSERT(SgTypeExpression::numberOfNodes() == expressions);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    for (int mutation = 0; mutation != 6; ++mutation) {
      AstFileRecord bad = ast;
      auto &properties = bad.nodes[0].properties;
      if (mutation == 0)
        properties.object.erase("represented_type");
      else if (mutation == 1)
        properties.object.at("represented_type") =
            parseJson(R"({"present":false})");
      else if (mutation < 4)
        properties.object.at("represented_type") = parseJson(
            mutation == 2 ? R"({"present":true,"kind":"SgTypeUnknown"})"
                          : R"({"present":true,"kind":"SgTypeDefault"})");
      else if (mutation == 4)
        properties.object.at("semantic_wrapper_mask") = parseJson("4294967296");
      else {
        properties.object.at("fortran_integer_constant_value") =
            JsonValue::number("1");
        properties.object.at("represented_type") = JsonValue::objectValue({});
      }
      NodeMap empty;
      bool rejected = false;
      try {
        rebuildConstructorOnlyNodes(recordGraph(bad.nodes), empty);
      } catch (const std::runtime_error &error) {
        if (mutation == 5)
          ROSE_ASSERT(std::string(error.what())
                          .find("folded selector value without availability") !=
                      std::string::npos);
        rejected = true;
      }
      ROSE_ASSERT(rejected && empty.empty());
      ROSE_ASSERT(SgTypeExpression::numberOfNodes() == expressions);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
  }
  bool rejected = false;
  try {
    (void)createNodeFromRecord(record, nullptr);
  } catch (const std::runtime_error &) {
    rejected = true;
  }
  ROSE_ASSERT(rejected && SgTypeExpression::numberOfNodes() == expressions);
  SageInterface::deleteAST(original);
}

void requireGraphComplexConstruction() {
  using namespace Rose::AstJson;
  const auto previousMode = SageBuilder::getSourcePositionClassificationMode();
  SageBuilder::setSourcePositionClassificationMode(
      SageBuilder::e_sourcePositionTransformation);
  auto *precision = SageBuilder::buildFloatType(SageBuilder::buildIntVal(8));
  auto *real = new SgFloatVal(1.0f, "");
  auto *imaginary = new SgFloatVal(2.0f, "");
  real->set_literal_type(precision);
  imaginary->set_literal_type(precision);
  auto *original = new SgComplexVal(nullptr, real, imaginary, precision);
  ROSE_ASSERT(real->get_parent() == original &&
              imaginary->get_parent() == original);
  original->set_literal_type(SgTypeComplex::createType(precision));
  SgExpression *expressions[] = {original, real, imaginary};
  for (SgExpression *expression : expressions) {
    SageInterface::setOneSourcePositionNull(expression);
    SageBuilder::initializeSemanticExpressionSourceProvenance(expression);
  }
  const std::unordered_map<const SgNode *, uint64_t> ids{
      {original, 1}, {real, 2}, {imaginary, 3}};
  NodeRecord record;
  record.id = 1;
  record.kind = "SgComplexVal";
  record.flags = parseJson(rawNodeFlagsJson(original));
  record.location = parseJson(rawLocationJson(original));
  record.properties = parseJson(rawNodeProperties(original, ids));
  record.edges = {{"real_value", 2, 0}, {"imaginary_value", 3, 0}};
  NodeRecord realRecord, imaginaryRecord;
  realRecord.id = 2;
  realRecord.kind = "SgFloatVal";
  realRecord.edges = {{"parent", 1, 0}};
  imaginaryRecord = realRecord;
  imaginaryRecord.id = 3;
  AstFileRecord ast;
  ast.nodes = {record, realRecord, imaginaryRecord};
  {
    auto duplicate = ast;
    duplicate.nodes.front().kind = "SgNonrealDecl";
    duplicate.nodes.push_back(duplicate.nodes.front());
    NodeMap empty;
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph(duplicate.nodes), empty);
    } catch (const std::runtime_error &error) {
      ROSE_ASSERT(std::string(error.what()) ==
                  "AST JSON duplicate construction record id 1");
      rejected = true;
    }
    ROSE_ASSERT(rejected && empty.empty());
  }
  const size_t complexes = SgComplexVal::numberOfNodes();
  const size_t floats = SgFloatVal::numberOfNodes();
  const size_t positions = Sg_File_Info::numberOfNodes();
  for (int repeat = 0; repeat != 100; ++repeat) {
    auto *restoredReal = new SgFloatVal(1.0f, "");
    auto *restoredImaginary = new SgFloatVal(2.0f, "");
    restoredReal->set_literal_type(precision);
    restoredImaginary->set_literal_type(precision);
    NodeMap nodes{{2, restoredReal}, {3, restoredImaginary}};
    rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    auto *value = isSgComplexVal(nodes.at(1));
    ROSE_ASSERT(value != nullptr && value->get_literal_type() != nullptr);
    ROSE_ASSERT(value != nullptr && value->get_precisionType() == precision);
    ROSE_ASSERT(value->get_real_value() == restoredReal);
    ROSE_ASSERT(value->get_imaginary_value() == restoredImaginary);
    ROSE_ASSERT(restoredReal->get_parent() == value);
    ROSE_ASSERT(restoredImaginary->get_parent() == value);
    SageInterface::deleteAST(value);
    ROSE_ASSERT(SgComplexVal::numberOfNodes() == complexes);
    ROSE_ASSERT(SgFloatVal::numberOfNodes() == floats);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    for (int mutation = 0; mutation != 10; ++mutation) {
      auto bad = ast;
      auto &properties = bad.nodes[0].properties;
      if (mutation == 0)
        properties.object.erase("precision_type");
      else if (mutation == 1)
        properties.object.erase("real_value");
      else if (mutation == 2)
        properties.object.erase("imaginary_value");
      else if (mutation == 3)
        bad.nodes[0].edges[0].target = 3;
      else if (mutation == 4) {
        properties.object.at("imaginary_value") = parseJson(R"({"node":2})");
        bad.nodes[0].edges[1].target = 2;
      } else if (mutation == 5)
        bad.nodes[1].edges[0].target = 99;
      else if (mutation == 6) {
        properties.object.at("real_value") = parseJson(R"({"node":99})");
        bad.nodes[0].edges[0].target = 99;
      } else if (mutation == 7)
        properties.object.at("real_value") = parseJson(R"({"node":-1})");
      else {
        if (mutation == 8)
          properties.object.erase("literal_spelling_form");
        else
          properties.object.at("literal_spelling_form") =
              JsonValue::number("0");
        properties.object.at("precision_type") = JsonValue::objectValue({});
      }
      auto childReal = std::make_unique<SgFloatVal>(1.0f, "");
      auto childImaginary = std::make_unique<SgFloatVal>(2.0f, "");
      NodeMap children{{2, childReal.get()}, {3, childImaginary.get()}};
      bool rejected = false;
      try {
        rebuildConstructorOnlyNodes(recordGraph(bad.nodes), children);
      } catch (const std::runtime_error &error) {
        if (mutation >= 8)
          ROSE_ASSERT(
              std::string(error.what()) ==
              (mutation == 8
                   ? "AST JSON object is missing key: literal_spelling_form"
                   : "AST JSON SgValueExp has an invalid "
                     "literal_spelling_form enum value"));
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(children.count(1) == 0);
      ROSE_ASSERT(childReal->get_parent() == nullptr);
      ROSE_ASSERT(childImaginary->get_parent() == nullptr);
      ROSE_ASSERT(SgComplexVal::numberOfNodes() == complexes);
      ROSE_ASSERT(SgFloatVal::numberOfNodes() == floats + 2);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
  }
  bool rejected = false;
  try {
    (void)createNodeFromRecord(record, nullptr);
  } catch (const std::runtime_error &) {
    rejected = true;
  }
  ROSE_ASSERT(rejected);
  ROSE_ASSERT(SgComplexVal::numberOfNodes() == complexes);
  SageInterface::deleteAST(original);
  SageBuilder::setSourcePositionClassificationMode(previousMode);
}

void requireOwnedComplexConstruction() {
  using namespace Rose::AstJson;
  const auto previousMode = SageBuilder::getSourcePositionClassificationMode();
  SageBuilder::setSourcePositionClassificationMode(
      SageBuilder::e_sourcePositionTransformation);
  auto *precision = SageBuilder::buildFloatType(SageBuilder::buildIntVal(8));
  auto *real = new SgFloatVal(1.0f, "");
  auto *imaginary = new SgFloatVal(2.0f, "");
  real->set_literal_type(precision);
  imaginary->set_literal_type(precision);
  auto *original = new SgComplexVal(nullptr, real, imaginary, precision);
  ROSE_ASSERT(real->get_parent() == original &&
              imaginary->get_parent() == original);
  original->set_literal_type(SgTypeComplex::createType(precision));
  SgExpression *expressions[] = {original, real, imaginary};
  for (SgExpression *expression : expressions) {
    SageInterface::setOneSourcePositionNull(expression);
    SageBuilder::initializeSemanticExpressionSourceProvenance(expression);
  }
  const auto record = parseJson(rawTypeOwnedExpressionRef(original, {}));
  auto unowned = std::make_unique<SgFloatVal>(3.0f, "");
  unowned->set_literal_type(precision);
  const NodeMap nodes{{42, real}, {43, unowned.get()}};
  const JsonValue mismatched_component = parseJson(rawTypeJson(
      SgTypeLabel::createType(SgName("rex_invalid_complex_component")), {}));
  const size_t complexes = SgComplexVal::numberOfNodes();
  const size_t complex_types = SgTypeComplex::numberOfNodes();
  const size_t floats = SgFloatVal::numberOfNodes();
  const size_t positions = Sg_File_Info::numberOfNodes();
  for (int repeat = 0; repeat != 100; ++repeat) {
    auto *restored = isSgComplexVal(expressionFromRef(record, nodes));
    ROSE_ASSERT(restored != nullptr);
    ROSE_ASSERT(restored->get_literal_type() != nullptr);
    ROSE_ASSERT(restored->get_precisionType() == precision);
    ROSE_ASSERT(restored->get_type() == original->get_type());
    ROSE_ASSERT(restored->get_real_value() != nullptr &&
                restored->get_real_value() != real &&
                restored->get_real_value()->get_parent() == restored);
    ROSE_ASSERT(restored->get_imaginary_value() != nullptr &&
                restored->get_imaginary_value() != imaginary &&
                restored->get_imaginary_value()->get_parent() == restored);
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgComplexVal::numberOfNodes() == complexes);
    ROSE_ASSERT(SgTypeComplex::numberOfNodes() == complex_types);
    ROSE_ASSERT(SgFloatVal::numberOfNodes() == floats);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    for (int mutation = 0; mutation != 12; ++mutation) {
      auto malformed = record;
      auto &properties = malformed.object.at("properties");
      if (mutation == 0)
        properties.object.erase("precision_type");
      else if (mutation == 1)
        properties.object.erase("real_value");
      else if (mutation == 2)
        properties.object.erase("imaginary_value");
      else if (mutation == 3)
        properties.object.at("precision_type") =
            parseJson(R"({"present":false})");
      else if (mutation == 4)
        properties.object.at("real_value") = parseJson(R"({"node":42})");
      else if (mutation == 5) {
        properties.object.at("real_value") = parseJson(R"({"node":43})");
        properties.object.at("imaginary_value") = parseJson(R"({"node":43})");
      } else if (mutation == 6)
        properties.object.erase("has_literal_semantic_type");
      else if (mutation == 7)
        properties.object.erase("type");
      else if (mutation == 8)
        properties.object.at("type") = properties.at("precision_type");
      else if (mutation == 9)
        properties.object.at("type").object.at("base") = mismatched_component;
      else {
        if (mutation == 10)
          properties.object.erase("literal_spelling_form");
        else
          properties.object.at("literal_spelling_form") =
              JsonValue::number("0");
        properties.object.at("precision_type") = JsonValue::objectValue({});
        malformed.object.at("original_expression") = JsonValue::objectValue({});
      }
      bool rejected = false;
      try {
        (void)expressionFromRef(malformed, nodes);
      } catch (const std::runtime_error &error) {
        if (mutation == 8 || mutation == 9) {
          ROSE_ASSERT(
              std::string(error.what()) ==
              "AST JSON complex literal type does not match its precision");
        }
        if (mutation >= 10)
          ROSE_ASSERT(
              std::string(error.what()) ==
              (mutation == 10
                   ? "AST JSON object is missing key: literal_spelling_form"
                   : "AST JSON SgValueExp has an invalid "
                     "literal_spelling_form enum value"));
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(real->get_parent() == original);
      ROSE_ASSERT(unowned->get_parent() == nullptr);
      ROSE_ASSERT(original->get_real_value() == real);
      ROSE_ASSERT(SgComplexVal::numberOfNodes() == complexes);
      ROSE_ASSERT(SgTypeComplex::numberOfNodes() == complex_types);
      ROSE_ASSERT(SgFloatVal::numberOfNodes() == floats);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
  }
  SageInterface::deleteAST(original);
  SageBuilder::setSourcePositionClassificationMode(previousMode);
}

void requireOwnedCastConstruction() {
  using namespace Rose::AstJson;
  const auto mode = SageBuilder::getSourcePositionClassificationMode();
  SageBuilder::setSourcePositionClassificationMode(
      SageBuilder::e_sourcePositionTransformation);
  auto *inner = SageBuilder::buildCastExp(SageBuilder::buildIntVal(7),
                                          SageBuilder::buildDoubleType());
  auto *original =
      SageBuilder::buildCastExp(inner, SageBuilder::buildLongDoubleType());
  const auto record = parseJson(rawTypeOwnedExpressionRef(original, {}));
  const size_t casts = SgCastExp::numberOfNodes();
  const size_t integers = SgIntVal::numberOfNodes();
  const size_t positions = Sg_File_Info::numberOfNodes();
  for (int repeat = 0; repeat != 100; ++repeat) {
    auto *restored = isSgCastExp(expressionFromRef(record, {}));
    ROSE_ASSERT(restored != nullptr &&
                restored->get_type() == original->get_type());
    auto *child = isSgCastExp(restored->get_operand_i());
    ROSE_ASSERT(child != nullptr && child->get_parent() == restored &&
                child->get_type() == inner->get_type());
    ROSE_ASSERT(isSgIntVal(child->get_operand_i())->get_value() == 7);
    restored->validate_semantic_conversion();
    child->validate_semantic_conversion();
    SageInterface::deleteAST(restored);
    for (int mutation = 0; mutation != 4; ++mutation) {
      auto malformed = record;
      auto &properties = malformed.object.at("properties");
      if (mutation == 0)
        properties.object.at("operand") = parseJson(R"({"node":1})");
      else if (mutation == 1)
        properties.object.erase("operand");
      else if (mutation == 2)
        properties.object.at("operand") = parseJson(R"({"node":0})");
      else
        properties.object.at("type") = parseJson(R"({"present":false})");
      bool rejected = false;
      try {
        (void)expressionFromRef(malformed, {{1, inner}});
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(inner->get_parent() == original &&
                  original->get_operand_i() == inner);
      ROSE_ASSERT(SgCastExp::numberOfNodes() == casts);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == integers);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    }
  }
  SageInterface::deleteAST(original);
  SageBuilder::setSourcePositionClassificationMode(mode);
}

void requireFortranNamelistConstruction() {
  using namespace Rose::AstJson;
  auto *file =
      SageBuilder::buildGeneratedSourceFile("rex_namelist_identity.f90");
  std::unique_ptr<SgProject, DeleteFixtureAst> original(file->get_project());
  auto *function = SageBuilder::buildProcedureHeaderStatement(
      SageBuilder::function_declaration_ownership::sourceLexical(),
      "rex_namelist_identity", SageBuilder::buildVoidType(),
      SageBuilder::buildFunctionParameterList_nfi(),
      SageBuilder::buildFunctionParameterList_nfi(),
      SgProcedureHeaderStatement::e_subroutine_subprogram_kind,
      SgProcedureHeaderStatement::e_fortran_procedure_source_form_header,
      file->get_globalScope());
  auto *scope = function->get_definition()->get_body();
  scope->setCaseInsensitive(true);
  auto *declaration = SageBuilder::buildVariableDeclaration(
      "rex_namelist_object", SageBuilder::buildIntType(), nullptr, scope);
  scope->append_statement(declaration);
  auto *name = declaration->get_variables().front();
  auto *reference = SageBuilder::buildVarRefExp(name);
  auto *group = new SgNameGroup("rex_group", {reference});
  SageInterface::setSourcePosition(group);
  {
    std::unique_ptr<SgVarRefExp, DeleteFixtureAst> borrowed(
        SageBuilder::buildVarRefExp(name));
    const auto groups = SgNameGroup::numberOfNodes();
    {
      RecordNodeConstruction construction;
      construction.borrow(borrowed.get());
      construction.make<SgNameGroup>("rex_rollback",
                                     SgVarRefExpPtrList{borrowed.get()});
    }
    ROSE_ASSERT(borrowed->get_parent() == nullptr &&
                SgNameGroup::numberOfNodes() == groups);
  }
  auto *statement = new SgNamelistStatement({group});
  SageInterface::setSourcePosition(statement);
  statement->set_firstNondefiningDeclaration(statement);
  statement->set_definingDeclaration(statement);
  SageInterface::appendStatement(statement, scope);
  auto *symbol = new SgNamelistSymbol({group});
  scope->insert_symbol(symbol->get_name(), symbol);
  std::unordered_map<const SgNode *, uint64_t> ids{
      {name, 1},      {statement, 2}, {group, 3},
      {reference, 5}, {scope, 8},     {declaration, 9}};
  auto record = [&](SgNode *node, uint64_t id) {
    NodeRecord result;
    result.id = id;
    result.kind = node->class_name();
    result.properties = parseJson(rawNodeProperties(node, ids));
    result.flags = parseJson(rawNodeFlagsJson(node));
    result.location = parseJson(rawLocationJson(node));
    return result;
  };
  std::vector<NodeRecord> records{record(name, 1),  record(statement, 2),
                                  record(group, 3), record(reference, 5),
                                  record(scope, 8), record(declaration, 9)};
  records[0].edges = {{"scope", 8}, {"parent", 9}, {"declptr", 9}};
  records[1].edges = {{"parent", 8}, {"scope", 8}, {"group_list", 3}};
  records[2].edges = {{"parent", 2}, {"objects", 5}};
  records[3].edges = {{"parent", 3}};
  records[4].edges = {{"statements", 9, 0}, {"statements", 2, 1}};
  records[5].edges = {{"parent", 8}, {"scope", 8}, {"variables", 1}};
  {
    auto *restored_function = SageBuilder::buildProcedureHeaderStatement(
        SageBuilder::function_declaration_ownership::sourceLexical(),
        "rex_namelist_restored", SageBuilder::buildVoidType(),
        SageBuilder::buildFunctionParameterList_nfi(),
        SageBuilder::buildFunctionParameterList_nfi(),
        SgProcedureHeaderStatement::e_subroutine_subprogram_kind,
        SgProcedureHeaderStatement::e_fortran_procedure_source_form_header,
        file->get_globalScope());
    auto *restored_scope = restored_function->get_definition()->get_body();
    restored_scope->setCaseInsensitive(true);
    auto *restored_declaration = SageBuilder::buildVariableDeclaration(
        "rex_namelist_object", name->get_type(), nullptr, restored_scope);
    restored_scope->append_statement(restored_declaration);
    auto *restored_name = restored_declaration->get_variables().front();
    auto *restored_reference = SageBuilder::buildVarRefExp(restored_name);
    NodeMap nodes{{1, restored_name},
                  {5, restored_reference},
                  {8, restored_scope},
                  {9, restored_declaration}};
    rebuildConstructorOnlyNodes(recordGraph(records), nodes);
    auto *restored_statement = nodeByIdAs<SgNamelistStatement>(nodes, 2);
    SageInterface::appendStatement(restored_statement, restored_scope);
    auto *restored_group = restored_statement->get_group_list().front();
    restored_group->validate_group();
    ROSE_ASSERT(restored_group->get_objects().front() == restored_reference);
    ROSE_ASSERT(restored_reference->get_symbol()->get_declaration() ==
                restored_name);
  }
  for (int mutation = 0; mutation != 9; ++mutation) {
    auto malformed = records;
    if (mutation == 0)
      malformed[2].properties.object["group_name"] = JsonValue::string("");
    else if (mutation == 1)
      malformed[2].edges.pop_back();
    else if (mutation == 2)
      malformed[2].edges.push_back({"objects", 5, 1});
    else if (mutation == 3)
      malformed[3].kind = "SgIntVal";
    else if (mutation == 4)
      malformed[3].edges = {{"parent", 2}};
    else if (mutation == 5)
      malformed[1].edges.push_back({"group_list", 3, 1});
    else if (mutation == 6)
      malformed[2].properties.object["name_list"] = JsonValue::arrayValue({});
    else if (mutation == 7)
      malformed[2].edges.back().index = 1;
    else
      malformed[2].properties.object["group_name"] =
          JsonValue::string(std::string("bad\0name", 8));
    for (bool borrowed : {false, true}) {
      NodeMap nodes =
          borrowed
              ? NodeMap{{1, name}, {5, reference}, {8, scope}, {9, declaration}}
              : NodeMap{};
      const auto before = nodes;
      const auto groups = SgNameGroup::numberOfNodes();
      const auto statements = SgNamelistStatement::numberOfNodes();
      const auto positions = Sg_File_Info::numberOfNodes();
      const auto revision = SgNode::get_globalAstModificationSequence();
      bool rejected = false;
      try {
        if (borrowed)
          rebuildConstructorOnlyNodes(recordGraph(malformed), nodes);
        else {
          std::unique_ptr<SgNode, DeleteFixtureAst> unexpected(
              reconstructSourceFile(recordGraph(malformed), nullptr));
        }
      } catch (const std::runtime_error &error) {
        const std::string message(error.what());
        rejected = mutation == 8
                       ? message == "AST JSON group_name contains embedded NUL"
                       : message.find("NAMELIST") != std::string::npos;
      }
      ROSE_ASSERT(rejected && nodes == before);
      ROSE_ASSERT(SgNameGroup::numberOfNodes() == groups &&
                  SgNamelistStatement::numberOfNodes() == statements &&
                  Sg_File_Info::numberOfNodes() == positions &&
                  SgNode::get_globalAstModificationSequence() == revision);
    }
  }
  auto *second_declaration = SageBuilder::buildVariableDeclaration(
      "rex_namelist_second", name->get_type(), nullptr, scope);
  scope->append_statement(second_declaration);
  auto *second_name = second_declaration->get_variables().front();
  auto *second_reference = SageBuilder::buildVarRefExp(second_name);
  auto *second_group = new SgNameGroup("rex_group", {second_reference});
  SageInterface::setSourcePosition(second_group);
  auto *second_statement = new SgNamelistStatement({second_group});
  SageInterface::setSourcePosition(second_statement);
  second_statement->set_firstNondefiningDeclaration(second_statement);
  second_statement->set_definingDeclaration(second_statement);
  SageInterface::appendStatement(second_statement, scope);
  symbol->append_declaration(second_group);
  auto *first_alias = new SgAliasSymbol(symbol, true, "rex_first_alias");
  first_alias->get_causal_nodes().push_back(statement);
  scope->insert_symbol(first_alias->get_name(), first_alias);
  auto *second_alias = new SgAliasSymbol(first_alias, true, "rex_second_alias");
  second_alias->get_causal_nodes().push_back(statement);
  scope->insert_symbol(second_alias->get_name(), second_alias);
  auto *write = new SgWriteStatement(symbol);
  SageInterface::setSourcePosition(write);
  auto *unit = SageBuilder::buildIntVal(6);
  auto *items = SageBuilder::buildExprListExp();
  write->set_unit(unit);
  unit->set_parent(write);
  write->set_io_stmt_list(items);
  items->set_parent(write);
  SageInterface::appendStatement(write, scope);
  {
    std::unique_ptr<SgNode, DeleteFixtureAst> copied(
        SageInterface::deepCopySemantic(scope));
    auto *body = isSgBasicBlock(copied.get());
    auto *copied_write = isSgWriteStatement(body->get_statements().back());
    auto *copied_symbol =
        SgNamelistSymbol::resolve(copied_write->get_namelist());
    auto *copied_statement = isSgNamelistStatement(body->get_statements()[1]);
    auto *copied_name = isSgVariableDeclaration(body->get_statements().front())
                            ->get_variables()
                            .front();
    auto *copied_group = copied_statement->get_group_list().front();
    auto *copied_reference = copied_group->get_objects().front();
    copied_group->validate_group();
    ROSE_ASSERT(copied_group != group && copied_reference != reference &&
                copied_name != name &&
                copied_reference->get_symbol()->get_declaration() ==
                    copied_name);
    ROSE_ASSERT(copied_symbol != symbol && copied_symbol->get_scope() == body);
    ROSE_ASSERT(copied_symbol->get_declarations().front() ==
                copied_statement->get_group_list().front());
    ROSE_ASSERT(copied_symbol->get_declarations().size() == 2);
    auto *copied_first =
        body->lookup_alias_symbol("rex_first_alias", copied_symbol);
    auto *copied_second =
        body->lookup_alias_symbol("rex_second_alias", copied_symbol);
    ROSE_ASSERT(copied_first != nullptr && copied_second != nullptr &&
                copied_first != first_alias && copied_second != second_alias &&
                copied_second->get_alias() == copied_first &&
                copied_first->get_alias() == copied_symbol);
    ROSE_ASSERT(copied_symbol->get_declarations().back() ==
                isSgNamelistStatement(body->get_statements()[3])
                    ->get_group_list()
                    .front());
  }
  ids.emplace(write, 10);
  ids.emplace(unit, 11);
  ids.emplace(items, 12);
  ids.emplace(second_statement, 13);
  ids.emplace(second_group, 14);
  ids.emplace(second_reference, 15);
  ids.emplace(second_name, 16);
  ids.emplace(second_declaration, 17);
  records[4].properties = parseJson(rawNodeProperties(scope, ids));
  records[4].edges.push_back({"statements", 17, 2});
  records[4].edges.push_back({"statements", 13, 3});
  records[4].edges.push_back({"statements", 10, 4});
  records.push_back(record(write, 10));
  records.back().edges = {{"parent", 8}, {"unit", 11}, {"io_stmt_list", 12}};
  records.push_back(record(unit, 11));
  records.back().edges = {{"parent", 10}};
  records.push_back(record(items, 12));
  records.back().edges = {{"parent", 10}};
  records.push_back(record(second_statement, 13));
  records.back().edges = {{"parent", 8}, {"scope", 8}, {"group_list", 14}};
  records.push_back(record(second_group, 14));
  records.back().edges = {{"parent", 13}, {"objects", 15}};
  records.push_back(record(second_reference, 15));
  records.back().edges = {{"parent", 14}};
  records.push_back(record(second_name, 16));
  records.back().edges = {{"scope", 8}, {"parent", 17}, {"declptr", 17}};
  records.push_back(record(second_declaration, 17));
  records.back().edges = {{"parent", 8}, {"scope", 8}, {"variables", 16}};
  const NodeMap borrowed_nodes{{1, name},
                               {2, statement},
                               {3, group},
                               {5, reference},
                               {8, scope},
                               {9, declaration},
                               {11, unit},
                               {12, items},
                               {13, second_statement},
                               {14, second_group},
                               {15, second_reference},
                               {16, second_name},
                               {17, second_declaration}};
  {
    auto nodes = borrowed_nodes;
    const auto aliases = SgAliasSymbol::numberOfNodes();
    rebuildConstructorOnlyNodes(recordGraph(records), nodes);
    std::unique_ptr<SgNode, DeleteFixtureAst> restored(nodeById(nodes, 10));
    ROSE_ASSERT(isSgWriteStatement(restored.get())->get_namelist() == symbol);
    ROSE_ASSERT(scope->lookup_alias_symbol("rex_first_alias", symbol) ==
                    first_alias &&
                scope->lookup_alias_symbol("rex_second_alias", symbol) ==
                    second_alias &&
                SgAliasSymbol::numberOfNodes() == aliases);
  }
  for (int mutation = 0; mutation != 18; ++mutation) {
    auto malformed = records;
    auto &binding = malformed[6].properties.object.at("namelist");
    if (mutation == 0)
      malformed[6].properties.object.erase("namelist");
    else if (mutation == 1)
      binding = JsonValue::string("rex_group");
    else if (mutation == 2)
      binding.object.at("symbol").object.at("symbol_kind") =
          JsonValue::string("SgVariableSymbol");
    else if (mutation == 3)
      binding.object.at("symbol").object.at("symbol_declaration") =
          JsonValue::number("1");
    else if (mutation == 4)
      binding.object.at("binding_scope") = JsonValue::number("0");
    else if (mutation == 5)
      binding.object.at("binding_name") = JsonValue::string("other_group");
    else if (mutation == 6)
      malformed[6].edges.push_back({"format", 11});
    else if (mutation >= 12) {
      auto &entries = malformed[4].properties.object.at("symbol_table").array;
      JsonValue *first = nullptr, *second = nullptr;
      for (auto &entry : entries) {
        if (entry.requiredString("entry_name") == "rex_first_alias")
          first = &entry;
        if (entry.requiredString("entry_name") == "rex_second_alias")
          second = &entry;
      }
      ROSE_ASSERT(first != nullptr && second != nullptr);
      auto &target = second->object.at("alias_target_binding");
      if (mutation == 12)
        target.object.at("binding_scope") = JsonValue::number("0");
      else if (mutation == 13)
        target.object.at("binding_name") = JsonValue::string("missing_alias");
      else if (mutation == 14) {
        target.object.at("binding_name") =
            JsonValue::string("rex_second_alias");
        target.object.at("symbol") = second->at("symbol");
      } else if (mutation == 15) {
        auto back = target;
        back.object.at("binding_name") = JsonValue::string("rex_second_alias");
        back.object.at("symbol") = second->at("symbol");
        first->object.erase("alias_target");
        first->object.emplace("alias_target_binding", std::move(back));
      } else if (mutation == 16) {
        second->object.erase("alias_target_binding");
        second->object.emplace("alias_target", first->at("symbol"));
      } else {
        second->object.emplace("alias_target", first->at("symbol"));
      }
    } else
      for (auto &entry :
           malformed[4].properties.object.at("symbol_table").array)
        if (entry.requiredString("symbol_kind") == "SgNamelistSymbol") {
          auto &declarations = entry.object.at("namelist_declarations").array;
          if (mutation == 7)
            declarations.push_back(JsonValue::number("3"));
          else if (mutation == 8)
            declarations.clear();
          else if (mutation == 9)
            declarations.front() = JsonValue::number("1");
          else if (mutation == 10)
            declarations.pop_back();
          else {
            auto duplicate = entry;
            duplicate.object.at("entry_name") = JsonValue::string("REX_GROUP");
            declarations.pop_back();
            duplicate.object.at("namelist_declarations")
                .array.erase(
                    duplicate.object.at("namelist_declarations").array.begin());
            duplicate.object.at("symbol").object.at("symbol_declaration") =
                JsonValue::number("14");
            malformed[4]
                .properties.object.at("symbol_table")
                .array.push_back(std::move(duplicate));
            break;
          }
        }
    for (bool borrowed : {false, true}) {
      auto nodes = borrowed ? borrowed_nodes : NodeMap{};
      const auto before = nodes;
      const auto symbols = SgNamelistSymbol::numberOfNodes();
      const auto aliases = SgAliasSymbol::numberOfNodes();
      const auto writes = SgWriteStatement::numberOfNodes();
      const auto positions = Sg_File_Info::numberOfNodes();
      const auto revision = SgNode::get_globalAstModificationSequence();
      bool rejected = false;
      try {
        if (borrowed)
          rebuildConstructorOnlyNodes(recordGraph(malformed), nodes);
        else {
          std::unique_ptr<SgNode, DeleteFixtureAst> unexpected(
              reconstructSourceFile(recordGraph(malformed), nullptr));
        }
      } catch (const std::runtime_error &error) {
        const std::string message(error.what());
        if (mutation == 0)
          rejected = message == "AST JSON object is missing key: namelist";
        else if (mutation == 1)
          rejected =
              message ==
              "AST JSON value is not an object while reading binding_scope";
        else if (mutation >= 12)
          rejected = message.find("alias") != std::string::npos;
        else
          rejected = message.find("NAMELIST") != std::string::npos;
      }
      ROSE_ASSERT(rejected && nodes == before);
      ROSE_ASSERT(SgNamelistSymbol::numberOfNodes() == symbols &&
                  SgAliasSymbol::numberOfNodes() == aliases &&
                  SgWriteStatement::numberOfNodes() == writes &&
                  Sg_File_Info::numberOfNodes() == positions &&
                  SgNode::get_globalAstModificationSequence() == revision);
    }
  }
  ROSE_ASSERT(SageInterface::set_name(name, "rex_namelist_renamed") == 1);
  ROSE_ASSERT(reference->get_symbol()->get_name() == "rex_namelist_renamed");
  group->validate_group();
  file->set_outputLanguage(SgFile::e_Fortran_language);
  file->set_outputFormat(SgFile::e_free_form_output_format);
  const auto emitted = statement->unparseToString();
  ROSE_ASSERT(emitted.find("rex_namelist_renamed") != std::string::npos &&
              emitted.find("rex_namelist_object") == std::string::npos);
}

void requireFortranDataConstruction() {
  using namespace Rose::AstJson;
  auto *type = SageBuilder::buildIntType();
  auto *repeat = SageBuilder::buildIntVal(2);
  repeat->set_fortran_integer_constant_value(2);
  repeat->set_fortran_integer_constant_value_is_available(true);
  auto *first = new SgDataStatementValue(SageBuilder::buildIntVal(2), repeat);
  auto *second = new SgDataStatementValue(SageBuilder::buildIntVal(1), nullptr);
  auto *initializer = new SgFortranDataInitializer({first, second}, type);
  SageInterface::setSourcePosition(initializer);
  auto *scope = SageBuilder::buildBasicBlock();
  std::unique_ptr<SgNode, DeleteFixtureAst> original(scope);
  auto *declaration = SageBuilder::buildVariableDeclaration("rex_data", type,
                                                            initializer, scope);
  scope->append_statement(declaration);
  auto *owner = declaration->get_variables().front();
  initializer->validate_initializer();
  ROSE_ASSERT(initializer->get_parent() == owner);
  {
    std::unique_ptr<SgNode, DeleteFixtureAst> copied(
        SageInterface::deepCopy(scope));
    auto *copied_scope = isSgBasicBlock(copied.get());
    auto *copy = isSgVariableDeclaration(copied_scope->get_statements().front())
                     ->get_variables()
                     .front();
    auto *data = isSgFortranDataInitializer(copy->get_initializer());
    data->validate_initializer();
    ROSE_ASSERT(data != initializer && data->get_type() == copy->get_type());
    ROSE_ASSERT(data->get_values().size() == 2);
    ROSE_ASSERT(data->get_values()[0] != first &&
                data->get_values()[1] != second);
    ROSE_ASSERT(data->get_values()[0]->get_repeat_expression() != repeat);
    ROSE_ASSERT(data->get_values()[0]
                    ->get_repeat_expression()
                    ->get_fortran_integer_constant_value() == 2);
    ROSE_ASSERT(data->get_values()[1]->get_repeat_expression() == nullptr);
    ROSE_ASSERT(first->get_parent() == initializer &&
                repeat->get_parent() == first);
  }
  const std::unordered_map<const SgNode *, uint64_t> ids{
      {owner, 1},
      {initializer, 2},
      {first, 3},
      {second, 4},
      {first->get_constant_expression(), 5},
      {repeat, 6},
      {second->get_constant_expression(), 7},
      {scope, 8},
      {declaration, 9}};
  auto record = [&](SgNode *node, uint64_t id) {
    NodeRecord result;
    result.id = id;
    result.kind = node->class_name();
    result.properties = parseJson(rawNodeProperties(node, ids));
    result.flags = parseJson(rawNodeFlagsJson(node));
    result.location = parseJson(rawLocationJson(node));
    return result;
  };
  std::vector<NodeRecord> records{record(owner, 1),
                                  record(initializer, 2),
                                  record(first, 3),
                                  record(second, 4),
                                  record(first->get_constant_expression(), 5),
                                  record(repeat, 6),
                                  record(second->get_constant_expression(), 7),
                                  record(scope, 8),
                                  record(declaration, 9)};
  records[0].edges = {{"initptr", 2, 0}, {"scope", 8, 0}, {"parent", 9, 0}};
  records[1].edges = {{"parent", 1, 0}, {"values", 3, 0}, {"values", 4, 1}};
  records[2].edges = {{"parent", 2, 0},
                      {"constant_expression", 5, 0},
                      {"repeat_expression", 6, 0}};
  records[3].edges = {{"parent", 2, 0}, {"constant_expression", 7, 0}};
  records[4].edges = {{"parent", 3, 0}};
  records[5].edges = {{"parent", 3, 0}};
  records[6].edges = {{"parent", 4, 0}};
  records[7].edges = {{"statements", 9, 0}};
  records[8].edges = {{"parent", 8, 0}, {"scope", 8, 0}, {"variables", 1, 0}};
  {
    auto *restoredScope = SageBuilder::buildBasicBlock();
    std::unique_ptr<SgNode, DeleteFixtureAst> restored(restoredScope);
    auto *restoredDeclaration = SageBuilder::buildVariableDeclaration(
        "rex_data", type, nullptr, restoredScope);
    restoredScope->append_statement(restoredDeclaration);
    auto *restoredOwner = restoredDeclaration->get_variables().front();
    auto *restoredRepeat =
        isSgIntVal(createNodeFromRecord(records[5], nullptr));
    ROSE_ASSERT(restoredRepeat != nullptr);
    ROSE_ASSERT(
        restoredRepeat->get_fortran_integer_constant_value_is_available());
    ROSE_ASSERT(restoredRepeat->get_fortran_integer_constant_value() == 2);
    NodeMap nodes{{1, restoredOwner},  {5, SageBuilder::buildIntVal(2)},
                  {6, restoredRepeat}, {7, SageBuilder::buildIntVal(1)},
                  {8, restoredScope},  {9, restoredDeclaration}};
    rebuildConstructorOnlyNodes(recordGraph(records), nodes);
    auto *data = nodeByIdAs<SgFortranDataInitializer>(nodes, 2);
    restoredOwner->set_initializer(data);
    data->validate_initializer();
    ROSE_ASSERT(data->get_type() == restoredOwner->get_type());
    ROSE_ASSERT(data->get_values().size() == 2);
    ROSE_ASSERT(data->get_values()[0]->get_repeat_expression() ==
                restoredRepeat);
    ROSE_ASSERT(data->get_values()[1]->get_repeat_expression() == nullptr);
    ROSE_ASSERT(isSgIntVal(data->get_values()[1]->get_constant_expression())
                    ->get_value() == 1);
  }
  const auto floatType =
      parseJson(rawTypeJson(SageBuilder::buildFloatType(), {}));
  const auto integerTypes = SgTypeInt::numberOfNodes();
  const auto floatTypes = SgTypeFloat::numberOfNodes();
  const auto initializers = SgFortranDataInitializer::numberOfNodes();
  const auto values = SgDataStatementValue::numberOfNodes();
  const auto integers = SgIntVal::numberOfNodes();
  const auto names = SgInitializedName::numberOfNodes();
  const auto positions = Sg_File_Info::numberOfNodes();
  for (int mutation = 0; mutation < 9; ++mutation) {
    auto malformed = records;
    const char *diagnostic = nullptr;
    switch (mutation) {
    case 0:
      malformed[1].edges.pop_back();
      malformed[1].edges.pop_back();
      diagnostic = "AST JSON DATA has an empty required list";
      break;
    case 1:
      malformed[1].edges.back().target = 3;
      diagnostic = "AST JSON DATA has invalid typed list children";
      break;
    case 2:
      malformed[5]
          .properties.object["fortran_integer_constant_value_is_available"] =
          JsonValue::boolean(false);
      diagnostic = "AST JSON DATA repeat has no valid folded integer";
      break;
    case 3:
      malformed[5].properties.object["fortran_integer_constant_value"] =
          parseJson("-1");
      diagnostic = "AST JSON DATA repeat has no valid folded integer";
      break;
    case 4:
      malformed[6].edges.front().target = 3;
      diagnostic = "AST JSON DATA child has conflicting ownership";
      break;
    case 5:
      malformed[1].properties.object["type"] = floatType;
      diagnostic = "AST JSON DATA initializer has no exact destination type";
      break;
    case 6:
      malformed[6].kind = "SgExprListExp";
      diagnostic = "AST JSON DATA value cannot use an expression list operand";
      break;
    case 7:
      malformed[5].kind = "SgExprListExp";
      diagnostic = "AST JSON DATA value cannot use an expression list operand";
      break;
    case 8:
      malformed[1].properties.object.erase("is_braced_initialized");
      diagnostic = "AST JSON object is missing key: is_braced_initialized";
      break;
    }
    NodeMap nodes;
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph(malformed), nodes);
    } catch (const std::runtime_error &error) {
      ROSE_ASSERT(std::string(error.what()) == diagnostic);
      rejected = true;
    }
    ROSE_ASSERT(rejected && nodes.empty());
    ROSE_ASSERT(SgFortranDataInitializer::numberOfNodes() == initializers);
    ROSE_ASSERT(SgDataStatementValue::numberOfNodes() == values);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == integers);
    ROSE_ASSERT(SgInitializedName::numberOfNodes() == names);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    ROSE_ASSERT(SgTypeInt::numberOfNodes() == integerTypes);
    ROSE_ASSERT(SgTypeFloat::numberOfNodes() == floatTypes);
    ROSE_ASSERT(initializer->get_parent() == owner &&
                first->get_parent() == initializer);
    ROSE_ASSERT(repeat->get_parent() == first);
  }
}

void requireFortranImplicitRangeConstruction() {
  using namespace Rose::AstJson;
  using Range = SgFortranImplicitRange;
  using Statement = SgImplicitStatement;
  auto type = std::make_unique<SgTypeInt>();
  type->set_fortran_source_syntax(true);
  auto *selector = SageBuilder::buildIntVal(4);
  selector->set_fortran_integer_constant_value(4);
  selector->set_fortran_integer_constant_value_is_available(true);
  selector->set_parent(type.get());
  type->set_type_kind(selector);
  auto *singleton =
      new Range('A', std::nullopt, type.get(), Range::e_intrinsic, nullptr);
  auto *explicit_range =
      new Range('b', 'b', type.get(), Range::e_intrinsic, nullptr);
  std::unique_ptr<SgNode, DeleteFixtureAst> original_scope(
      SageBuilder::buildBasicBlock());
  auto *original = new Statement(Statement::e_has_implicit_spec_list,
                                 {singleton, explicit_range});
  isSgBasicBlock(original_scope.get())->append_statement(original);
  for (SgNode *node :
       {static_cast<SgNode *>(original), static_cast<SgNode *>(singleton),
        static_cast<SgNode *>(explicit_range)})
    SageInterface::setSourcePosition(isSgLocatedNode(node));
  auto record = [](SgNode *node, uint64_t id) {
    NodeRecord result;
    result.id = id;
    result.kind = node->class_name();
    result.properties = parseJson(rawNodeProperties(node, {}));
    result.flags = parseJson(rawNodeFlagsJson(node));
    result.location = parseJson(rawLocationJson(node));
    return result;
  };
  NodeRecord statement = record(original, 1);
  statement.edges = {{"ranges", 2, 0}, {"ranges", 3, 1}};
  NodeRecord first = record(singleton, 2);
  first.edges = {{"parent", 1, 0}};
  NodeRecord second = record(explicit_range, 3);
  second.edges = {{"parent", 1, 0}};
  ROSE_ASSERT(first.properties.at("last_letter").kind == JsonValue::Kind::Null);
  ROSE_ASSERT(second.properties.requiredInt("last_letter") == 'b');
  ROSE_ASSERT(first.properties.at("type").requiredInt("source_type_identity") ==
              second.properties.at("type").requiredInt("source_type_identity"));
  ROSE_ASSERT(statement.properties.find("implicit_none") == nullptr);
  ROSE_ASSERT(statement.properties.find("decl_attributes") == nullptr);

  const size_t copy_statements = Statement::numberOfNodes();
  const size_t copy_blocks = SgBasicBlock::numberOfNodes();
  const size_t copy_ranges = Range::numberOfNodes();
  const size_t copy_types = SgTypeInt::numberOfNodes();
  const size_t copy_selectors = SgIntVal::numberOfNodes();
  {
    std::unique_ptr<SgNode, DeleteFixtureAst> copied(
        SageInterface::deepCopy(original_scope.get()));
    auto *block = isSgBasicBlock(copied.get());
    ROSE_ASSERT(block != nullptr && block->get_statements().size() == 1);
    auto *copy = isSgImplicitStatement(block->get_statements().front());
    ROSE_ASSERT(copy != nullptr && copy->get_ranges().size() == 2);
    copy->validate_implicit_statement();
    ROSE_ASSERT(copy->get_ranges()[0] != singleton);
    ROSE_ASSERT(copy->get_ranges()[1] != explicit_range);
    ROSE_ASSERT(copy->get_ranges()[0]->get_first_letter() == 'A');
    ROSE_ASSERT(!copy->get_ranges()[0]->get_last_letter());
    ROSE_ASSERT(copy->get_ranges()[1]->get_last_letter() == 'b');
    ROSE_ASSERT(copy->get_ranges()[0]->get_type() == type.get());
    ROSE_ASSERT(copy->get_ranges()[1]->get_type() == type.get());
    ROSE_ASSERT(Statement::numberOfNodes() == copy_statements + 1);
    ROSE_ASSERT(SgBasicBlock::numberOfNodes() == copy_blocks + 1);
    ROSE_ASSERT(Range::numberOfNodes() == copy_ranges + 2);
    ROSE_ASSERT(SgTypeInt::numberOfNodes() == copy_types);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == copy_selectors);
  }
  ROSE_ASSERT(Statement::numberOfNodes() == copy_statements);
  ROSE_ASSERT(SgBasicBlock::numberOfNodes() == copy_blocks);
  ROSE_ASSERT(Range::numberOfNodes() == copy_ranges);
  ROSE_ASSERT(SgTypeInt::numberOfNodes() == copy_types);
  ROSE_ASSERT(SgIntVal::numberOfNodes() == copy_selectors);
  {
    NodeMap nodes;
    rebuildConstructorOnlyNodes(recordGraph({statement, second, first}), nodes);
    auto *restored = nodeByIdAs<Statement>(nodes, 1);
    restored->validate_implicit_statement();
    ROSE_ASSERT(restored->get_ranges().size() == 2);
    ROSE_ASSERT(restored->get_ranges()[0]->get_first_letter() == 'A');
    ROSE_ASSERT(!restored->get_ranges()[0]->get_last_letter());
    ROSE_ASSERT(restored->get_ranges()[1]->get_last_letter() == 'b');
    std::set<SgType *> restored_types;
    for (Range *range : restored->get_ranges()) {
      ROSE_ASSERT(range->get_type() != type.get());
      ROSE_ASSERT(isSgTypeInt(range->get_type()) != nullptr);
      ROSE_ASSERT(range->get_type()->get_fortran_source_syntax());
      ROSE_ASSERT(range->get_type()->get_type_kind() != selector);
      ROSE_ASSERT(range->get_type()->get_type_kind()->get_parent() ==
                  range->get_type());
      restored_types.insert(range->get_type());
    }
    ROSE_ASSERT(restored_types.size() == 1);
    SageInterface::deleteAST(restored);
    for (SgType *restored_type : restored_types)
      delete restored_type;
  }
  {
    auto distinct = std::make_unique<SgTypeInt>(*type);
    ROSE_ASSERT(distinct.get() != type.get());
    ROSE_ASSERT(distinct->get_ast_json_type_identity() == 0);
    ROSE_ASSERT(distinct->get_type_kind() != selector);
    ROSE_ASSERT(distinct->get_type_kind()->get_parent() == distinct.get());
    const uint64_t identity = sourceTypeJsonIdentity(distinct.get());
    ROSE_ASSERT(identity != sourceTypeJsonIdentity(type.get()));
    JsonValue different = first.properties.at("type");
    different.object["source_type_identity"] =
        parseJson(std::to_string(identity));
    FullTypeDeserializationIdentityGuard identities;
    std::unique_ptr<SgType> first_type(
        typeFromJson(first.properties.at("type"), {}));
    std::unique_ptr<SgType> second_type(typeFromJson(different, {}));
    ROSE_ASSERT(first_type.get() != second_type.get());
    ROSE_ASSERT(first_type->get_type_kind() != second_type->get_type_kind());
    ROSE_ASSERT(typeFromJson(first.properties.at("type"), {}) ==
                first_type.get());
    const size_t types = SgTypeInt::numberOfNodes();
    const size_t values = SgIntVal::numberOfNodes();
    const size_t positions = Sg_File_Info::numberOfNodes();
    auto contradictory = first.properties.at("type");
    contradictory.object.at("has_type_kind_star") = parseJson("true");
    bool rejected = false;
    try {
      (void)typeFromJson(contradictory, {});
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected);
    ROSE_ASSERT(SgTypeInt::numberOfNodes() == types);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    ROSE_ASSERT(typeFromJson(first.properties.at("type"), {}) ==
                first_type.get());
  }
  {
    FullTypeDeserializationIdentityGuard identities;
    auto borrowed = first.properties.at("type");
    borrowed.object["type_kind"] = parseJson(R"({"node":4})");
    const size_t types = SgTypeInt::numberOfNodes();
    const size_t values = SgIntVal::numberOfNodes();
    bool rejected = false;
    try {
      (void)typeFromJson(borrowed, {{4, selector}});
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected);
    ROSE_ASSERT(selector->get_parent() == type.get());
    ROSE_ASSERT(SgTypeInt::numberOfNodes() == types);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
    std::unique_ptr<SgType> restored(
        typeFromJson(first.properties.at("type"), {}));
    ROSE_ASSERT(restored->get_type_kind() != selector);
    ROSE_ASSERT(restored->get_type_kind()->get_parent() == restored.get());
  }

  statement.edges.resize(1);
  std::unique_ptr<SgNode, DeleteFixtureAst> symbol_owner(
      SageBuilder::buildBasicBlock());
  auto *scope = isSgBasicBlock(symbol_owner.get());
  auto *variable = SageBuilder::buildVariableDeclaration(
      "rex_implicit_wrong_symbol", SageBuilder::buildIntType(), nullptr, scope);
  scope->append_statement(variable);
  auto *name = variable->get_variables().front();
  auto *symbol = scope->lookup_variable_symbol(name->get_name());
  ROSE_ASSERT(symbol != nullptr);
  const NodeMap symbol_nodes{{4, scope}, {5, name}};
  const std::unordered_map<const SgNode *, uint64_t> symbol_ids{{scope, 4},
                                                                {name, 5}};
  {
    FullTypeDeserializationIdentityGuard identities;
    std::unique_ptr<Range> restored(constructFortranImplicitRange(
        'A', std::nullopt, Range::e_intrinsic, first.properties, {}));
    std::unique_ptr<SgType> restored_type(restored->get_type());
    auto malformed = second.properties;
    malformed.object["source_derived_type_symbol"] =
        parseJson(rawExactBoundSymbolRef(symbol, symbol_ids));
    const size_t types = SgTypeInt::numberOfNodes();
    const size_t ranges = Range::numberOfNodes();
    const size_t values = SgIntVal::numberOfNodes();
    const size_t positions = Sg_File_Info::numberOfNodes();
    bool rejected = false;
    try {
      (void)constructFortranImplicitRange('b', 'b', Range::e_intrinsic,
                                          malformed, symbol_nodes);
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected && restored->get_type() == restored_type.get());
    restored->validate_range();
    ROSE_ASSERT(SgTypeInt::numberOfNodes() == types);
    ROSE_ASSERT(Range::numberOfNodes() == ranges);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    std::unique_ptr<Range> later(constructFortranImplicitRange(
        'b', 'b', Range::e_intrinsic, second.properties, {}));
    ROSE_ASSERT(later->get_type() == restored_type.get());
  }
  const size_t statements = Statement::numberOfNodes();
  const size_t ranges = Range::numberOfNodes();
  const size_t types = SgTypeInt::numberOfNodes();
  const size_t positions = Sg_File_Info::numberOfNodes();
  for (int mutation = 0; mutation != 16; ++mutation) {
    auto malformed = first;
    auto owner = statement;
    if (mutation == 0)
      malformed.properties.object["first_letter"] = parseJson("256");
    else if (mutation == 1)
      malformed.properties.object["last_letter"] = parseJson("\"z\"");
    else if (mutation == 2) {
      malformed.properties.object["first_letter"] = parseJson("90");
      malformed.properties.object["last_letter"] = parseJson("97");
    } else if (mutation == 3)
      malformed.properties.object["type_spec"] = parseJson("99");
    else if (mutation == 4)
      malformed.properties.object["type"] = parseJson(R"({"present":false})");
    else if (mutation == 5)
      malformed.properties.object["source_derived_type_symbol"] =
          parseJson("7");
    else if (mutation == 6)
      malformed.properties.object["type_spec"] =
          parseJson(std::to_string(Range::e_type));
    else if (mutation == 7)
      malformed.edges.front().target = 2;
    else if (mutation == 8)
      owner.edges.push_back({"ranges", 2, 1});
    else if (mutation == 9)
      malformed.properties.object.erase("last_letter");
    else if (mutation == 10) {
      malformed.properties.object["type"].object["fortran_source_syntax"] =
          parseJson("false");
      malformed.properties.object["type"].object.erase("source_type_identity");
    } else if (mutation == 11)
      owner.properties.object["implicit_spec"] =
          parseJson(std::to_string(Statement::e_none));
    else if (mutation == 12)
      malformed.properties.object["source_derived_type_symbol"] =
          parseJson(rawExactBoundSymbolRef(symbol, symbol_ids));
    else if (mutation == 13)
      malformed.properties.object["type"].object.erase("source_type_identity");
    else
      malformed.properties.object["type"].object["source_type_identity"] =
          parseJson(mutation == 14 ? "0" : "null");
    NodeMap nodes = mutation == 12 ? symbol_nodes : NodeMap{};
    const size_t borrowed_nodes = nodes.size();
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph({owner, malformed}), nodes);
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected && nodes.size() == borrowed_nodes);
    ROSE_ASSERT(Statement::numberOfNodes() == statements);
    ROSE_ASSERT(Range::numberOfNodes() == ranges);
    ROSE_ASSERT(SgTypeInt::numberOfNodes() == types);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  {
    auto owner = statement;
    auto first_range = first;
    owner.edges = {{"ranges", 2, 0}, {"ranges", 3, 1}};
    first_range.properties.object["last_letter"] = parseJson("67");
    auto second_range = second;
    second_range.properties.object["last_letter"] = parseJson("100");
    const size_t values = SgIntVal::numberOfNodes();
    NodeMap nodes;
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(
          recordGraph({owner, first_range, second_range}), nodes);
    } catch (const std::runtime_error &error) {
      if (std::string(error.what()) !=
          "AST JSON implicit statement has overlapping letter ranges")
        throw;
      rejected = true;
    }
    ROSE_ASSERT(rejected && nodes.empty());
    ROSE_ASSERT(Statement::numberOfNodes() == statements);
    ROSE_ASSERT(Range::numberOfNodes() == ranges);
    ROSE_ASSERT(SgTypeInt::numberOfNodes() == types);
    ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    ROSE_ASSERT(singleton->get_parent() == original);
    ROSE_ASSERT(explicit_range->get_parent() == original);
    ROSE_ASSERT(singleton->get_type() == type.get());
    ROSE_ASSERT(selector->get_parent() == type.get());
  }
  {
    NodeMap nodes{{2, singleton}};
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph({statement, first}), nodes);
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected && nodes.size() == 1);
    ROSE_ASSERT(singleton->get_parent() == original);
    ROSE_ASSERT(Statement::numberOfNodes() == statements);
  }
  {
    auto owner = statement;
    owner.edges.push_back({"ranges", 3, 1});
    auto malformed = second;
    malformed.properties.object["type_spec"] =
        parseJson(std::to_string(Range::e_type));
    NodeMap nodes{{2, singleton}};
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph({owner, first, malformed}),
                                  nodes);
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected && nodes.size() == 1);
    ROSE_ASSERT(singleton->get_parent() == original);
    ROSE_ASSERT(singleton->get_type() == type.get());
    singleton->validate_range();
    ROSE_ASSERT(Statement::numberOfNodes() == statements);
    ROSE_ASSERT(Range::numberOfNodes() == ranges);
    ROSE_ASSERT(SgTypeInt::numberOfNodes() == types);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
  }
  {
    FullTypeDeserializationIdentityGuard identities;
    auto component = std::make_unique<SgTypeFloat>();
    component->set_fortran_source_syntax(true);
    auto complex = std::make_unique<SgTypeComplex>(component.get());
    complex->set_fortran_source_syntax(true);
    auto malformed = first;
    malformed.properties.object["type"] =
        parseJson(rawTypeJson(complex.get(), {}));
    malformed.properties.object["type_spec"] =
        parseJson(std::to_string(Range::e_type));
    const size_t floats = SgTypeFloat::numberOfNodes();
    const size_t complexes = SgTypeComplex::numberOfNodes();
    NodeMap nodes;
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph({statement, malformed}), nodes);
    } catch (const std::runtime_error &) {
      rejected = true;
    }
    ROSE_ASSERT(rejected && nodes.empty());
    ROSE_ASSERT(Statement::numberOfNodes() == statements);
    ROSE_ASSERT(Range::numberOfNodes() == ranges);
    ROSE_ASSERT(SgTypeFloat::numberOfNodes() == floats);
    ROSE_ASSERT(SgTypeComplex::numberOfNodes() == complexes);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    {
      std::unique_ptr<SgTypeComplex> restored(
          isSgTypeComplex(typeFromJson(malformed.properties.at("type"), {})));
      ROSE_ASSERT(restored != nullptr);
      std::unique_ptr<SgType> restored_component(restored->get_base_type());
      ROSE_ASSERT(restored_component.get() != component.get());
      ROSE_ASSERT(restored_component->get_fortran_source_syntax());
      restored.reset();
    }
    ROSE_ASSERT(SgTypeFloat::numberOfNodes() == floats);
    ROSE_ASSERT(SgTypeComplex::numberOfNodes() == complexes);
  }
  for (auto spec :
       {Statement::e_none, Statement::e_none_external, Statement::e_none_type,
        Statement::e_none_external_and_type}) {
    std::unique_ptr<SgNode, DeleteFixtureAst> source_scope(
        SageBuilder::buildBasicBlock());
    auto *source = new Statement(spec, {});
    isSgBasicBlock(source_scope.get())->append_statement(source);
    SageInterface::setSourcePosition(source);
    NodeMap nodes;
    rebuildConstructorOnlyNodes(recordGraph({record(source, 1)}), nodes);
    auto *restored = nodeByIdAs<Statement>(nodes, 1);
    ROSE_ASSERT(restored->get_implicit_spec() == spec);
    ROSE_ASSERT(restored->get_ranges().empty());
    SageInterface::deleteAST(restored);
  }
}

void requireOwnedTypeExpressionConstruction() {
  using namespace Rose::AstJson;
  const auto original_mode = SageBuilder::getSourcePositionClassificationMode();
  SageBuilder::setSourcePositionClassificationMode(
      SageBuilder::e_sourcePositionTransformation);
  auto scope = std::make_unique<SgGlobal>();
  auto declaration = std::make_unique<SgNonrealDecl>("rex_owned_type", nullptr);
  declaration->set_parent(scope.get());
  const NodeMap nodes{{1, declaration.get()}};
  auto *base = new SgNonrealType(declaration.get());
  base->set_parent(declaration.get());
  declaration->set_type(base);
  auto *pointer = SageBuilder::buildPointerType(base);
  auto *original = new SgTypeExpression(pointer);
  SageInterface::setOneSourcePositionNull(original);
  SageBuilder::initializeSemanticExpressionSourceProvenance(original);
  const auto record =
      parseJson(rawTypeOwnedExpressionRef(original, {{declaration.get(), 1}}));
  const size_t pointers = SgPointerType::numberOfNodes();
  const size_t expressions = SgTypeExpression::numberOfNodes();
  const size_t positions = Sg_File_Info::numberOfNodes();
  for (int repeat = 0; repeat != 100; ++repeat) {
    auto *restored = isSgTypeExpression(expressionFromRef(record, nodes));
    ROSE_ASSERT(restored != nullptr);
    ROSE_ASSERT(restored->get_represented_type() == pointer);
    SageInterface::deleteAST(restored);
    ROSE_ASSERT(SgTypeExpression::numberOfNodes() == expressions);
    ROSE_ASSERT(SgPointerType::numberOfNodes() == pointers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    for (int mutation = 0; mutation != 4; ++mutation) {
      auto malformed = record;
      auto &properties = malformed.object.at("properties");
      if (mutation == 0)
        properties.object.erase("represented_type");
      else if (mutation == 1)
        properties.object.at("represented_type") =
            parseJson(R"({"present":false})");
      else if (mutation == 2)
        properties.object.at("represented_type")
            .object.at("base")
            .object.at("declaration") = JsonValue::number("2");
      else
        properties.object.at("represented_type")
            .object.at("base")
            .object.erase("declaration");
      bool rejected = false;
      try {
        auto *unexpected = expressionFromRef(malformed, nodes);
        SageInterface::deleteAST(unexpected);
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgTypeExpression::numberOfNodes() == expressions);
      ROSE_ASSERT(SgPointerType::numberOfNodes() == pointers);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
      ROSE_ASSERT(declaration->get_type() == base);
      ROSE_ASSERT(base->get_ptr_to() == pointer);
    }
  }
  SageInterface::deleteAST(original);
  SageInterface::deleteAST(pointer,
                           SageInterface::DeleteAstMode::kRequireIsolated);
  ROSE_ASSERT(base->get_ptr_to() == nullptr);
  declaration->set_type(nullptr);
  base->set_parent(nullptr);
  delete base;
  SageBuilder::setSourcePositionClassificationMode(original_mode);
}

void requireThisSymbolBindings() {
  using namespace Rose::AstJson;
  auto scope = std::make_unique<SgDeclarationScope>();
  auto classDeclaration = std::make_unique<SgClassDeclaration>(
      SgName("rex_this_class"), SgClassDeclaration::e_class, nullptr, nullptr);
  auto nonrealDeclaration =
      std::make_unique<SgNonrealDecl>("rex_this_nonreal", nullptr);
  classDeclaration->set_firstNondefiningDeclaration(classDeclaration.get());
  classDeclaration->set_scope(scope.get());
  nonrealDeclaration->set_scope(scope.get());

  const auto check = [&](auto *declaration, auto *symbol, auto lookup,
                         const char *diagnostic) {
    const size_t classes = SgClassSymbol::numberOfNodes();
    const size_t templateClasses = SgTemplateClassSymbol::numberOfNodes();
    const size_t nonreals = SgNonrealSymbol::numberOfNodes();
    const auto requireRejected = [&](auto *input) {
      bool rejected = false;
      try {
        (void)lookup(input);
      } catch (const std::runtime_error &error) {
        if (std::string(error.what()).find(diagnostic) == std::string::npos)
          throw;
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgClassSymbol::numberOfNodes() == classes);
      ROSE_ASSERT(SgTemplateClassSymbol::numberOfNodes() == templateClasses);
      ROSE_ASSERT(SgNonrealSymbol::numberOfNodes() == nonreals);
    };
    for (int repeat = 0; repeat < 25; ++repeat) {
      requireRejected(declaration);
      requireRejected(static_cast<decltype(declaration)>(nullptr));
    }
    scope->insert_symbol(declaration->get_name(), symbol);
    for (int repeat = 0; repeat < 25; ++repeat)
      ROSE_ASSERT(lookup(declaration) == symbol);
    scope->remove_symbol(symbol);
    symbol->set_parent(nullptr);
    requireRejected(declaration);
  };
  auto classSymbol = std::make_unique<SgClassSymbol>(classDeclaration.get());
  check(classDeclaration.get(), classSymbol.get(), classSymbolForDeclaration,
        "class symbol reference has no exact restored symbol-table binding");
  auto nonrealSymbol =
      std::make_unique<SgNonrealSymbol>(nonrealDeclaration.get());
  check(nonrealDeclaration.get(), nonrealSymbol.get(),
        nonrealSymbolForDeclaration,
        "nonreal symbol reference has no exact restored symbol-table binding");
}

void requireThisConstruction(SgNonrealDecl *declaration) {
  using namespace Rose::AstJson;
  auto scope = std::make_unique<SgDeclarationScope>();
  SgDeclarationScope *previous_scope = declaration->get_declarationScope();
  declaration->set_scope(scope.get());
  auto symbol = std::make_unique<SgNonrealSymbol>(declaration);
  scope->insert_symbol(declaration->get_name(), symbol.get());
  SgNonrealType *base = declaration->get_type();
  auto *pointer = buildCachedJsonPointerType(base);
  auto *original = new SgThisExp(nullptr, symbol.get(), pointer);
  SageBuilder::initializeSemanticExpressionSourceProvenance(original);
  const std::unordered_map<const SgNode *, uint64_t> ids{{original, 1},
                                                         {declaration, 2}};
  NodeRecord record;
  record.id = 1;
  record.kind = "SgThisExp";
  record.flags = parseJson(rawNodeFlagsJson(original));
  record.location = parseJson(rawLocationJson(original));
  record.properties = parseJson(rawNodeProperties(original, ids));
  const auto owned =
      parseJson(rawTypeOwnedExpressionRef(original, {{declaration, 2}}));
  SageInterface::deleteAST(original);
  const auto wrongPointerType = parseJson(rawTypeJson(
      SageBuilder::buildPointerType(SageBuilder::buildIntType()), {}));
  const size_t expressions = SgThisExp::numberOfNodes();
  const size_t symbols = SgNonrealSymbol::numberOfNodes();
  for (int repeat = 0; repeat < 25; ++repeat) {
    NodeMap nodes{{2, declaration}};
    auto *restored_owned = isSgThisExp(expressionFromRef(owned, nodes));
    ROSE_ASSERT(restored_owned != nullptr &&
                restored_owned->get_nonreal_symbol() == symbol.get() &&
                restored_owned->get_class_symbol() == nullptr &&
                restored_owned->get_type() == pointer);
    SageInterface::deleteAST(restored_owned);
    AstFileRecord ast;
    ast.nodes = {record};
    rebuildConstructorOnlyNodes(recordGraph(ast.nodes), nodes);
    auto *restored = isSgThisExp(nodes.at(1));
    ROSE_ASSERT(restored != nullptr &&
                restored->get_nonreal_symbol() == symbol.get() &&
                restored->get_type() == pointer);
    SageInterface::deleteAST(restored);
    nodes.erase(1);
    for (int malformed = 0; malformed != 5; ++malformed) {
      auto bad = record.properties;
      std::string expected;
      if (malformed == 0) {
        bad.object.erase("type");
        expected = "missing key: type";
      } else if (malformed == 1) {
        bad.object.at("type") =
            parseJson(rawTypeJson(SageBuilder::buildIntType(), {}));
        expected = "result type is not an exact pointer type";
      } else if (malformed == 2) {
        bad.object.at("nonreal_symbol_declaration") = parseJson("0");
        expected = "must name exactly one class or nonreal symbol declaration";
      } else if (malformed == 3) {
        bad.object.at("nonreal_symbol_declaration") = parseJson("-1");
        expected = "must name exactly one class or nonreal symbol declaration";
      } else {
        bad.object.at("type") = wrongPointerType;
        expected = "pointer type does not match its symbol type";
      }
      bool rejected = false;
      try {
        std::unique_ptr<SgThisExp> unexpected(
            thisExpressionFromProperties(bad, nodes));
      } catch (const std::runtime_error &error) {
        if (std::string(error.what()).find(expected) == std::string::npos)
          throw;
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgThisExp::numberOfNodes() == expressions);
      ROSE_ASSERT(SgNonrealSymbol::numberOfNodes() == symbols);
    }
  }
  scope->remove_symbol(symbol.get());
  symbol->set_parent(nullptr);
  SageInterface::deleteAST(pointer,
                           SageInterface::DeleteAstMode::kRequireIsolated);
  ROSE_ASSERT(base->get_ptr_to() == nullptr);
  declaration->set_declarationScope(previous_scope);
}

void requireNonrealTypeOwnership() {
  using namespace Rose::AstJson;
  const size_t types = SgNonrealType::numberOfNodes();
  std::unique_ptr<SgNonrealDecl> declaration(
      new SgNonrealDecl("rex_parameter", nullptr));
  NodeMap nodes{{1, declaration.get()}};
  const JsonValue valid = parseJson(
      R"({"present":true,"kind":"SgNonrealType","fortran_source_syntax":false,
           "declaration":1})");
  for (int repeat = 0; repeat < 100; ++repeat) {
    JsonValue malformed = valid;
    const bool obsolete = repeat % 2 == 0;
    if (obsolete)
      malformed.object["autonomous_declaration"] = parseJson("false");
    else
      malformed.object.erase("declaration");
    bool rejected = false;
    try {
      (void)typeFromJson(malformed, nodes);
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what()) ==
                 (obsolete ? "AST JSON named type contains obsolete "
                             "autonomous_declaration"
                           : "AST JSON object is missing key: declaration");
    }
    ROSE_ASSERT(rejected && declaration->get_type() == nullptr);
    ROSE_ASSERT(SgNonrealType::numberOfNodes() == types);
  }
  bool missingTypeRejected = false;
  try {
    (void)typeFromJson(valid, nodes);
  } catch (const std::runtime_error &error) {
    missingTypeRejected =
        std::string(error.what())
            .find("conflicts with its exact declaration owner") !=
        std::string::npos;
  }
  ROSE_ASSERT(missingTypeRejected && declaration->get_type() == nullptr);
  ROSE_ASSERT(SgNonrealType::numberOfNodes() == types);
  auto *type = new SgNonrealType(declaration.get());
  type->set_parent(declaration.get());
  declaration->set_type(type);
  ROSE_ASSERT(type != nullptr && type->get_declaration() == declaration.get());
  ROSE_ASSERT(type->get_parent() == declaration.get());
  for (int repeat = 0; repeat < 100; ++repeat)
    ROSE_ASSERT(typeFromJson(valid, nodes) == type);
  const JsonValue integer_type =
      parseJson(rawTypeJson(SageBuilder::buildIntType(), {}));
  const auto declarations = SgNonrealDecl::numberOfNodes();
  const auto integers = SgTypeInt::numberOfNodes();
  const auto positions = Sg_File_Info::numberOfNodes();
  const auto revision = SgNode::get_globalAstModificationSequence();
  for (bool extra_projection : {false, true}) {
    JsonValue malformed = valid;
    malformed.object.emplace(
        "aliased_type",
        extra_projection ? integer_type : parseJson(R"({"present":false})"));
    bool rejected = false;
    try {
      (void)typeFromJson(malformed, nodes);
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what()) ==
                 "AST JSON SgNonrealType alias projection must be stored on "
                 "its declaration";
    }
    ROSE_ASSERT(rejected && declaration->get_type() == type &&
                type->get_aliased_type() == nullptr);
    ROSE_ASSERT(SgNonrealType::numberOfNodes() == types + 1);
    ROSE_ASSERT(SgNonrealDecl::numberOfNodes() == declarations);
    ROSE_ASSERT(SgTypeInt::numberOfNodes() == integers);
    ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
    ROSE_ASSERT(SgNode::get_globalAstModificationSequence() == revision);
  }
  requireThisConstruction(declaration.get());
  declaration->set_type(nullptr);
  type->set_parent(nullptr);
  delete type;
  ROSE_ASSERT(SgNonrealType::numberOfNodes() == types);
}

void requireNodeEditState() {
  using namespace Rose::AstJson;
  for (bool modified : {false, true}) {
    auto original = std::make_unique<SgFileList>();
    original->set_isModified(modified);
    NodeRecord record;
    record.kind = "SgFileList";
    record.flags = parseJson(rawNodeFlagsJson(original.get()));
    record.location = parseJson(rawLocationJson(original.get()));
    std::unique_ptr<SgNode> restored(createNodeFromRecord(record, nullptr));
    ROSE_ASSERT(restored->get_isModified() == modified);

    auto *literal = SageBuilder::buildIntVal(42);
    literal->set_isModified(modified);
    const JsonValue owned = parseJson(rawTypeOwnedExpressionRef(literal, {}));
    auto *expression = expressionFromRef(owned, {});
    ROSE_ASSERT(expression != nullptr &&
                expression->get_isModified() == modified);
    for (const char *flags :
         {"{}", R"({"is_modified":null})", R"({"is_modified":0})",
          R"({"is_modified":"false"})"}) {
      record.flags = parseJson(flags);
      bool rejected = false;
      try {
        (void)createNodeFromRecord(record, nullptr);
      } catch (const std::runtime_error &error) {
        const std::string message = error.what();
        rejected = message.find("is_modified") != std::string::npos ||
                   message.find("not a bool") != std::string::npos;
      }
      ROSE_ASSERT(rejected);
      JsonValue malformed = owned;
      malformed.object.at("flags") = record.flags;
      rejected = false;
      try {
        (void)expressionFromRef(malformed, {});
      } catch (const std::runtime_error &error) {
        const std::string message = error.what();
        rejected = message.find("is_modified") != std::string::npos ||
                   message.find("not a bool") != std::string::npos;
      }
      ROSE_ASSERT(rejected);
    }
    SageInterface::deleteAST(expression);
    SageInterface::deleteAST(literal);
  }
}

void requireInlineExpressionListFlags() {
  using namespace Rose::AstJson;
  for (bool flag : {false, true}) {
    auto *original = SageBuilder::buildExprListExp(SageBuilder::buildIntVal(7));
    original->get_expressions().front()->set_need_paren(true);
    for (SgExpression *node : {static_cast<SgExpression *>(original),
                               original->get_expressions().front()}) {
      node->attachPreprocessingInfo(
          new PreprocessingInfo(PreprocessingInfo::C_StyleComment,
                                "/* retained inline comment */",
                                "rex_ast_json_required_fields.cpp", 1, 1, 1,
                                PreprocessingInfo::before),
          PreprocessingInfo::before);
      node->setAttribute("rex_tool_annotation", new AstIntAttribute(73));
    }
    original->set_containsTransformation(flag);
    original->set_containsTransformationToSurroundingWhitespace(flag);
    original->set_source_range_ends_in_macro_expansion(flag);
    original->set_source_range_is_macro_expansion_fragment(flag);
    original->set_isModified(flag);
    JsonValue serialized = parseJson(rawTypeOwnedExprListExpJson(original, {}));
    auto *restored = exprListExpFromTypeJson(serialized, {});
    ROSE_ASSERT(restored != nullptr && restored != original);
    ROSE_ASSERT(restored->get_isModified() == flag);
    ROSE_ASSERT(restored->get_containsTransformation() == flag);
    ROSE_ASSERT(restored->get_containsTransformationToSurroundingWhitespace() ==
                flag);
    ROSE_ASSERT(restored->get_source_range_ends_in_macro_expansion() == flag);
    ROSE_ASSERT(restored->get_source_range_is_macro_expansion_fragment() ==
                flag);
    ROSE_ASSERT(restored->get_expressions().size() == 1);
    ROSE_ASSERT(restored->get_expressions().front()->get_parent() == restored);
    for (auto pair : {std::make_pair(static_cast<SgExpression *>(original),
                                     static_cast<SgExpression *>(restored)),
                      std::make_pair(original->get_expressions().front(),
                                     restored->get_expressions().front())}) {
      auto *comments = pair.second->getAttachedPreprocessingInfo();
      ROSE_ASSERT(pair.second->get_need_paren() ==
                  pair.first->get_need_paren());
      ROSE_ASSERT(comments != nullptr && comments->size() == 1);
      auto *comment = comments->front();
      ROSE_ASSERT(comment !=
                  pair.first->getAttachedPreprocessingInfo()->front());
      ROSE_ASSERT(comment->getAttachedOwner() == pair.second);
      ROSE_ASSERT(comment->getString() == "/* retained inline comment */");
      auto *annotation = dynamic_cast<AstIntAttribute *>(
          pair.second->getAttribute("rex_tool_annotation"));
      ROSE_ASSERT(annotation != nullptr && annotation->getValue() == 73);
      ROSE_ASSERT(annotation !=
                  pair.first->getAttribute("rex_tool_annotation"));
    }
    SageInterface::deleteAST(restored);
    const auto owned = parseJson(rawTypeOwnedExpressionRef(original, {}));
    for (bool inline_list : {false, true}) {
      for (const char *field : {"attributes", "preprocessing"}) {
        auto malformed_metadata = inline_list ? serialized : owned;
        malformed_metadata.object.at("properties").object.at(field) =
            JsonValue::number("0");
        const auto count = numberOfNodes();
        const auto sequence = SgNode::get_globalAstModificationSequence();
        bool rejected = false;
        try {
          SageInterface::deleteAST(
              inline_list ? exprListExpFromTypeJson(malformed_metadata, {})
                          : expressionFromRef(malformed_metadata, {}));
        } catch (const std::runtime_error &error) {
          rejected = std::string(error.what()).find(field) != std::string::npos;
        }
        ROSE_ASSERT(rejected && numberOfNodes() == count);
        ROSE_ASSERT(SgNode::get_globalAstModificationSequence() == sequence);
      }
    }
    for (const char *field :
         {"is_modified", "contains_transformation",
          "contains_transformation_to_surrounding_whitespace",
          "source_range_ends_in_macro_expansion",
          "source_range_is_macro_expansion_fragment"}) {
      for (bool inline_list : {false, true}) {
        for (bool missing : {false, true}) {
          auto malformed_flags = inline_list ? serialized : owned;
          auto &flags = malformed_flags.object.at("flags").object;
          if (missing)
            flags.erase(field);
          else
            flags.at(field) = JsonValue::number("0");
          const auto count = numberOfNodes();
          const auto sequence = SgNode::get_globalAstModificationSequence();
          bool rejected_flags = false;
          try {
            SageInterface::deleteAST(
                inline_list ? exprListExpFromTypeJson(malformed_flags, {})
                            : expressionFromRef(malformed_flags, {}));
          } catch (const std::runtime_error &error) {
            rejected_flags =
                std::string(error.what()) ==
                (missing
                     ? std::string("AST JSON object is missing key: ") + field
                     : "AST JSON value is not a bool");
          }
          ROSE_ASSERT(rejected_flags && numberOfNodes() == count);
          ROSE_ASSERT(SgNode::get_globalAstModificationSequence() == sequence);
        }
      }
    }
    auto malformed = serialized;
    malformed.object.at("properties")
        .object.at("fortran_integer_constant_value") = JsonValue::number("1");
    malformed.object.at("original_expression") = JsonValue::objectValue({});
    const auto lists = SgExprListExp::numberOfNodes();
    bool metadata_rejected = false;
    try {
      (void)exprListExpFromTypeJson(malformed, {});
    } catch (const std::runtime_error &error) {
      metadata_rejected =
          std::string(error.what())
              .find("folded selector value without availability") !=
          std::string::npos;
    }
    ROSE_ASSERT(metadata_rejected && SgExprListExp::numberOfNodes() == lists);
    serialized.object.at("properties").object.erase("preprocessing");
    bool rejected = false;
    try {
      (void)exprListExpFromTypeJson(serialized, {});
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what()).find("preprocessing") != std::string::npos;
    }
    ROSE_ASSERT(rejected);
    SageInterface::deleteAST(original);
  }
}

void requireRejectedInlineListOwnership() {
  using namespace Rose::AstJson;
  PointerMemberTypeSerializationIdentityGuard serialize_members;
  auto *original = SageBuilder::buildExprListExp(SageBuilder::buildIntVal(7));
  auto *borrowed = original->get_expressions().front();
  original->setAttribute("rex_tool_annotation", new AstIntAttribute(73));
  borrowed->setAttribute("rex_tool_annotation", new AstIntAttribute(73));
  auto *borrowed_attributes = borrowed->get_attributeMechanism();
  const JsonValue serialized =
      parseJson(rawTypeOwnedExprListExpJson(original, {}));
  const auto list_count = SgExprListExp::numberOfNodes();
  const auto value_count = SgIntVal::numberOfNodes();
  const auto position_count = Sg_File_Info::numberOfNodes();
  for (bool inline_list : {false, true}) {
    auto malformed = inline_list
                         ? serialized
                         : parseJson(rawTypeOwnedExpressionRef(original, {}));
    malformed.object.at("location") = parseJson(
        R"({"start":{"present":false},"end":{"present":false},"operator":{"present":false}})");
    malformed.object.at("expressions") =
        parseJson(R"([{"node":1},{"node":0}])");
    const auto count = numberOfNodes();
    const auto sequence = SgNode::get_globalAstModificationSequence();
    bool rejected = false;
    try {
      SageInterface::deleteAST(
          inline_list ? exprListExpFromTypeJson(malformed, {{1, borrowed}})
                      : expressionFromRef(malformed, {{1, borrowed}}));
    } catch (const std::runtime_error &error) {
      ROSE_ASSERT(std::string(error.what()) ==
                  "AST JSON expression list contains a null expression");
      rejected = true;
    }
    ROSE_ASSERT(rejected && numberOfNodes() == count);
    ROSE_ASSERT(SgNode::get_globalAstModificationSequence() == sequence);
    ROSE_ASSERT(borrowed->get_parent() == original);
    ROSE_ASSERT(borrowed->get_attributeMechanism() == borrowed_attributes);
  }
  for (bool borrowed_first : {false, true}) {
    JsonValue malformed = serialized;
    if (borrowed_first)
      malformed.object.at("expressions").array.front() =
          parseJson(R"({"node":1})");
    malformed.object.at("expressions")
        .array.push_back(parseJson(R"({"node":0})"));
    for (int iteration = 0; iteration != 100; ++iteration) {
      bool rejected = false;
      try {
        (void)exprListExpFromTypeJson(malformed, {{1, borrowed}});
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what()).find("null expression") !=
                   std::string::npos;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgExprListExp::numberOfNodes() == list_count);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == value_count);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == position_count);
      ROSE_ASSERT(SgNode::isLiveNode(borrowed));
      ROSE_ASSERT(borrowed->get_parent() == original);
      ROSE_ASSERT(borrowed->get_attributeMechanism() == borrowed_attributes);
      ROSE_ASSERT(original->get_expressions().front() == borrowed);
    }
  }
  auto *file = SageBuilder::buildGeneratedSourceFile("rex_type_rollback.cpp");
  std::unique_ptr<SgProject, DeleteFixtureAst> project(file->get_project());
  auto *member_owner = SageBuilder::buildNondefiningClassDeclaration(
      SageBuilder::declaration_ownership::sourceLexical(),
      "RexRollbackMemberOwner", file->get_globalScope());
  const std::unordered_map<const SgNode *, uint64_t> ids{{member_owner, 2}};
  SgType *integer = SageBuilder::buildIntType();
  std::unique_ptr<SgType> source_types[]{
      std::make_unique<SgAutoType>(false, nullptr),
      std::make_unique<SgDeclType>(SageBuilder::buildIntVal(7), integer, false),
      std::make_unique<SgTypeOfType>(SageBuilder::buildIntVal(7), nullptr),
      std::make_unique<SgTypeInt>(),
      std::make_unique<SgTypeOfType>(nullptr, integer),
      std::make_unique<SgFunctionType>(integer, false,
                                       new SgFunctionParameterTypeList()),
      std::make_unique<SgPointerMemberType>(integer, member_owner->get_type()),
      std::make_unique<SgMemberFunctionType>(
          integer, false, new SgFunctionParameterTypeList(),
          member_owner->get_type(), SgMemberFunctionType::e_const),
      std::make_unique<SgModifierType>(member_owner->get_type()),
      std::make_unique<SgUnaryTransformType>(member_owner->get_type(),
                                             SgUnaryTransformType::e_remove_cv),
      std::make_unique<SgTypeBool>(),
      std::make_unique<SgTypeInt>(),
      std::make_unique<SgTypeUnsignedInt>(),
      std::make_unique<SgTypeFloat>(),
      std::make_unique<SgTypeString>(SageBuilder::buildIntVal(29))};
  isSgModifierType(source_types[8].get())->get_typeModifier().setAtomic();
  for (size_t index = 10; index != 14; ++index) {
    auto *kind = SageBuilder::buildIntVal(16);
    source_types[index]->set_type_kind(kind);
    kind->set_parent(source_types[index].get());
  }
  auto *character = isSgTypeString(source_types[14].get());
  character->get_lengthExpression()->set_parent(character);
  auto *selector = SageBuilder::buildIntVal(4);
  selector->set_fortran_integer_constant_value(4);
  selector->set_fortran_integer_constant_value_is_available(true);
  source_types[3]->set_fortran_source_syntax(true);
  source_types[3]->set_type_kind(selector);
  selector->set_parent(source_types[3].get());
  auto delete_array = [](SgArrayType *type) {
    SageInterface::deleteAST(type,
                             SageInterface::DeleteAstMode::kRequireIsolated);
  };
  std::unique_ptr<SgArrayType, decltype(delete_array)> array(
      new SgArrayType(integer, SageBuilder::buildIntVal(3)), delete_array);
  array->get_index()->set_parent(array.get());
  const JsonValue wrappers[]{
      JsonValue{},
      parseJson(rawTypeJson(SageBuilder::buildPointerType(integer), {})),
      parseJson(rawTypeJson(SageBuilder::buildReferenceType(integer), {})),
      parseJson(
          rawTypeJson(SageBuilder::buildRvalueReferenceType(integer), {})),
      parseJson(rawTypeJson(array.get(), {}))};
  JsonValue malformed_signature =
      parseJson(rawTypeJson(source_types[5].get(), {}));
  JsonValue result_array = wrappers[4];
  result_array.object.at("base") =
      parseJson(rawTypeJson(source_types[1].get(), {}));
  JsonValue result_pointer = wrappers[1];
  result_pointer.object.at("base") = result_array;
  malformed_signature.object.at("return_type") = result_pointer;
  JsonValue argument = parseJson(R"({
    "is_pack_expansion":false,
    "source_type_qualification_present":false,
    "source_type_global_qualification":false,
    "source_type_qualification_tokens":[],
    "source_type_elaboration_required":false
  })");
  argument.object["type"] = parseJson(rawTypeJson(source_types[2].get(), {}));
  argument.object.at("type").object.at("base_expression") =
      parseJson(R"({"node":1})");
  malformed_signature.object.at("arguments").array.push_back(argument);
  for (const auto &source_type : source_types) {
    std::unique_ptr<SgTypeExpression> type_expression(
        SageBuilder::buildTypeExpression(source_type.get()));
    JsonValue malformed = serialized;
    auto &children = malformed.object.at("expressions").array;
    children.front() =
        parseJson(rawTypeOwnedExpressionRef(type_expression.get(), ids));
    children.push_back(parseJson(R"({"node":1})"));
    children.push_back(parseJson(R"({"node":0})"));
    JsonValue represented_type =
        children.front().object.at("properties").object.at("represented_type");
    if (source_type.get() == source_types[5].get()) {
      represented_type.object.at("semantic_canonical") = parseJson("true");
      represented_type.object.at("return_type") =
          parseJson(rawTypeJson(source_types[1].get(), {}));
    }
    if (isSgMemberFunctionType(source_type.get()) != nullptr)
      represented_type.object.at("semantic_canonical") = parseJson("true");
    for (const auto &wrapper : wrappers) {
      if (source_type->get_fortran_source_syntax() &&
          wrapper.kind != JsonValue::Kind::Null)
        continue;
      auto &type_json = children.front()
                            .object.at("properties")
                            .object.at("represented_type");
      type_json = represented_type;
      if (wrapper.kind != JsonValue::Kind::Null) {
        type_json = wrapper;
        type_json.object.at("base") = represented_type;
      }
      const auto autos = SgAutoType::numberOfNodes();
      const auto decltypes = SgDeclType::numberOfNodes();
      const auto typeofs = SgTypeOfType::numberOfNodes();
      const auto integers = SgTypeInt::numberOfNodes();
      const auto logicals = SgTypeBool::numberOfNodes();
      const auto unsigned_integers = SgTypeUnsignedInt::numberOfNodes();
      const auto reals = SgTypeFloat::numberOfNodes();
      const auto characters = SgTypeString::numberOfNodes();
      const auto pointers = SgPointerType::numberOfNodes();
      const auto member_pointers = SgPointerMemberType::numberOfNodes();
      const auto canonical_members =
          SgPointerMemberType::canonicalSemanticTypes();
      const auto references = SgReferenceType::numberOfNodes();
      const auto rvalue_references = SgRvalueReferenceType::numberOfNodes();
      const auto arrays = SgArrayType::numberOfNodes();
      const auto functions = SgFunctionType::numberOfNodes();
      const auto member_functions = SgMemberFunctionType::numberOfNodes();
      const auto modifiers = SgModifierType::numberOfNodes();
      const auto modifier_buckets = SgModifierNodes::numberOfNodes();
      const auto parameter_lists = SgFunctionParameterTypeList::numberOfNodes();
      const auto transforms = SgUnaryTransformType::numberOfNodes();
      const auto type_expressions = SgTypeExpression::numberOfNodes();
      const auto values = SgIntVal::numberOfNodes();
      const auto positions = Sg_File_Info::numberOfNodes();
      const auto type_entries =
          *SgNode::get_globalTypeTable()->get_type_table()->get_table();
      const auto function_types =
          SgNode::get_globalFunctionTypeTable()->get_types();
      const NodeMap nodes{{1, borrowed}, {2, member_owner}};
      PointerMemberTypeDeserializationIdentityGuard member_identity;
      FunctionTypeDeserializationIdentityGuard function_identity;
      for (int repeat = 0; repeat != 2; ++repeat) {
        FullTypeDeserializationIdentityGuard outer_identity;
        const bool read_signature =
            source_type.get() == source_types[5].get() &&
            wrapper.kind == JsonValue::Kind::Null && repeat == 1;
        bool rejected = false;
        try {
          if (read_signature)
            (void)typeFromJson(malformed_signature, nodes);
          else
            (void)exprListExpFromTypeJson(malformed, nodes);
        } catch (const std::runtime_error &error) {
          rejected =
              std::string(error.what()) ==
              (read_signature
                   ? "AST JSON typeof operand already has a different lexical "
                     "owner"
                   : "AST JSON expression list contains a null expression");
        }
        ROSE_ASSERT(rejected);
        ROSE_ASSERT(SgAutoType::numberOfNodes() == autos);
        ROSE_ASSERT(SgDeclType::numberOfNodes() == decltypes);
        ROSE_ASSERT(SgTypeOfType::numberOfNodes() == typeofs);
        ROSE_ASSERT(SgTypeInt::numberOfNodes() == integers);
        ROSE_ASSERT(SgTypeBool::numberOfNodes() == logicals);
        ROSE_ASSERT(SgTypeUnsignedInt::numberOfNodes() == unsigned_integers);
        ROSE_ASSERT(SgTypeFloat::numberOfNodes() == reals);
        ROSE_ASSERT(SgTypeString::numberOfNodes() == characters);
        ROSE_ASSERT(SgPointerType::numberOfNodes() == pointers);
        ROSE_ASSERT(SgPointerMemberType::numberOfNodes() == member_pointers);
        ROSE_ASSERT(SgPointerMemberType::canonicalSemanticTypes() ==
                    canonical_members);
        ROSE_ASSERT(SgReferenceType::numberOfNodes() == references);
        ROSE_ASSERT(SgRvalueReferenceType::numberOfNodes() ==
                    rvalue_references);
        ROSE_ASSERT(SgArrayType::numberOfNodes() == arrays);
        ROSE_ASSERT(SgFunctionType::numberOfNodes() == functions);
        ROSE_ASSERT(SgMemberFunctionType::numberOfNodes() == member_functions);
        ROSE_ASSERT(SgModifierType::numberOfNodes() == modifiers);
        ROSE_ASSERT(SgModifierNodes::numberOfNodes() == modifier_buckets);
        ROSE_ASSERT(SgUnaryTransformType::numberOfNodes() == transforms);
        ROSE_ASSERT(SgFunctionParameterTypeList::numberOfNodes() ==
                    parameter_lists);
        ROSE_ASSERT(SgTypeExpression::numberOfNodes() == type_expressions);
        ROSE_ASSERT(SgExprListExp::numberOfNodes() == list_count);
        ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
        ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
        ROSE_ASSERT(
            *SgNode::get_globalTypeTable()->get_type_table()->get_table() ==
            type_entries);
        const auto &current_functions =
            SgNode::get_globalFunctionTypeTable()->get_types();
        const auto compare = function_types.key_comp();
        ROSE_ASSERT(current_functions.size() == function_types.size());
        ROSE_ASSERT(std::equal(current_functions.begin(),
                               current_functions.end(), function_types.begin(),
                               [&compare](const auto &left, const auto &right) {
                                 return left.second == right.second &&
                                        !compare(left.first, right.first) &&
                                        !compare(right.first, left.first);
                               }));
        ROSE_ASSERT(nodes.at(1) == borrowed && SgNode::isLiveNode(borrowed));
        ROSE_ASSERT(borrowed->get_parent() == original);
        ROSE_ASSERT(borrowed->get_attributeMechanism() == borrowed_attributes);
        ROSE_ASSERT(original->get_expressions().front() == borrowed);
        ROSE_ASSERT(selector->get_parent() == source_types[3].get());
        if (source_type->get_fortran_source_syntax()) {
          SgType *restored = typeFromJson(represented_type, {});
          ROSE_ASSERT(restored != source_type.get());
          ROSE_ASSERT(restored->get_fortran_source_syntax());
          SageInterface::deleteAST(
              restored, SageInterface::DeleteAstMode::kRequireIsolated);
          ROSE_ASSERT(SgTypeInt::numberOfNodes() == integers);
          ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
          ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
        }
      }
    }
  }
  const NodeMap member_nodes{{2, member_owner}};
  std::unique_ptr<SgTypeExpression> borrowed_type_expression(
      SageBuilder::buildTypeExpression(member_owner->get_type()));
  auto *canonical_member =
      SgPointerMemberType::createType(integer, member_owner->get_type());
  const auto canonical_json = parseJson(rawTypeJson(canonical_member, ids));
  SageInterface::deleteAST(canonical_member,
                           SageInterface::DeleteAstMode::kRequireIsolated);
  JsonValue borrowed_wrappers[12];
  for (size_t index = 0; index != 3; ++index) {
    borrowed_wrappers[index] = wrappers[index + 1];
    borrowed_wrappers[index].object.at("base") =
        parseJson(rawTypeJson(member_owner->get_type(), ids));
  }
  borrowed_wrappers[3] = canonical_json;
  borrowed_wrappers[4] = parseJson(rawTypeJson(source_types[7].get(), ids));
  borrowed_wrappers[4].object.at("semantic_canonical") = parseJson("true");
  borrowed_wrappers[5] = parseJson(rawTypeJson(source_types[8].get(), ids));
  borrowed_wrappers[6] = parseJson(rawTypeJson(source_types[9].get(), ids));
  for (size_t index = 0; index != 5; ++index)
    borrowed_wrappers[7 + index] =
        parseJson(rawTypeJson(source_types[10 + index].get(), ids));
  auto *borrowed_base = member_owner->get_type();
  const bool original_modified = borrowed_base->get_isModified();
  for (const auto &type_json : borrowed_wrappers) {
    PointerMemberTypeDeserializationIdentityGuard member_identity;
    FunctionTypeDeserializationIdentityGuard function_identity;
    JsonValue malformed = serialized;
    auto &children = malformed.object.at("expressions").array;
    children.front() = parseJson(
        rawTypeOwnedExpressionRef(borrowed_type_expression.get(), ids));
    children.front().object.at("properties").object.at("represented_type") =
        type_json;
    children.push_back(parseJson(R"({"node":0})"));
    for (bool cached : {false, true}) {
      if (cached) {
        SgType *restored = nullptr;
        for (bool modified : {false, true}) {
          borrowed_base->set_isModified(modified);
          auto *read = typeFromJson(type_json, member_nodes);
          ROSE_ASSERT(read != nullptr);
          if (restored != nullptr)
            ROSE_ASSERT(read == restored);
          restored = read;
          ROSE_ASSERT(borrowed_base->get_isModified() == modified);
          ROSE_ASSERT(typeFromJson(type_json, member_nodes) == restored);
          ROSE_ASSERT(borrowed_base->get_isModified() == modified);
        }
      }
      auto *base = member_owner->get_type();
      auto *pointer = base->get_ptr_to();
      auto *reference = base->get_ref_to();
      auto *rvalue_reference = base->get_rvalue_ref_to();
      const auto pointers = SgPointerType::numberOfNodes();
      const auto references = SgReferenceType::numberOfNodes();
      const auto rvalue_references = SgRvalueReferenceType::numberOfNodes();
      const auto member_pointers = SgPointerMemberType::numberOfNodes();
      const auto canonical_members =
          SgPointerMemberType::canonicalSemanticTypes();
      const auto expressions = SgTypeExpression::numberOfNodes();
      const auto member_functions = SgMemberFunctionType::numberOfNodes();
      const auto function_entries =
          SgNode::get_globalFunctionTypeTable()->size();
      const auto modifiers = SgModifierType::numberOfNodes();
      const auto modifier_buckets = SgModifierNodes::numberOfNodes();
      auto *modifier_head = base->get_modifiers();
      const auto transforms = SgUnaryTransformType::numberOfNodes();
      const auto positions = Sg_File_Info::numberOfNodes();
      const auto entries =
          *SgNode::get_globalTypeTable()->get_type_table()->get_table();
      for (int repeat = 0; repeat != 2; ++repeat) {
        const bool modified = repeat != 0;
        base->set_isModified(modified);
        bool rejected = false;
        try {
          (void)exprListExpFromTypeJson(malformed, member_nodes);
        } catch (const std::runtime_error &error) {
          if (std::string(error.what()) !=
              "AST JSON expression list contains a null expression")
            throw;
          rejected = true;
        }
        ROSE_ASSERT(rejected);
        ROSE_ASSERT(base->get_isModified() == modified);
        ROSE_ASSERT(base->get_ptr_to() == pointer);
        ROSE_ASSERT(base->get_ref_to() == reference);
        ROSE_ASSERT(base->get_rvalue_ref_to() == rvalue_reference);
        ROSE_ASSERT(SgPointerType::numberOfNodes() == pointers);
        ROSE_ASSERT(SgReferenceType::numberOfNodes() == references);
        ROSE_ASSERT(SgRvalueReferenceType::numberOfNodes() ==
                    rvalue_references);
        ROSE_ASSERT(SgPointerMemberType::numberOfNodes() == member_pointers);
        ROSE_ASSERT(SgPointerMemberType::canonicalSemanticTypes() ==
                    canonical_members);
        ROSE_ASSERT(SgTypeExpression::numberOfNodes() == expressions);
        ROSE_ASSERT(SgMemberFunctionType::numberOfNodes() == member_functions);
        ROSE_ASSERT(SgNode::get_globalFunctionTypeTable()->size() ==
                    function_entries);
        ROSE_ASSERT(SgModifierType::numberOfNodes() == modifiers);
        ROSE_ASSERT(SgModifierNodes::numberOfNodes() == modifier_buckets);
        ROSE_ASSERT(base->get_modifiers() == modifier_head);
        ROSE_ASSERT(SgUnaryTransformType::numberOfNodes() == transforms);
        ROSE_ASSERT(SgExprListExp::numberOfNodes() == list_count);
        ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
        ROSE_ASSERT(
            *SgNode::get_globalTypeTable()->get_type_table()->get_table() ==
            entries);
      }
    }
  }
  borrowed_base->set_isModified(original_modified);
  {
    auto *component = SageBuilder::buildFloatType(SageBuilder::buildIntVal(16));
    std::unique_ptr<SgTypeComplex, DeleteFixtureAst> prototype(
        SageBuilder::buildComplexType(component));
    std::unique_ptr<SgExprListExp, DeleteFixtureAst> list(
        SageBuilder::buildExprListExp(
            SageBuilder::buildTypeExpression(prototype.get())));
    const auto type_json = parseJson(rawTypeJson(prototype.get(), {}));
    auto malformed = parseJson(rawTypeOwnedExprListExpJson(list.get(), {}));
    malformed.object.at("expressions")
        .array.push_back(parseJson(R"({"node":0})"));
    for (bool cached : {false, true}) {
      SgType *existing = cached ? typeFromJson(type_json, {}) : nullptr;
      ROSE_ASSERT(SgTypeComplex::findCanonicalSemanticType(component) ==
                  existing);
      const auto complexes = SgTypeComplex::numberOfNodes();
      const auto expressions = SgTypeExpression::numberOfNodes();
      const auto lists = SgExprListExp::numberOfNodes();
      const auto positions = Sg_File_Info::numberOfNodes();
      for (int repeat = 0; repeat != 2; ++repeat) {
        bool rejected = false;
        try {
          (void)exprListExpFromTypeJson(malformed, {});
        } catch (const std::runtime_error &error) {
          if (std::string(error.what()) !=
              "AST JSON expression list contains a null expression")
            throw;
          rejected = true;
        }
        ROSE_ASSERT(rejected);
        ROSE_ASSERT(SgTypeComplex::numberOfNodes() == complexes);
        ROSE_ASSERT(SgTypeExpression::numberOfNodes() == expressions);
        ROSE_ASSERT(SgExprListExp::numberOfNodes() == lists);
        ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
        ROSE_ASSERT(SgTypeComplex::findCanonicalSemanticType(component) ==
                    existing);
        if (cached)
          ROSE_ASSERT(typeFromJson(type_json, {}) == existing);
      }
    }
    auto *canonical = SgTypeComplex::findCanonicalSemanticType(component);
    ROSE_ASSERT(canonical != nullptr && canonical != prototype.get());
    SageInterface::deleteAST(canonical,
                             SageInterface::DeleteAstMode::kRequireIsolated);
    ROSE_ASSERT(SgTypeComplex::findCanonicalSemanticType(component) == nullptr);
    {
      std::unique_ptr<SgTypeComplex> recreated(
          SgTypeComplex::createType(component));
      ROSE_ASSERT(SgTypeComplex::findCanonicalSemanticType(component) ==
                  recreated.get());
    }
    ROSE_ASSERT(SgTypeComplex::findCanonicalSemanticType(component) == nullptr);
    {
      std::unique_ptr<SgTypeImaginary> imaginary(
          SgTypeImaginary::createType(component));
      ROSE_ASSERT(SgTypeImaginary::findCanonicalSemanticType(component) ==
                  imaginary.get());
    }
    ROSE_ASSERT(SgTypeImaginary::findCanonicalSemanticType(component) ==
                nullptr);
  }
  const auto member_json = parseJson(rawTypeJson(source_types[6].get(), ids));
  std::unique_ptr<SgPointerMemberType, DeleteFixtureAst> restored_member;
  {
    PointerMemberTypeDeserializationIdentityGuard member_identity;
    restored_member.reset(
        isSgPointerMemberType(typeFromJson(member_json, member_nodes)));
    ROSE_ASSERT(restored_member != nullptr &&
                restored_member.get() != source_types[6].get());
    ROSE_ASSERT(restored_member->get_class_type() == member_owner->get_type());
    ROSE_ASSERT(typeFromJson(member_json, member_nodes) ==
                restored_member.get());
    restored_member->set_source_class_type_is_unqualified_injected_name(true);
    bool rejected = false;
    try {
      (void)typeFromJson(member_json, member_nodes);
    } catch (const std::runtime_error &error) {
      rejected = std::string(error.what()) ==
                 "AST JSON pointer-member identity no longer names its exact "
                 "restored type graph";
    }
    ROSE_ASSERT(rejected);
    ROSE_ASSERT(
        restored_member->get_source_class_type_is_unqualified_injected_name());
    restored_member->set_source_class_type_is_unqualified_injected_name(false);
  }
  restored_member.reset();
  canonical_member =
      SgPointerMemberType::createType(integer, member_owner->get_type());
  delete canonical_member;
  ROSE_ASSERT(SgPointerMemberType::findCanonicalSemanticType(
                  integer, member_owner->get_type()) == nullptr);
  canonical_member =
      SgPointerMemberType::createType(integer, member_owner->get_type());
  {
    std::unique_ptr<SgPointerMemberType> noncanonical(
        new SgPointerMemberType(integer, member_owner->get_type()));
    ROSE_ASSERT(
        !SgPointerMemberType::isCanonicalSemanticType(noncanonical.get()));
  }
  ROSE_ASSERT(SgPointerMemberType::findCanonicalSemanticType(
                  integer, member_owner->get_type()) == canonical_member);
  canonical_member->set_fortran_source_syntax(true);
  {
    PointerMemberTypeDeserializationIdentityGuard member_identity;
    bool rejected = false;
    try {
      (void)typeFromJson(canonical_json, member_nodes);
    } catch (const std::runtime_error &error) {
      rejected =
          std::string(error.what()) ==
          "AST JSON canonical semantic pointer-member type has source syntax";
    }
    ROSE_ASSERT(rejected && SgNode::isLiveNode(canonical_member));
    ROSE_ASSERT(canonical_member->get_fortran_source_syntax());
    canonical_member->set_fortran_source_syntax(false);
    ROSE_ASSERT(typeFromJson(canonical_json, member_nodes) == canonical_member);
    ROSE_ASSERT(typeFromJson(canonical_json, member_nodes) == canonical_member);
  }
  SageInterface::deleteAST(original);
}

void requireRejectedNestedExpressionOwnership() {
  using namespace Rose::AstJson;
  auto *sum = SageBuilder::buildAddOp(SageBuilder::buildIntVal(7),
                                      SageBuilder::buildIntVal(9),
                                      SageBuilder::buildIntType());
  auto *original = SageBuilder::buildExprListExp(sum);
  auto *borrowed = sum->get_lhs_operand();
  const JsonValue serialized =
      parseJson(rawTypeOwnedExprListExpJson(original, {}));
  const auto lists = SgExprListExp::numberOfNodes();
  const auto sums = SgAddOp::numberOfNodes();
  const auto values = SgIntVal::numberOfNodes();
  const auto positions = Sg_File_Info::numberOfNodes();
  for (bool borrowed_first : {false, true}) {
    for (bool reject_sibling : {false, true}) {
      JsonValue malformed = serialized;
      auto &properties = malformed.object.at("expressions")
                             .array.front()
                             .object.at("properties");
      if (borrowed_first)
        properties.object.at("lhs_operand") = parseJson(R"({"node":1})");
      if (reject_sibling) {
        // The completed nested expression has already adopted its children
        // when the list rejects a later entry. Borrowed parentage must roll
        // back. A borrowed left operand is rejected even earlier, before the
        // right operand is decoded or either operand is connected.
        malformed.object.at("expressions")
            .array.push_back(parseJson(R"({"node":0})"));
      } else {
        // Reject after decoding the left operand, before connecting either
        // operand to the binary expression, when the right operand loses its
        // required literal field.
        properties.object.at("rhs_operand")
            .object.at("properties")
            .object.erase("lvalue");
      }
      for (int iteration = 0; iteration != 100; ++iteration) {
        bool rejected = false;
        try {
          (void)exprListExpFromTypeJson(malformed, {{1, borrowed}});
        } catch (const std::runtime_error &error) {
          rejected =
              std::string(error.what())
                  .find(borrowed_first   ? "distinct unowned operands"
                        : reject_sibling ? "null expression"
                                         : "lvalue") != std::string::npos;
        }
        ROSE_ASSERT(rejected);
        ROSE_ASSERT(SgExprListExp::numberOfNodes() == lists);
        ROSE_ASSERT(SgAddOp::numberOfNodes() == sums);
        ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
        ROSE_ASSERT(Sg_File_Info::numberOfNodes() == positions);
        ROSE_ASSERT(SgNode::isLiveNode(borrowed));
        ROSE_ASSERT(borrowed->get_parent() == sum);
        ROSE_ASSERT(sum->get_lhs_operand() == borrowed);
      }
    }
  }
  SageInterface::deleteAST(original);
}

void requireRejectedUnaryFactoryOwnership() {
  using namespace Rose::AstJson;
  auto *original =
      SageBuilder::buildMinusOp(SageBuilder::buildIntVal(7),
                                SageBuilder::buildIntType(), SgUnaryOp::prefix);
  const JsonValue serialized =
      parseJson(rawTypeOwnedExpressionRef(original, {}));
  const auto unary_count = SgMinusOp::numberOfNodes();
  const auto value_count = SgIntVal::numberOfNodes();
  const auto position_count = Sg_File_Info::numberOfNodes();
  for (bool missing : {false, true}) {
    JsonValue malformed = serialized;
    auto &properties = malformed.object.at("properties").object;
    if (missing)
      properties.erase("mode");
    else
      properties.at("mode") = parseJson("9223372036854775807");
    for (int iteration = 0; iteration != 100; ++iteration) {
      bool rejected = false;
      try {
        (void)expressionFromRef(malformed, {});
      } catch (const std::runtime_error &error) {
        rejected = std::string(error.what()).find("mode") != std::string::npos;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgMinusOp::numberOfNodes() == unary_count);
      ROSE_ASSERT(SgIntVal::numberOfNodes() == value_count);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == position_count);
    }
  }
  SageInterface::deleteAST(original);
}

void requireRejectedLeafFactoryOwnership() {
  using namespace Rose::AstJson;
  const auto properties = parseJson(
      "{\"role\":" +
      std::to_string(SgNullExpression::e_null_expression_syntactic_absence) +
      ",\"fortran_integer_constant_value_is_available\":false,"
      "\"fortran_integer_constant_value\":0,\"lvalue\":false,"
      "\"need_paren\":false,\"global_qualified_name\":false,"
      "\"semantic_wrapper_mask\":0}");
  NodeRecord record;
  record.kind = "SgNullExpression";
  auto expression_flags_storage = std::make_unique<SgNullExpression>();
  auto &expression_flags = *expression_flags_storage;
  record.flags = parseJson(rawNodeFlagsJson(&expression_flags));
  record.location = parseJson(
      R"({"start":{"present":false},"end":{"present":false},"operator":{"present":false}})");
  record.properties = properties;
  {
    std::unique_ptr<SgNode> valid(createNodeFromRecord(record, nullptr));
    ROSE_ASSERT(isSgNullExpression(valid.get()) != nullptr);
  }
  const size_t node_count = SgNullExpression::numberOfNodes();
  const size_t position_count = Sg_File_Info::numberOfNodes();
  auto require_rejection = [&] {
    for (int iteration = 0; iteration != 100; ++iteration) {
      bool rejected = false;
      try {
        std::unique_ptr<SgNode> unexpected(
            createNodeFromRecord(record, nullptr));
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected);
      ROSE_ASSERT(SgNullExpression::numberOfNodes() == node_count);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == position_count);
    }
  };
  for (const auto &property : properties.object) {
    for (bool missing : {false, true}) {
      record.properties = properties;
      if (missing)
        record.properties.object.erase(property.first);
      else
        record.properties.object.at(property.first) = parseJson("null");
      require_rejection();
    }
  }
  record.properties = properties;
  record.properties.object.at("role") = parseJson("9223372036854775807");
  require_rejection();
  for (const char *invalid :
       {"4294967296", "9223372036854775807", "-1", "32"}) {
    record.properties = properties;
    record.properties.object.at("semantic_wrapper_mask") = parseJson(invalid);
    require_rejection();
  }
}

void requirePhysicalFileIdentity() {
  using namespace Rose::AstJson;
  auto require_rejection = [](const JsonValue &malformed,
                              const char *diagnostic) {
    const auto positions = Sg_File_Info::numberOfNodes();
    bool rejected = false;
    try {
      std::unique_ptr<Sg_File_Info> unexpected(
          buildFileInfo(malformed, nullptr));
    } catch (const std::runtime_error &error) {
      if (diagnostic != nullptr &&
          std::string(error.what()).find(diagnostic) == std::string::npos)
        throw;
      rejected = true;
    }
    ROSE_ASSERT(rejected && Sg_File_Info::numberOfNodes() == positions);
  };
  require_rejection(parseJson(R"({"present":false,"raw_line":1})"),
                    "absent file info has a payload");
  std::unique_ptr<Sg_File_Info> original(
      Sg_File_Info::generateDefaultFileInfoForTransformationNode());
  const JsonValue serialized = parseJson(rawFileInfoJson(original.get()));
  const auto position_fields = fileInfoFieldsFromJson(serialized);
  ROSE_ASSERT(position_fields &&
              position_fields->file_id == original->get_file_id() &&
              position_fields->line == original->get_line() &&
              position_fields->column == original->get_col());
  std::unique_ptr<Sg_File_Info> restored(buildFileInfo(serialized, nullptr));
  ROSE_ASSERT(restored != nullptr);
  ROSE_ASSERT(restored->get_physical_file_id() ==
              original->get_physical_file_id());
  ROSE_ASSERT(restored->get_raw_file_id() == original->get_raw_file_id());
  ROSE_ASSERT(restored->get_physical_file_occurrence_id() ==
              original->get_physical_file_occurrence_id());
  for (const char *field : {"file_id", "raw_file_id", "physical_file_id",
                            "physical_internal_file_id", "raw_line",
                            "raw_column", "physical_line", "line", "column"}) {
    for (const char *invalid : {"missing", "2147483648", "-2147483649"}) {
      JsonValue malformed = serialized;
      if (std::string(invalid) == "missing")
        malformed.object.erase(field);
      else
        malformed.object[field] = parseJson(invalid);
      require_rejection(malformed, field);
    }
  }

  std::unique_ptr<Sg_File_Info> named(new Sg_File_Info("NULL_FILE", 1, 1));
  ROSE_ASSERT(named->get_raw_file_id() >= 0);
  named->set_physical_file_occurrence_id(23);
  const JsonValue named_serialized = parseJson(rawFileInfoJson(named.get()));
  std::unique_ptr<Sg_File_Info> named_restored(
      buildFileInfo(named_serialized, nullptr));
  ROSE_ASSERT(named_restored->get_raw_file_id() == named->get_raw_file_id());
  ROSE_ASSERT(named_restored->get_physical_file_id() ==
              named->get_physical_file_id());
  ROSE_ASSERT(named_restored->get_physical_file_occurrence_id() == 23);
  {
    auto original_statement_storage = std::make_unique<SgNullStatement>();
    auto &original_statement = *original_statement_storage;
    NodeRecord first;
    first.id = 1;
    first.kind = "SgNullStatement";
    first.flags = parseJson(rawNodeFlagsJson(&original_statement));
    first.properties = parseJson(rawNodeProperties(&original_statement, {}));
    first.location = parseJson(rawLocationJson(&original_statement));
    first.location.object.at("start") = named_serialized;
    NodeRecord second = first;
    second.id = 2;
    second.location.object.at("start").object.at("raw_line") =
        JsonValue::number("2147483648");
    NodeMap nodes;
    const auto count = numberOfNodes();
    const auto sequence = SgNode::get_globalAstModificationSequence();
    bool rejected = false;
    try {
      rebuildConstructorOnlyNodes(recordGraph({first, second}), nodes);
    } catch (const std::runtime_error &error) {
      ROSE_ASSERT(std::string(error.what()) ==
                  "AST JSON file info raw_line is out of range");
      rejected = true;
    }
    ROSE_ASSERT(rejected && nodes.empty() && numberOfNodes() == count);
    ROSE_ASSERT(SgNode::get_globalAstModificationSequence() == sequence);
  }
  for (const char *field : {"filename", "line", "column"}) {
    JsonValue malformed = named_serialized;
    malformed.object.at(field) = std::string(field) == "filename"
                                     ? JsonValue::string("wrong.cpp")
                                     : parseJson("0");
    require_rejection(malformed, "effective coordinates disagree");
  }
  for (bool compiler_generated : {false, true}) {
    for (bool frontend_specific : {false, true}) {
      if (compiler_generated)
        named->setCompilerGenerated();
      else
        named->unsetCompilerGenerated();
      if (frontend_specific)
        named->setFrontendSpecific();
      else
        named->unsetFrontendSpecific();
      const auto fields =
          fileInfoFieldsFromJson(parseJson(rawFileInfoJson(named.get())));
      ROSE_ASSERT(fields && fields->file_id == named->get_file_id() &&
                  fields->line == named->get_line() &&
                  fields->column == named->get_col());
      std::unique_ptr<Sg_File_Info> classified(
          buildFileInfo(parseJson(rawFileInfoJson(named.get())), nullptr));
      ROSE_ASSERT(classified->get_file_id() == named->get_file_id());
      ROSE_ASSERT(classified->get_raw_file_id() == named->get_raw_file_id());
      if (compiler_generated) {
        named->set_physical_file_id(Sg_File_Info::COMPILER_GENERATED_FILE_ID);
        std::unique_ptr<Sg_File_Info> semantic(
            buildFileInfo(parseJson(rawFileInfoJson(named.get())), nullptr));
        ROSE_ASSERT(semantic->isCompilerGenerated());
        ROSE_ASSERT(semantic->get_physical_file_id() ==
                    Sg_File_Info::COMPILER_GENERATED_FILE_ID);
        ROSE_ASSERT(semantic->get_raw_line() == named->get_raw_line());
        named->set_physical_file_id(named_restored->get_physical_file_id());
      }
    }
  }
  for (bool unresolved_copy : {false, true}) {
    JsonValue malformed = named_serialized;
    malformed.object.at("file_id") =
        JsonValue::number(std::to_string(Sg_File_Info::COPY_FILE_ID));
    if (unresolved_copy) {
      malformed.object.at("raw_file_id") =
          JsonValue::number(std::to_string(Sg_File_Info::COPY_FILE_ID));
      malformed.object.at("raw_filename") = JsonValue::string(
          Sg_File_Info::getFilenameFromID(Sg_File_Info::COPY_FILE_ID));
    }
    require_rejection(malformed, unresolved_copy ? "raw_file_id" : "file_id");
  }
  for (int raw_file_id :
       {Sg_File_Info::COPY_FILE_ID, Sg_File_Info::NULL_FILE_ID}) {
    JsonValue malformed = named_serialized;
    malformed.object.at("raw_file_id") =
        JsonValue::number(std::to_string(raw_file_id));
    malformed.object.at("raw_filename") =
        JsonValue::string(Sg_File_Info::getFilenameFromID(raw_file_id));
    malformed.object.at("compiler_generated") = JsonValue::boolean(true);
    malformed.object.at("frontend_specific") = JsonValue::boolean(true);
    require_rejection(malformed, "raw_file_id");
  }
  for (const char *field : {"raw_file_id", "physical_internal_file_id"}) {
    JsonValue contradictory = named_serialized;
    contradictory.object.at(field) = parseJson("-2");
    require_rejection(contradictory, nullptr);
  }

  const auto position_count = Sg_File_Info::numberOfNodes();
  const std::string rejected_filename =
      "rex_ast_json_rejected_position_unregistered.cpp";
  const auto &names = Sg_File_Info::get_nametofileid_map();
  const auto &ids = Sg_File_Info::get_fileidtoname_map();
  ROSE_ASSERT(names.find(rejected_filename) == names.end());
  const size_t name_count = names.size(), id_count = ids.size();
  for (const char *field :
       {"compiler_generated", "transformation", "frontend_specific", "shared",
        "source_position_unavailable_in_frontend", "comment_or_directive",
        "token", "default_argument", "implicit_cast",
        "output_in_code_generation"}) {
    for (int repeat = 0; repeat < 25; ++repeat) {
      JsonValue malformed = serialized;
      malformed.object.at("raw_filename") =
          parseJson(jsonString(rejected_filename));
      malformed.object.erase(field);
      const std::string diagnostic = std::string("missing key: ") + field;
      require_rejection(malformed, diagnostic.c_str());
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == position_count);
      ROSE_ASSERT(names.size() == name_count && ids.size() == id_count);
      ROSE_ASSERT(names.find(rejected_filename) == names.end());
    }
  }

  for (const char *field : {"source_sequence", "physical_file_occurrence_id"}) {
    for (const char *invalid : {"missing", "-1", "4294967296"}) {
      JsonValue malformed = serialized;
      if (std::string(invalid) == "missing")
        malformed.object.erase(field);
      else
        malformed.object.at(field) = parseJson(invalid);
      require_rejection(malformed, field);
      ROSE_ASSERT(Sg_File_Info::numberOfNodes() == position_count);
    }
  }
  JsonValue largest_sequence = serialized;
  largest_sequence.object.at("source_sequence") = parseJson("4294967295");
  largest_sequence.object.at("physical_file_occurrence_id") =
      parseJson("4294967295");
  std::unique_ptr<Sg_File_Info> largest(
      buildFileInfo(largest_sequence, nullptr));
  ROSE_ASSERT(largest->get_source_sequence_number() == 4294967295u);
  ROSE_ASSERT(largest->get_physical_file_occurrence_id() == 4294967295u);
}

void requireAddressOperandForm() {
  using namespace Rose::AstJson;
  SgType *pointer = SageBuilder::buildPointerType(SageBuilder::buildIntType());
  JsonValue properties =
      parseJson("{\"mode\":" + std::to_string(SgUnaryOp::prefix) +
                ",\"address_operand_form\":1}");
  const auto count = SgAddressOfOp::numberOfNodes();
  const auto values = SgIntVal::numberOfNodes();
  for (auto form : {SgAddressOfOp::e_address_operand_object,
                    SgAddressOfOp::e_address_operand_qualified_id}) {
    properties.object.at("address_operand_form") =
        parseJson(std::to_string(form));
    auto *operand = SageBuilder::buildIntVal_nfi(7, "7");
    const auto fields =
        unaryConstructionFieldsFromJson(properties, "SgAddressOfOp", {});
    auto *address = isSgAddressOfOp(
        constructUnaryOp("SgAddressOfOp", operand, fields, pointer));
    ROSE_ASSERT(address != nullptr &&
                address->get_address_operand_form() == form);
    ROSE_ASSERT(address->get_type() == pointer);
    ROSE_ASSERT(address->get_mode() == SgUnaryOp::prefix);
    ROSE_ASSERT(address->get_operand_i() == operand);
    ROSE_ASSERT(operand->get_parent() == address);
    SageInterface::deleteAST(address);
  }
  ROSE_ASSERT(SgAddressOfOp::numberOfNodes() == count);
  ROSE_ASSERT(SgIntVal::numberOfNodes() == values);
  for (const char *invalid : {"null", "0", "3", "-1", "true"}) {
    auto malformed = properties;
    malformed.object.at("address_operand_form") = parseJson(invalid);
    for (int attempt = 0; attempt != 100; ++attempt) {
      bool rejected = false;
      try {
        (void)unaryConstructionFieldsFromJson(malformed, "SgAddressOfOp", {});
      } catch (const std::runtime_error &) {
        rejected = true;
      }
      ROSE_ASSERT(rejected && SgAddressOfOp::numberOfNodes() == count);
    }
  }
  properties.object.erase("address_operand_form");
  bool rejected = false;
  try {
    (void)unaryConstructionFieldsFromJson(properties, "SgAddressOfOp", {});
  } catch (const std::runtime_error &) {
    rejected = true;
  }
  ROSE_ASSERT(rejected && SgAddressOfOp::numberOfNodes() == count);
}

